#[derive(Clone, Default)]
struct DatabaseAggregateLoadCounter {
  enabled: Arc<AtomicBool>,
  calls: Arc<AtomicUsize>,
}

impl<S> tracing_subscriber::Layer<S> for DatabaseAggregateLoadCounter
where
  S: Subscriber,
{
  fn on_new_span(&self, attrs: &Attributes<'_>, _id: &tracing::span::Id, _context: Context<'_, S>) {
    if self.enabled.load(Ordering::Relaxed) && attrs.metadata().name() == "get_record_with_lifecycle" {
      self.calls.fetch_add(1, Ordering::Relaxed);
    }
  }
}

fn legacy_database_fixture_update(name: &str) -> Vec<u8> {
  let decoded = WorkspaceDecoder::new(WorkspaceImportLimits::default())
    .decode_path(
      Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../workspace_import/tests/fixtures")
        .join(name),
    )
    .expect("decode canonical legacy workspace fixture");
  decoded
    .documents
    .into_iter()
    .find_map(|document| {
      let update = match document.content {
        DecodedDocumentContent::YjsV1(update) => update,
        DecodedDocumentContent::SnapshotBlocks(blocks) => {
          yjs::snapshot_blocks_to_yjs(&blocks).expect("encode fixture snapshot blocks")
        }
        DecodedDocumentContent::MarkdownUtf8(_) => return None,
      };
      let blocks =
        yjs::extract_legacy_database_blocks(&update).expect("inspect canonical fixture for legacy Database blocks");
      (!blocks.is_empty()).then_some(update)
    })
    .expect("fixture document with a legacy Database")
}

async fn persist_legacy_database_document(
  pool: &PgPool,
  workspace_id: Uuid,
  actor_id: Uuid,
  title: &str,
  update: Vec<u8>,
) -> Uuid {
  let document_id = Uuid::new_v4();
  sqlx::query(
    "INSERT INTO docs (id, external_id, workspace_id, title, is_workspace_root, created_by, updated_by) \
     VALUES ($1, $1::text, $2, $3, false, $4, $4)",
  )
  .bind(document_id)
  .bind(workspace_id)
  .bind(title)
  .bind(actor_id)
  .execute(pool)
  .await
  .expect("persist legacy migration document metadata");
  DocService::new(Arc::new(SqlxDocStore::new(pool.clone())))
    .push_update_raw(workspace_id, document_id, update, DocSpaceKind::Workspace)
    .await
    .expect("persist legacy migration document state");
  document_id
}

struct FailingReminderQueue;

#[async_trait::async_trait]
impl DatabaseJobEnqueuer for FailingReminderQueue {
  async fn enqueue(&self, _queue: &str, _job_name: &str, _data: Value, _delay_ms: i64) -> Result<String, String> {
    Err("notification queue unavailable".to_string())
  }
}

#[async_trait::async_trait]
impl DatabaseJobEnqueuer for DatabaseRedisQueue {
  async fn enqueue(&self, queue: &str, job_name: &str, data: Value, delay_ms: i64) -> Result<String, String> {
    self
      .queue
      .enqueue(
        queue,
        job_name,
        data,
        JobOptions {
          delay_ms: (delay_ms > 0).then_some(delay_ms),
          max_attempts: 3,
          ..Default::default()
        },
      )
      .await
      .map_err(|error| error.to_string())
  }
}

/// Admit intentional content-only SQL fixtures against the same immutable sources
/// as native writers. This does not grant managed definition/lifecycle bypasses.
async fn execute_catalog_pinned_content_fixture<'q>(
  pool: &PgPool,
  query: sqlx::query::Query<'q, sqlx::Postgres, sqlx::postgres::PgArguments>,
) -> Result<sqlx::postgres::PgQueryResult, sqlx::Error> {
  let mut tx = pool.begin().await?;
  pin_catalog_content_fixture(&mut tx).await?;
  let result = query.execute(&mut *tx).await?;
  tx.commit().await?;
  Ok(result)
}

async fn pin_catalog_content_fixture(tx: &mut sqlx::Transaction<'_, sqlx::Postgres>) -> Result<(), sqlx::Error> {
  sqlx::query("SELECT set_config('myoxus.admitted_database_sources',$1,true)")
    .bind(
      serde_json::to_string(&crate::helpers::database_starter_catalog().admitted_sources())
        .expect("validated fixture catalog"),
    )
    .execute(&mut **tx)
    .await?;
  Ok(())
}

fn gql_data<'a>(response: &'a Value, path: &[&str]) -> &'a Value {
  if let Some(errors) = response.get("errors") {
    panic!("unexpected GraphQL errors: {errors:#}");
  }
  let mut cursor = response.get("data").expect("GraphQL response must include data");
  for segment in path {
    cursor = cursor
      .get(*segment)
      .unwrap_or_else(|| panic!("missing GraphQL data segment {segment} in {response:#}"));
  }
  cursor
}

fn gql_errors(response: &Value) -> Vec<Value> {
  response
    .get("errors")
    .and_then(|errors| errors.as_array())
    .cloned()
    .unwrap_or_default()
}

fn assert_database_conflict(response: &Value, expected_code: &str) -> Value {
  let errors = gql_errors(response);
  assert_eq!(
    errors.len(),
    1,
    "expected exactly one {expected_code} error: {response:#}"
  );
  let extensions = &errors[0]["extensions"];
  assert_eq!(
    extensions["code"], expected_code,
    "unexpected conflict family: {response:#}"
  );
  serde_json::from_str(
    extensions["latestState"]
      .as_str()
      .expect("database conflict must expose JSON latestState"),
  )
  .expect("database latestState must be valid JSON")
}

// Always clean these persisted Database fixtures, then propagate the original
// assertion panic. Cleanup completion is asserted instead of trusting a helper
// that also serves older best-effort fixtures.
async fn finish_database_fixture(
  pool: &sqlx::PgPool,
  user_ids: &[Uuid],
  body: Result<(), Box<dyn std::any::Any + Send>>,
) {
  helpers::cleanup_users(pool, user_ids).await;
  let remaining: i64 = sqlx::query_scalar("SELECT count(*) FROM users WHERE id = ANY($1)")
    .bind(user_ids)
    .fetch_one(pool)
    .await
    .expect("Database fixture cleanup readback");
  assert_eq!(
    remaining, 0,
    "Database fixture users must be removed even after an assertion panic"
  );
  let workspaces: i64 = sqlx::query_scalar("SELECT count(*) FROM workspaces WHERE owner_user_id = ANY($1)")
    .bind(user_ids)
    .fetch_one(pool)
    .await
    .expect("Database fixture workspace cleanup readback");
  assert_eq!(
    workspaces, 0,
    "Database fixture workspaces must be removed even after an assertion panic"
  );
  if let Err(panic) = body {
    resume_unwind(panic);
  }
}

async fn gql_csv_upload(
  app: &axum::Router,
  session_id: Uuid,
  operations: Value,
  file_name: &str,
  content: &[u8],
) -> Value {
  let boundary = "X-BOUNDARY-WORKSPACE-DATABASE-CSV";
  let map = json!({ "0": ["variables.file"] }).to_string();
  let mut body = Vec::new();
  body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
  body.extend_from_slice(b"Content-Disposition: form-data; name=\"operations\"\r\n\r\n");
  body.extend_from_slice(operations.to_string().as_bytes());
  body.extend_from_slice(b"\r\n");
  body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
  body.extend_from_slice(b"Content-Disposition: form-data; name=\"map\"\r\n\r\n");
  body.extend_from_slice(map.as_bytes());
  body.extend_from_slice(b"\r\n");
  body.extend_from_slice(format!("--{boundary}\r\n").as_bytes());
  body
    .extend_from_slice(format!("Content-Disposition: form-data; name=\"0\"; filename=\"{file_name}\"\r\n").as_bytes());
  body.extend_from_slice(b"Content-Type: text/csv\r\n\r\n");
  body.extend_from_slice(content);
  body.extend_from_slice(b"\r\n");
  body.extend_from_slice(format!("--{boundary}--\r\n").as_bytes());

  let response = app
    .clone()
    .oneshot(
      Request::builder()
        .method("POST")
        .uri("/graphql")
        .header("content-type", format!("multipart/form-data; boundary={boundary}"))
        .header("cookie", format!("affine_session={session_id}"))
        .body(Body::from(body))
        .expect("multipart workspace database CSV request"),
    )
    .await
    .expect("multipart workspace database CSV response");
  let bytes = response
    .into_body()
    .collect()
    .await
    .expect("multipart workspace database CSV body")
    .to_bytes();
  serde_json::from_slice(&bytes).expect("multipart workspace database CSV JSON")
}

