async fn seed_usable_template(
  pool: &sqlx::PgPool,
  workspace_id: Uuid,
  template_doc_id: Uuid,
  slug: &str,
  title: &str,
) -> Uuid {
  let store = SqlxTemplateRegistryStore::new(pool.clone());
  let template_id = Uuid::new_v4();
  let revision_id = Uuid::new_v4();
  let now = Utc::now();
  store
    .create_catalog_entry(&TemplateCatalogEntry {
      archived_at: None,
      builder_version: None,
      category: Some("project".to_string()),
      created_at: now,
      description: Some("P8 hardening template".to_string()),
      id: template_id,
      min_client_version: 0,
      slug: slug.to_string(),
      source: TemplateSource::Bundle,
      status: TemplateStatus::Active,
      tags: Vec::new(),
      title: title.to_string(),
      updated_at: now,
    })
    .await
    .expect("P8 template catalog seed");
  store
    .create_revision(&TemplateRevision {
      bundle_blob_id: None,
      checksum: None,
      created_at: now,
      created_by: None,
      detected_format: "snapshot".to_string(),
      error_catalog_version: "p8-test".to_string(),
      id: revision_id,
      ignored_entries_count: 0,
      manifest: None,
      normalization_warnings: Vec::new(),
      normalizer_version: "p8-test".to_string(),
      preview_blob_id: None,
      published_at: Some(now),
      release_notes: None,
      source_format: "snapshot".to_string(),
      state: RevisionState::Published,
      template_id,
      version: "1.0.0".to_string(),
    })
    .await
    .expect("P8 template revision seed");
  store
    .create_policy(&WorkspaceTemplatePolicy {
      created_at: now,
      id: Uuid::new_v4(),
      is_enabled: true,
      provisioning_mode: ProvisioningMode::SeedOnce,
      selected_revision_id: None,
      selection_mode: SelectionMode::Published,
      template_id,
      updated_at: now,
      workspace_id,
    })
    .await
    .expect("P8 template policy seed");
  store
    .create_instance(&WorkspaceTemplateInstance {
      id: Uuid::new_v4(),
      workspace_id,
      template_id,
      revision_id,
      workspace_doc_id: Some(template_doc_id),
      workspace_doc_key: Some(template_doc_id.to_string()),
      state: InstanceState::Ok,
      last_applied_hash: None,
      current_hash: None,
      last_synced_at: Some(now),
      detached_at: None,
      retired_at: None,
      last_error_code: None,
      last_error_message: None,
      expected_hash: None,
      locale_hash: None,
    })
    .await
    .expect("P8 template instance seed");
  template_id
}

#[test]
fn database_row_service_loads_the_database_aggregate_once() {
  helpers::block_on_large_stack("database-row-single-aggregate-load", || async {
    let counter = DatabaseAggregateLoadCounter::default();
    let subscriber = tracing_subscriber::registry().with(counter.clone());
    let dispatch = tracing::Dispatch::new(subscriber);
    let _guard = tracing::dispatcher::set_default(&dispatch);

    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-row-single-load-owner").await;
    let result = AssertUnwindSafe(async {
      let workspace_id = helpers::create_workspace(&pool, owner_id).await;
      let created = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": "mutation($input: CreateDatabaseInput!) { createDatabase(input: $input) { database { id } } }",
          "variables": { "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Single aggregate load",
            "initialViewKind": "Table"
          }}
        }),
      )
      .await;
      let database_id = gql_data(&created, &["createDatabase", "database"])["id"]
        .as_str()
        .expect("database id")
        .to_string();

      let repository = Arc::new(PgDatabaseRepository::new(
        pool.clone(),
        crate::helpers::database_starter_catalog(),
      ));
      let permission_store: Arc<dyn AuthStore> = auth_store.clone();
      let service = DatabaseServices::new(
        repository,
        DocService::new(Arc::new(SqlxDocStore::new(pool.clone()))),
        Arc::new(PermissionService::new(permission_store)),
        DatabaseLimits::default(),
        Arc::new(myoxus_infrastructure::workspace::SqlxWorkspaceStore::new(
          pool.clone(),
          crate::helpers::database_starter_catalog(),
        )),
        crate::helpers::database_starter_catalog(),
        myoxus_application::database::DatabaseServiceDependencies::disabled(),
      );
      counter.calls.store(0, Ordering::Relaxed);
      counter.enabled.store(true, Ordering::Relaxed);
      let created_row = service
        .editing
        .create_row(
          owner_id,
          Uuid::parse_str(&database_id).expect("database UUID"),
          Some("One read".to_string()),
          Vec::new(),
        )
        .await
        .expect("create Row through the Application service");
      counter.enabled.store(false, Ordering::Relaxed);

      assert_eq!(created_row.row.title, "One read");
      assert_eq!(created_row.row.row_kind, DatabaseRowKind::Record);
      assert_eq!(
        counter.calls.load(Ordering::Relaxed),
        1,
        "ordinary Row creation must load the Database aggregate exactly once"
      );
    })
    .catch_unwind()
    .await;

    helpers::cleanup_users(&pool, &[owner_id]).await;
    if let Err(error) = result {
      resume_unwind(error);
    }
  });
}

#[test]
fn database_graphql_crud_rows_and_csv_export_are_workspace_bound() {
  helpers::block_on_large_stack("workspace-database-crud-csv", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-owner").await;
    let (outsider_id, outsider_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-outsider").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let other_workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id workspaceId profileKind title }
            fields { id name fieldType required }
            fieldRoles { profileKind roleKey rowKindScope fieldId required config }
            views {
              id
              name
              viewKind
              config {
                kind
                table { titleFieldId visibleFieldIds }
                kanban { titleFieldId groupFieldId visibleFieldIds }
              }
            }
            rowCount
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Customer Pipeline",
            "description": "P3/P4 contract test",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let created_record = gql_data(&created, &["createDatabase"]);
    let database_id = created_record["database"]["id"].as_str().expect("database id");
    assert_eq!(created_record["database"]["workspaceId"], workspace_id.to_string());
    assert_eq!(created_record["database"]["profileKind"], "Generic");
    assert!(
      created_record["fieldRoles"].as_array().is_some_and(Vec::is_empty),
      "generic Database creation must not infer Project field roles from names"
    );
    assert_eq!(created_record["rowCount"], 0);
    assert_eq!(created_record["fields"][0]["fieldType"], "Title");
    let title_field_id = created_record["fields"][0]["id"].as_str().expect("title field id");
    let table_view_id = created_record["views"][0]["id"].as_str().expect("table view id");

    let text_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id name fieldType required }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Company",
            "fieldType": "Text",
            "config": { "text": { "multiline": false } },
            "required": false
          }
        }
      }),
    )
    .await;
    let company_field_id = gql_data(&text_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("text field id");

    let updated_view = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateView($input: UpdateDatabaseViewInput!) {
          updateDatabaseView(input: $input) {
            id
            viewKind
            config {
              kind
              table {
                titleFieldId
                visibleFieldIds
                fieldWidths { fieldId width }
                sort { fieldId direction }
                filter { fieldId operator value { kind value } }
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": table_view_id,
            "config": {
              "table": {
                "titleFieldId": title_field_id,
                "visibleFieldIds": [title_field_id, company_field_id],
                "fieldWidths": [],
                "sort": [],
                "filter": []
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&updated_view, &["updateDatabaseView"])["config"]["table"]["visibleFieldIds"]
        .as_array()
        .expect("visible fields")
        .len(),
      2
    );

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id contentDocument { documentId state title } title }
            cells { fieldId value { kind text number checkbox select multiSelect user date { start end } } }
            redacted
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Alpha Opportunity",
            "cells": [
              { "fieldId": company_field_id, "value": { "text": "Myoxus Labs" } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    assert_eq!(row["row"]["title"], "Alpha Opportunity");
    assert_eq!(row["redacted"], false);
    assert_eq!(row["cells"][0]["value"]["kind"], "Text");
    assert_eq!(row["cells"][0]["value"]["text"], "Myoxus Labs");
    assert!(
      row["row"]["contentDocument"].is_null(),
      "new database rows must not own documents"
    );
    let doc_count: i64 = sqlx::query_scalar("SELECT COUNT(*)::BIGINT FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("workspace doc count query");
    assert_eq!(
      doc_count, 0,
      "database row creation must not create implicit workspace documents"
    );

    let listed = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query Database($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databases { id title fieldCount }
            database(databaseId: $databaseId) { database { id } rowCount }
            databaseRows(databaseId: $databaseId) {
              totalCount
              rows {
                row { title }
                cells { value { kind text number checkbox select multiSelect user date { start end } } }
                redacted
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content rowCount columnCount contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&listed, &["workspace"]);
    assert_eq!(workspace["databases"].as_array().expect("database list").len(), 1);
    assert_eq!(workspace["database"]["rowCount"], 1);
    assert_eq!(workspace["databaseRows"]["totalCount"], 1);
    let csv = workspace["databaseCsvExport"]["content"].as_str().expect("csv export");
    assert!(
      csv.contains("Title,Company"),
      "CSV export must include visible fields: {csv}"
    );
    assert!(
      csv.contains("Alpha Opportunity,Myoxus Labs"),
      "CSV export must include row values: {csv}"
    );
    assert_eq!(workspace["databaseCsvExport"]["contentType"], "text/csv");

    let csv_content = b"Name,Amount,Closed\r\nDeal A,12.5,true\r\nDeal B,13,false\r\n";
    let csv_preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewDatabaseCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedDelimiter
            rowCount
            detectedColumns { fieldName fieldType isTitle }
            inferredFields { name fieldType config { kind } }
            errors { code message }
            warnings { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Imported Deals"
          }
        }
      }),
      "deals.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&csv_preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["detectedDelimiter"], "comma");
    assert_eq!(preview["rowCount"], 2);
    assert_eq!(
      preview["errors"].as_array().expect("preview errors").len(),
      0,
      "status CSV preview errors: {preview:#}"
    );
    assert_eq!(preview["detectedColumns"][0]["fieldType"], "Title");
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Currency");
    assert_eq!(preview["detectedColumns"][2]["fieldType"], "Checkbox");

    let csv_import = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportDatabaseCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { name fieldType }
              rowCount
            }
            createdFieldCount
            createdRowCount
            createdDocCount
            skippedRowCount
            errors { code message }
            warnings { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Imported Deals"
          }
        }
      }),
      "deals.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&csv_import, &["importDatabaseCsv"]);
    assert_eq!(imported["database"]["database"]["title"], "Imported Deals");
    assert_eq!(imported["createdFieldCount"], 3);
    assert_eq!(imported["createdRowCount"], 2);
    assert_eq!(imported["createdDocCount"], 0);
    assert_eq!(imported["skippedRowCount"], 0);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    assert_eq!(imported["database"]["rowCount"], 2);

    let invalid_cell_value = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidCellValue($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row["row"]["id"].as_str().expect("row id"),
            "fieldId": company_field_id,
            "value": { "text": "valid alone", "number": 42 }
          }
        }
      }),
    )
    .await;
    let invalid_cell_error = invalid_cell_value["errors"][0]["extensions"]["code"]
      .as_str()
      .expect("invalid cell error code");
    assert_eq!(invalid_cell_error, "MIX_DATABASE_CELL_VALUE_INVALID");

    let clear_cell_value = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ClearCellValue($input: ClearDatabaseCellValueInput!) {
          clearDatabaseCellValue(input: $input) { rowId fieldId editRevision hasValue }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row["row"]["id"].as_str().expect("row id"),
            "fieldId": company_field_id
          }
        }
      }),
    )
    .await;
    let cleared_revision = gql_data(&clear_cell_value, &["clearDatabaseCellValue"]);
    assert_eq!(cleared_revision["hasValue"], false);
    assert_eq!(cleared_revision["fieldId"], company_field_id);
    let cleared_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ClearedRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows { cells { fieldId value { kind text } } }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let cleared_cells = gql_data(&cleared_rows, &["workspace"])["databaseRows"]["rows"][0]["cells"]
      .as_array()
      .expect("cleared row cells");
    assert!(
      cleared_cells.is_empty(),
      "clearing a cell must remove the stored value from row projections"
    );
    let cell_values_table = ["workspace", "database", "cell", "values"].join("_");
    let (cell_count, tombstone_revision): (i64, Option<i64>) = sqlx::query_as(&format!(
      "SELECT COUNT(*)::BIGINT, MAX(edit_revision) FILTER (WHERE value_json IS NULL) \
       FROM {cell_values_table} WHERE row_id = $1 AND field_id = $2"
    ))
    .bind(uuid::Uuid::parse_str(row["row"]["id"].as_str().expect("row id")).expect("row id uuid"))
    .bind(uuid::Uuid::parse_str(company_field_id).expect("company field id uuid"))
    .fetch_one(&pool)
    .await
    .expect("cleared cell count");
    assert_eq!(cell_count, 1, "clear must retain exactly one revision tombstone");
    assert_eq!(
      tombstone_revision,
      cleared_revision["editRevision"].as_i64(),
      "the hidden tombstone must preserve the revision returned by the mutation"
    );

    let clear_title_value = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ClearTitleValue($input: ClearDatabaseCellValueInput!) {
          clearDatabaseCellValue(input: $input) { rowId fieldId editRevision hasValue }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row["row"]["id"].as_str().expect("row id"),
            "fieldId": title_field_id
          }
        }
      }),
    )
    .await;
    let clear_title_error = clear_title_value["errors"][0]["extensions"]["code"]
      .as_str()
      .expect("clear title error code");
    assert_eq!(clear_title_error, "MIX_DATABASE_CELL_VALUE_INVALID");

    let wrong_workspace = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query WrongWorkspace($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) { database(databaseId: $databaseId) { database { id } } }
        }
      "#,
        "variables": {
          "workspaceId": other_workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    assert!(gql_data(&wrong_workspace, &["workspace"])["database"].is_null());

    let outsider_update = helpers::gql(
      &app,
      outsider_session,
      json!({
        "query": r#"
        mutation OutsiderUpdate($input: UpdateDatabaseInput!) {
          updateDatabase(input: $input) { database { id } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Forbidden"
          }
        }
      }),
    )
    .await;
    let error_code = outsider_update["errors"][0]["extensions"]["code"]
      .as_str()
      .expect("database error code");
    assert_eq!(error_code, "MIX_DATABASE_FORBIDDEN");

    helpers::cleanup_users(&pool, &[owner_id, outsider_id]).await;
  });
}

#[test]
fn database_graphql_trash_restore_and_purge_preserve_children_until_purge() {
  helpers::block_on_large_stack("workspace-database-lifecycle", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-lifecycle-owner").await;
    let (outsider_id, outsider_session) =
      helpers::seed_user(&pool, &auth_store, "workspace-db-lifecycle-outsider").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation($input: CreateDatabaseInput!) {
            createDatabase(input: $input) {
              database { id editRevision }
              fields { id fieldType }
            }
          }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Recoverable Database",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let created_record = gql_data(&created, &["createDatabase"]);
    let database_id = created_record["database"]["id"].as_str().expect("database id");
    let title_field_id = created_record["fields"]
      .as_array()
      .expect("database fields")
      .iter()
      .find(|field| field["fieldType"] == "Title")
      .and_then(|field| field["id"].as_str())
      .expect("title field id");

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation($input: CreateDatabaseRowInput!) {
            createDatabaseRow(input: $input) { row { id title } }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Retained row",
            "cells": []
          }
        }
      }),
    )
    .await;
    let row_id = gql_data(&created_row, &["createDatabaseRow", "row"])["id"]
      .as_str()
      .expect("row id");

    let trash = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation($input: DatabaseLifecycleInput!) {
            trashDatabase(input: $input) {
              database { id editRevision deletedAt deletedBy }
              rowCount
            }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "expectedEditRevision": 1,
            "force": false
          }
        }
      }),
    )
    .await;
    let trashed = gql_data(&trash, &["trashDatabase"]);
    assert_eq!(trashed["rowCount"], 1);
    assert_eq!(trashed["database"]["editRevision"], 2);
    assert!(trashed["database"]["deletedAt"].is_string());
    assert_eq!(trashed["database"]["deletedBy"], owner_id.to_string());

    let inventory = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          query($workspaceId: String!, $databaseId: ID!) {
            workspace(id: $workspaceId) {
              databases { id }
              database(databaseId: $databaseId) { database { id } }
              trashedDatabases { id editRevision rowCount }
              databasePageIdentities { id }
              trashedDatabasePageIdentities {
                id profileKind title description deletedAt editRevision createdAt updatedAt
              }
            }
          }
        "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let inventory = gql_data(&inventory, &["workspace"]);
    assert!(inventory["databases"].as_array().is_some_and(Vec::is_empty));
    assert!(inventory["database"].is_null());
    assert_eq!(inventory["trashedDatabases"][0]["id"], database_id);
    assert_eq!(inventory["trashedDatabases"][0]["rowCount"], 1);
    assert!(
      inventory["databasePageIdentities"]
        .as_array()
        .is_some_and(Vec::is_empty)
    );
    let trashed_identity = &inventory["trashedDatabasePageIdentities"][0];
    assert_eq!(trashed_identity["id"], database_id);
    assert_eq!(trashed_identity["title"], "Recoverable Database");
    assert!(trashed_identity["deletedAt"].is_string());
    assert_eq!(trashed_identity["editRevision"], 2);

    let forbidden_inventory = helpers::gql(
      &app,
      outsider_session,
      json!({
        "query": "query($workspaceId: String!) { workspace(id: $workspaceId) { databasePageIdentities { id } } }",
        "variables": { "workspaceId": workspace_id.to_string() }
      }),
    )
    .await;
    assert!(
      forbidden_inventory.get("errors").is_some(),
      "Database page identities must preserve Workspace Read authorization: {forbidden_inventory}"
    );

    let forbidden_restore = helpers::gql(
      &app,
      outsider_session,
      json!({
        "query": "mutation($input: DatabaseLifecycleInput!) { restoreDatabase(input: $input) { database { id } } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "expectedEditRevision": 2,
            "force": false
          }
        }
      }),
    )
    .await;
    assert_eq!(
      forbidden_restore["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );

    let restore = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DatabaseLifecycleInput!) { restoreDatabase(input: $input) { database { id editRevision deletedAt } rowCount } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "expectedEditRevision": 2,
            "force": false
          }
        }
      }),
    )
    .await;
    let restored = gql_data(&restore, &["restoreDatabase"]);
    assert_eq!(restored["database"]["editRevision"], 3);
    assert!(restored["database"]["deletedAt"].is_null());
    assert_eq!(restored["rowCount"], 1);

    let restored_row_count: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_database_rows WHERE id = $1 AND database_id = $2")
        .bind(Uuid::parse_str(row_id).expect("row uuid"))
        .bind(Uuid::parse_str(database_id).expect("database uuid"))
        .fetch_one(&pool)
        .await
        .expect("restored row count");
    assert_eq!(restored_row_count, 1);
    let title_field_count: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_database_fields WHERE id = $1 AND database_id = $2")
        .bind(Uuid::parse_str(title_field_id).expect("title field uuid"))
        .bind(Uuid::parse_str(database_id).expect("database uuid"))
        .fetch_one(&pool)
        .await
        .expect("restored field count");
    assert_eq!(title_field_count, 1);

    let retrash = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DatabaseLifecycleInput!) { trashDatabase(input: $input) { database { editRevision } } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "expectedEditRevision": 3,
            "force": false
          }
        }
      }),
    )
    .await;
    assert_eq!(gql_data(&retrash, &["trashDatabase", "database"])["editRevision"], 4);

    let purged = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DatabaseLifecycleInput!) { deleteDatabasePermanently(input: $input) }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "expectedEditRevision": 4,
            "force": false
          }
        }
      }),
    )
    .await;
    assert_eq!(gql_data(&purged, &["deleteDatabasePermanently"]), true);
    let remaining_children: i64 = sqlx::query_scalar(
      "SELECT (SELECT COUNT(*) FROM workspace_database_rows WHERE database_id = $1) + \
              (SELECT COUNT(*) FROM workspace_database_fields WHERE database_id = $1)",
    )
    .bind(Uuid::parse_str(database_id).expect("database uuid"))
    .fetch_one(&pool)
    .await
    .expect("purged child count");
    assert_eq!(remaining_children, 0);

    helpers::cleanup_users(&pool, &[owner_id, outsider_id]).await;
  });
}

#[test]
fn database_repository_persists_profile_and_field_roles_transactionally() {
  helpers::block_on_large_stack("database-profile-field-roles", || async {
    let (_app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, _owner_session) = helpers::seed_user(&pool, &auth_store, "database-profile-role-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let repo = PgDatabaseRepository::new(pool.clone(), crate::helpers::database_starter_catalog());
    let now = Utc::now();
    let database_id = Uuid::new_v4();
    let title_field_id = Uuid::new_v4();
    let public_id_field_id = Uuid::new_v4();
    let fields = vec![
      myoxus_domain::database::DatabaseField {
        id: title_field_id,
        database_id,
        name: "Task".to_string(),
        field_type: myoxus_domain::database::DatabaseFieldType::Title,
        config: myoxus_domain::database::DatabaseFieldConfig::Title,
        position: 0,
        required: true,
        edit_revision: 1,
        created_at: now,
        updated_at: now,
      },
      myoxus_domain::database::DatabaseField {
        id: public_id_field_id,
        database_id,
        name: "Public ID".to_string(),
        field_type: myoxus_domain::database::DatabaseFieldType::UniqueId,
        config: myoxus_domain::database::DatabaseFieldConfig::UniqueId(
          myoxus_domain::database::DatabaseUniqueIdFieldConfig {
            prefix: "PROJ-".to_string(),
            start_number: 1,
            padding: 3,
          },
        ),
        position: 1,
        required: true,
        edit_revision: 1,
        created_at: now,
        updated_at: now,
      },
    ];
    let views = vec![myoxus_domain::database::DatabaseView {
      id: Uuid::new_v4(),
      database_id,
      name: "Table".to_string(),
      view_kind: myoxus_domain::database::DatabaseViewKind::Table,
      icon: None,
      config: myoxus_domain::database::DatabaseViewConfig::Table(myoxus_domain::database::DatabaseTableViewConfig {
        title_field_id,
        visible_field_ids: vec![title_field_id, public_id_field_id],
        field_widths: Default::default(),
        search_field_ids: Vec::new(),
        sort: Vec::new(),
        filter: Vec::new(),
        filter_tree: None,
        group: None,
        subgroup: None,
      }),
      position: 0,
      edit_revision: 1,
      created_at: now,
      updated_at: now,
    }];
    let field_roles = vec![
      myoxus_domain::database::DatabaseFieldRole {
        database_id,
        profile_kind: myoxus_domain::database::DatabaseProfileKind::Project,
        role_key: "task.title".to_string(),
        row_kind_scope: Some("task".to_string()),
        field_id: title_field_id,
        required: true,
        config: serde_json::json!({}),
        created_at: now,
        updated_at: now,
      },
      myoxus_domain::database::DatabaseFieldRole {
        database_id,
        profile_kind: myoxus_domain::database::DatabaseProfileKind::Project,
        role_key: "task.publicId".to_string(),
        row_kind_scope: Some("task".to_string()),
        field_id: public_id_field_id,
        required: true,
        config: serde_json::json!({}),
        created_at: now,
        updated_at: now,
      },
    ];

    let unbound = repo
      .create_database(myoxus_domain::database::DatabaseInitialState {
        database: myoxus_domain::database::Database {
          system_role: None,
          managed_installation: None,
          id: database_id,
          workspace_id,
          profile_kind: myoxus_domain::database::DatabaseProfileKind::Project,
          profile_structure_preset: Some("phases".to_string()),
          profile_config: serde_json::json!({ "profile": "project", "structurePreset": "phases" }),
          title: "Project role contract".to_string(),
          description: None,
          created_by: Some(owner_id),
          updated_by: Some(owner_id),
          deleted_at: None,
          deleted_by: None,
          edit_revision: 1,
          created_at: now,
          updated_at: now,
        },
        fields: fields,
        views: views,
        roles: field_roles,
        view_roles: Vec::new(),
        rows: Vec::new(),
        row_templates: Vec::new(),
        workspace_tags: Vec::new(),
      })
      .await
      .expect_err("Project schemas without an admitted installation must fail atomically");
    assert!(matches!(
      unbound,
      myoxus_domain::repositories::RepositoryError::Validation(_)
    ));
    assert!(repo.get_database(database_id).await.unwrap().is_none());
    let database_id = repo
      .task_destinations(workspace_id, 1, None)
      .await
      .unwrap()
      .default_destination
      .unwrap()
      .database_id;
    let loaded = repo
      .get_database(database_id)
      .await
      .unwrap()
      .expect("canonical managed aggregate");
    assert_eq!(
      loaded.database.profile_kind,
      myoxus_domain::database::DatabaseProfileKind::Project
    );
    assert_eq!(loaded.database.profile_structure_preset.as_deref(), Some("tasks_only"));
    let public_id = loaded
      .field_roles
      .iter()
      .find(|role| role.role_key == "task.publicId")
      .expect("persisted explicit public ID role");
    assert!(
      loaded
        .fields
        .iter()
        .any(|field| field.id == public_id.field_id && field.field_type == DatabaseFieldType::UniqueId)
    );

    let generic_database_id = Uuid::new_v4();
    let generic_title_field_id = Uuid::new_v4();
    repo
      .create_database(myoxus_domain::database::DatabaseInitialState {
        database: myoxus_domain::database::Database {
          system_role: None,
          managed_installation: None,
          id: generic_database_id,
          workspace_id,
          profile_kind: myoxus_domain::database::DatabaseProfileKind::Generic,
          profile_structure_preset: None,
          profile_config: serde_json::json!({}),
          title: "Generic role isolation".to_string(),
          description: None,
          created_by: Some(owner_id),
          updated_by: Some(owner_id),
          deleted_at: None,
          deleted_by: None,
          edit_revision: 1,
          created_at: now,
          updated_at: now,
        },
        fields: vec![myoxus_domain::database::DatabaseField {
          id: generic_title_field_id,
          database_id: generic_database_id,
          name: "Name".to_string(),
          field_type: myoxus_domain::database::DatabaseFieldType::Title,
          config: myoxus_domain::database::DatabaseFieldConfig::Title,
          position: 0,
          required: true,
          edit_revision: 1,
          created_at: now,
          updated_at: now,
        }],
        views: vec![myoxus_domain::database::DatabaseView {
          id: Uuid::new_v4(),
          database_id: generic_database_id,
          name: "Table".to_string(),
          view_kind: myoxus_domain::database::DatabaseViewKind::Table,
          icon: None,
          config: myoxus_domain::database::DatabaseViewConfig::Table(
            myoxus_domain::database::DatabaseTableViewConfig {
              title_field_id: generic_title_field_id,
              visible_field_ids: vec![generic_title_field_id],
              field_widths: Default::default(),
              search_field_ids: Vec::new(),
              sort: Vec::new(),
              filter: Vec::new(),
              filter_tree: None,
              group: None,
              subgroup: None,
            },
          ),
          position: 0,
          edit_revision: 1,
          created_at: now,
          updated_at: now,
        }],
        roles: Vec::new(),
        view_roles: Vec::new(),
        rows: Vec::new(),
        row_templates: Vec::new(),
        workspace_tags: Vec::new(),
      })
      .await
      .expect("create generic database for role isolation check");

    let mut native_writer = pool.begin().await.unwrap();
    sqlx::query("SELECT set_config('myoxus.managed_schema_write','on',true)")
      .execute(&mut *native_writer)
      .await
      .unwrap();
    let cross_database_role = sqlx::query(
      r#"
        INSERT INTO database_field_roles
          (database_id, profile_kind, role_key, row_kind_scope, field_id, required, config_json, created_at, updated_at)
        VALUES ($1, 'project', 'task.crossDatabase', 'task', $2, true, '{}'::jsonb, $3, $4)
      "#,
    )
    .bind(database_id)
    .bind(generic_title_field_id)
    .bind(now)
    .bind(now)
    .execute(&mut *native_writer)
    .await
    .expect_err("native composite FK rejects another Database field even inside the definition writer");
    assert_eq!(
      cross_database_role.as_database_error().unwrap().code().as_deref(),
      Some("23503")
    );
    native_writer.rollback().await.unwrap();

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_graphql_duration_field_roundtrips_config_cells_and_validation() {
  helpers::block_on_large_stack("database-duration-field-graphql", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-duration-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
            fields { id fieldType }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Duration contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let created_record = gql_data(&created, &["createDatabase"]);
    let database_id = created_record["database"]["id"].as_str().expect("database id");

    let duration_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDurationField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config {
              kind
              duration { displayUnit minMinutes maxMinutes }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Effort",
            "fieldType": "Duration",
            "config": {
              "duration": {
                "displayUnit": "Hours",
                "minMinutes": 0,
                "maxMinutes": 480
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let duration_field = gql_data(&duration_field, &["createDatabaseField"]);
    let duration_field_id = duration_field["id"].as_str().expect("duration field id");
    assert_eq!(duration_field["fieldType"], "Duration");
    assert_eq!(duration_field["config"]["duration"]["displayUnit"], "Hours");
    assert_eq!(duration_field["config"]["duration"]["minMinutes"], 0);
    assert_eq!(duration_field["config"]["duration"]["maxMinutes"], 480);

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDurationRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              fieldType
              value { kind duration { minutes } }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Implement Duration",
            "cells": [
              { "fieldId": duration_field_id, "value": { "duration": { "minutes": 90 } } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["fieldType"], "Duration");
    assert_eq!(row["cells"][0]["value"]["kind"], "Duration");
    assert_eq!(row["cells"][0]["value"]["duration"]["minutes"], 90);

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidDuration($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": duration_field_id,
            "value": { "duration": { "minutes": -1 } }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("duration validation error code"),
      "MIX_DATABASE_DURATION_INVALID"
    );

    let listed = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query DurationRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                cells {
                  fieldId
                  value { kind duration { minutes } }
                }
              }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let rows = &gql_data(&listed, &["workspace"])["databaseRows"]["rows"];
    assert_eq!(rows[0]["cells"][0]["value"]["duration"]["minutes"], 90);

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_graphql_status_field_roundtrips_semantics_and_import_export() {
  helpers::block_on_large_stack("database-status-field-graphql", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-status-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let kanban = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateKanbanDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
            fields {
              id
              name
              fieldType
              config {
                kind
                select { options { id name } }
                status { defaultOptionId options { id name position colorRole group } }
              }
            }
            views { viewKind config { kind kanban { groupFieldId } } }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Kanban status contract",
            "initialViewKind": "Kanban"
          }
        }
      }),
    )
    .await;
    let kanban_record = gql_data(&kanban, &["createDatabase"]);
    let initial_status = kanban_record["fields"]
      .as_array()
      .expect("kanban fields")
      .iter()
      .find(|field| field["name"] == "Status")
      .expect("initial Kanban status field");
    assert_eq!(initial_status["fieldType"], "Status");
    assert!(initial_status["config"]["select"].is_null());
    assert_eq!(initial_status["config"]["status"]["defaultOptionId"], "status.todo");
    assert_eq!(initial_status["config"]["status"]["options"][0]["group"], "NotStarted");
    assert_eq!(
      kanban_record["views"][0]["config"]["kanban"]["groupFieldId"], initial_status["id"],
      "initial Kanban grouping must use the semantic Status field"
    );

    let database_id = kanban_record["database"]["id"].as_str().expect("database id");
    let status_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateStatusField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            name
            fieldType
            config {
              kind
              select { options { id name } }
              status { defaultOptionId options { id name position colorRole group } }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Workflow",
            "fieldType": "Status",
            "config": {
              "status": {
                "defaultOptionId": "todo",
                "options": [
                  {
                    "id": "todo",
                    "name": "Todo",
                    "position": 0,
                    "colorRole": "database.status.todo",
                    "group": "NotStarted"
                  },
                  {
                    "id": "doing",
                    "name": "Doing",
                    "position": 1,
                    "colorRole": "database.status.inProgress",
                    "group": "Active"
                  },
                  {
                    "id": "done",
                    "name": "Done",
                    "position": 2,
                    "colorRole": "database.status.done",
                    "group": "Complete"
                  }
                ]
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let status_field = gql_data(&status_field, &["createDatabaseField"]);
    let status_field_id = status_field["id"].as_str().expect("status field id");
    assert_eq!(status_field["fieldType"], "Status");
    assert_eq!(status_field["config"]["kind"], "Status");
    assert!(status_field["config"]["select"].is_null());
    assert_eq!(status_field["config"]["status"]["options"][1]["group"], "Active");

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateStatusRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              fieldType
              value { kind select status }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Implement status",
            "cells": [
              { "fieldId": status_field_id, "value": { "status": "doing" } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["fieldType"], "Status");
    assert_eq!(row["cells"][0]["value"]["kind"], "Status");
    assert_eq!(row["cells"][0]["value"]["status"], "doing");
    assert!(row["cells"][0]["value"]["select"].is_null());

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidStatus($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": status_field_id,
            "value": { "status": "missing-status-option" }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("status validation error code"),
      "MIX_DATABASE_CELL_VALUE_INVALID"
    );

    let csv_content = b"Task,Status\nAlpha,Todo\nBeta,Doing\nGamma,Done\n";
    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewStatusCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields {
              name
              fieldType
              config { kind status { defaultOptionId options { id name position colorRole group } } }
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Status CSV"
          }
        }
      }),
      "status.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(
      preview["errors"].as_array().expect("preview errors").len(),
      0,
      "status CSV preview errors: {preview:#}"
    );
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Status");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "Status");
    assert_eq!(
      preview["inferredFields"][1]["config"]["status"]["defaultOptionId"],
      "status.csv.todo"
    );
    assert_eq!(
      preview["inferredFields"][1]["config"]["status"]["options"][2]["group"],
      "Complete"
    );

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportStatusCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { id name fieldType config { kind status { defaultOptionId options { id name group } } } }
              rowCount
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Status CSV"
          }
        }
      }),
      "status.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    assert_eq!(imported["database"]["rowCount"], 3);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_status_field = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "Status")
      .expect("imported status field");
    let imported_status_field_id = imported_status_field["id"].as_str().expect("imported status field id");
    assert!(
      imported_status_field["config"]["status"]["options"]
        .as_array()
        .expect("imported status options")
        .iter()
        .any(|option| option["id"] == "status.csv.doing" && option["group"] == "Active"),
      "imported status options must preserve CSV-derived ids and groups: {imported_status_field:#}"
    );

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedStatusRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells { fieldId value { kind status select } }
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
            databaseJsonExport(databaseId: $databaseId) { content contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let beta = rows.iter().find(|row| row["row"]["title"] == "Beta").expect("Beta row");
    let beta_status = beta["cells"]
      .as_array()
      .expect("Beta cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_status_field_id)
      .expect("Beta status cell");
    assert_eq!(beta_status["value"]["kind"], "Status");
    assert_eq!(beta_status["value"]["status"], "status.csv.doing");
    assert!(beta_status["value"]["select"].is_null());

    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains("status.csv.done"),
      "CSV export must preserve Status option ids, not only labels: {csv_export:?}"
    );

    let json_export = workspace["databaseJsonExport"]["content"]
      .as_str()
      .expect("JSON export");
    assert_eq!(workspace["databaseJsonExport"]["contentType"], "application/json");
    let snapshot: Value = serde_json::from_str(json_export).expect("status JSON snapshot");
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| {
          field["fieldType"] == "status"
            && field["config"]["kind"] == "status"
            && field["config"]["options"][2]["group"] == "complete"
        }),
      "JSON snapshot must preserve Status field schema: {snapshot:#}"
    );
    assert!(
      snapshot["database"]["rows"]
        .as_array()
        .expect("snapshot rows")
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .any(|cell| {
          cell["fieldType"] == "status"
            && cell["value"]["kind"] == "domain"
            && cell["value"]["value"]["kind"] == "status"
            && cell["value"]["value"]["value"] == "status.csv.doing"
        }),
      "JSON snapshot must preserve Status option ids: {snapshot:#}"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportStatusJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { fields { name fieldType config { kind status { defaultOptionId options { id name group } } } } rowCount }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "status.database.json",
      json_export.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_eq!(
      imported_json["warnings"]
        .as_array()
        .expect("JSON import warnings")
        .len(),
      0
    );
    assert_eq!(imported_json["database"]["rowCount"], 3);
    assert!(
      imported_json["database"]["fields"]
        .as_array()
        .expect("JSON imported fields")
        .iter()
        .any(|field| {
          field["name"] == "Status"
            && field["fieldType"] == "Status"
            && field["config"]["status"]["options"][2]["group"] == "Complete"
        }),
      "JSON import must recreate Status fields: {imported_json:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_graphql_users_field_roundtrips_config_cells_and_membership_validation() {
  helpers::block_on_large_stack("database-users-field-graphql", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-users-owner").await;
    let (member_id, _) = helpers::seed_user(&pool, &auth_store, "database-users-member").await;
    let (outsider_id, _) = helpers::seed_user(&pool, &auth_store, "database-users-outsider").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    sqlx::query(
      "INSERT INTO workspace_memberships (workspace_id, user_id, role, status, joined_at)
       VALUES ($1, $2, 'Collaborator', 'Accepted', now())",
    )
    .bind(workspace_id)
    .bind(member_id)
    .execute(&pool)
    .await
    .expect("insert accepted workspace member");

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) { database { id } }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Users contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let users_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateUsersField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config { kind users { minCount maxCount } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Assignees",
            "fieldType": "Users",
            "config": { "users": { "minCount": 1, "maxCount": 2 } },
            "required": false
          }
        }
      }),
    )
    .await;
    let users_field = gql_data(&users_field, &["createDatabaseField"]);
    let users_field_id = users_field["id"].as_str().expect("users field id");
    assert_eq!(users_field["fieldType"], "Users");
    assert_eq!(users_field["config"]["users"]["minCount"], 1);
    assert_eq!(users_field["config"]["users"]["maxCount"], 2);

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateUsersRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells { fieldId fieldType value { kind users user } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Assigned task",
            "cells": [
              { "fieldId": users_field_id, "value": { "users": [owner_id.to_string(), member_id.to_string()] } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["fieldType"], "Users");
    assert_eq!(row["cells"][0]["value"]["kind"], "Users");
    assert_eq!(
      row["cells"][0]["value"]["users"]
        .as_array()
        .expect("users value")
        .iter()
        .map(|value| value.as_str().expect("user id").to_string())
        .collect::<Vec<_>>(),
      vec![owner_id.to_string(), member_id.to_string()]
    );
    assert!(row["cells"][0]["value"]["user"].is_null());

    for (name, users) in [
      ("duplicate users", vec![owner_id, owner_id]),
      ("non-member user", vec![outsider_id]),
      ("empty users", Vec::new()),
    ] {
      let invalid = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": r#"
          mutation InvalidUsers($input: UpdateDatabaseCellValueInput!) {
            updateDatabaseCellValue(input: $input) { fieldId }
          }
        "#,
          "variables": {
            "input": {
              "databaseId": database_id,
              "rowId": row_id,
              "fieldId": users_field_id,
              "value": { "users": users.iter().map(Uuid::to_string).collect::<Vec<_>>() }
            }
          }
        }),
      )
      .await;
      assert_eq!(
        invalid["errors"][0]["extensions"]["code"]
          .as_str()
          .unwrap_or_else(|| panic!("{name} must return database validation code: {invalid:#}")),
        "MIX_DATABASE_CELL_VALUE_INVALID",
        "{name} must be rejected"
      );
    }

    helpers::cleanup_users(&pool, &[owner_id, member_id, outsider_id]).await;
  });
}

#[test]
fn database_csv_preview_import_mapping_and_export_dialect_contract() {
  helpers::block_on_large_stack("database-csv-dialect-mapping", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-csv-contract-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let csv_content = b"Alpha|12|red; blue\r\nBeta|13|blue\r\n";
    let csv_input = json!({
      "workspaceId": workspace_id.to_string(),
      "databaseTitle": "Mapped imports",
      "dialect": { "delimiter": "Pipe" },
      "firstRowIsHeader": false,
      "mapping": [
        { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
        { "sourceIndex": 1, "importColumn": true, "fieldName": "Score", "fieldType": "Number", "isTitle": false },
        { "sourceIndex": 2, "importColumn": true, "fieldName": "Tags", "fieldType": "MultiSelect", "isTitle": false }
      ]
    });

    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedDelimiter
            detectedDialect { delimiter }
            appliedDialect { delimiter }
            confidence
            rowCount
            appliedMapping { sourceIndex sourceHeader fieldName fieldType isTitle importColumn }
            errors { code field message }
          }
        }
      "#,
        "variables": { "file": null, "input": csv_input.clone() }
      }),
      "mapped.psv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["detectedDelimiter"], "pipe");
    assert_eq!(preview["detectedDialect"]["delimiter"], "Pipe");
    assert_eq!(preview["appliedDialect"]["delimiter"], "Pipe");
    assert_eq!(preview["confidence"], "explicit");
    assert_eq!(preview["rowCount"], 2);
    assert_eq!(preview["appliedMapping"][0]["sourceHeader"], "Column 1");
    assert_eq!(preview["appliedMapping"][0]["fieldType"], "Title");
    assert_eq!(preview["appliedMapping"][2]["fieldType"], "MultiSelect");
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);

    let missing_title_preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            errors { code field message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Invalid import",
            "dialect": { "delimiter": "Pipe" },
            "firstRowIsHeader": false,
            "mapping": [
              { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Text", "isTitle": false }
            ]
          }
        }
      }),
      "missing-title.psv",
      csv_content,
    )
    .await;
    let errors = gql_data(&missing_title_preview, &["previewDatabaseCsvImport"])["errors"]
      .as_array()
      .expect("mapping errors");
    assert!(
      errors.iter().any(|error| error["message"]
        .as_str()
        .unwrap_or_default()
        .contains("exactly one imported Title")),
      "preview must report a structured missing-title mapping error: {errors:#?}"
    );

    let invalid_mapping_preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            errors { code field message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Invalid targets",
            "dialect": { "delimiter": "Pipe" },
            "firstRowIsHeader": false,
            "mapping": [
              { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
              { "sourceIndex": 1, "importColumn": true, "fieldName": "Other title", "fieldType": "Title", "isTitle": true },
              { "sourceIndex": 2, "importColumn": true, "fieldName": "Created", "fieldType": "CreatedTime", "isTitle": false },
              { "sourceIndex": 2, "importColumn": true, "fieldName": "Related row", "fieldType": "Relation", "isTitle": false }
            ]
          }
        }
      }),
      "invalid-targets.psv",
      csv_content,
    )
    .await;
    let errors = gql_data(&invalid_mapping_preview, &["previewDatabaseCsvImport"])["errors"]
      .as_array()
      .expect("invalid target errors");
    assert!(
      errors.iter().any(|error| error["message"]
        .as_str()
        .unwrap_or_default()
        .contains("exactly one imported Title")),
      "preview must reject multiple imported Title columns: {errors:#?}"
    );
    assert!(
      errors.iter().any(|error| error["message"]
        .as_str()
        .unwrap_or_default()
        .contains("cannot be imported")),
      "preview must reject read-only projection field targets as non-importable: {errors:#?}"
    );
    assert!(
      errors.iter().any(|error| error["message"]
        .as_str()
        .unwrap_or_default()
        .contains("Relation imports require an existing target Database")),
      "preview must reject relation CSV mapping with a specific target-resolution diagnostic: {errors:#?}"
    );

    let auto_comma_preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedDialect { delimiter }
            confidence
            rowCount
            appliedMapping { sourceIndex sourceHeader fieldName fieldType isTitle importColumn }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Auto comma",
            "dialect": { "delimiter": "Auto" },
            "firstRowIsHeader": true,
            "mapping": [
              { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
              { "sourceIndex": 1, "importColumn": true, "fieldName": "Score", "fieldType": "Number", "isTitle": false },
              { "sourceIndex": 2, "importColumn": true, "fieldName": "Tags", "fieldType": "Text", "isTitle": false }
            ]
          }
        }
      }),
      "auto-comma.csv",
      b"Task,Score,Tags\nAlpha,12,\"red, blue\"\nBeta,13,blue\n",
    )
    .await;
    let auto_comma_preview = gql_data(&auto_comma_preview, &["previewDatabaseCsvImport"]);
    assert_eq!(auto_comma_preview["detectedDialect"]["delimiter"], "Comma");
    assert_eq!(auto_comma_preview["confidence"], "high");
    assert_eq!(auto_comma_preview["rowCount"], 2);
    assert_eq!(
      auto_comma_preview["errors"]
        .as_array()
        .expect("auto comma preview errors")
        .len(),
      0
    );

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields {
                name
                fieldType
                config { kind multiSelect { options { id name } } }
              }
              rowCount
            }
            createdFieldCount
            createdRowCount
            errors { code message }
          }
        }
      "#,
        "variables": { "file": null, "input": csv_input }
      }),
      "mapped.psv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["createdFieldCount"], 3);
    assert_eq!(imported["createdRowCount"], 2);
    assert_eq!(imported["database"]["rowCount"], 2);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    let database_id = imported["database"]["database"]["id"].as_str().expect("database id");
    let fields = imported["database"]["fields"].as_array().expect("fields");
    let tags = fields.iter().find(|field| field["name"] == "Tags").expect("tags field");
    assert_eq!(tags["fieldType"], "MultiSelect");
    let options = tags["config"]["multiSelect"]["options"]
      .as_array()
      .expect("multi-select options");
    assert_eq!(options.len(), 2);
    assert!(options.iter().any(|option| option["id"] == "red"));
    assert!(options.iter().any(|option| option["id"] == "blue"));

    let export_semicolon = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ExportSemicolon($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseCsvExport(databaseId: $databaseId, options: { dialect: { delimiter: Semicolon } }) {
              content
              contentType
              rowCount
              columnCount
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let export_semicolon = gql_data(&export_semicolon, &["workspace", "databaseCsvExport"]);
    assert_eq!(export_semicolon["contentType"], "text/csv");
    assert_eq!(export_semicolon["rowCount"], 2);
    assert_eq!(export_semicolon["columnCount"], 3);
    let export_content = export_semicolon["content"].as_str().expect("semicolon CSV export");
    assert!(export_content.starts_with("Task;Score;Tags\r\n"));
    assert!(
      export_content.contains("Alpha;12.00;\"red; blue\"\r\n"),
      "semicolon export must quote multi-select values containing the selected delimiter: {export_content:?}"
    );

    for (delimiter, expected_header) in [
      ("Comma", "Task,Score,Tags\r\n"),
      ("Tab", "Task\tScore\tTags\r\n"),
      ("Pipe", "Task|Score|Tags\r\n"),
    ] {
      let exported = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": r#"
          query ExportDialect($workspaceId: String!, $databaseId: ID!, $dialect: DatabaseCsvDialectInput!) {
            workspace(id: $workspaceId) {
              databaseCsvExport(databaseId: $databaseId, options: { dialect: $dialect }) {
                content
                contentType
                rowCount
                columnCount
              }
            }
          }
        "#,
          "variables": {
            "workspaceId": workspace_id.to_string(),
            "databaseId": database_id,
            "dialect": { "delimiter": delimiter }
          }
        }),
      )
      .await;
      let exported = gql_data(&exported, &["workspace", "databaseCsvExport"]);
      assert_eq!(exported["contentType"], "text/csv");
      assert_eq!(exported["rowCount"], 2);
      assert_eq!(exported["columnCount"], 3);
      let content = exported["content"].as_str().expect("dialect CSV export");
      assert!(
        content.starts_with(expected_header),
        "{delimiter} export must use the requested delimiter: {content:?}"
      );
    }

    let export_auto = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ExportAuto($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseCsvExport(databaseId: $databaseId, options: { dialect: { delimiter: Auto } }) { content }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let error_code = export_auto["errors"][0]["extensions"]["code"]
      .as_str()
      .expect("export auto error code");
    assert_eq!(error_code, "MIX_DATABASE_CSV_INVALID");

    let existing_tag = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateWorkspaceTagInput!) { createWorkspaceTag(input: $input) { id slug } }",
        "variables": {
          "input": {
            "workspaceId": workspace_id,
            "name": "Backend",
            "colorRole": "tag.blue"
          }
        }
      }),
    )
    .await;
    let existing_tag_id = gql_data(&existing_tag, &["createWorkspaceTag"])["id"]
      .as_str()
      .expect("existing workspace tag id")
      .to_string();
    let workspace_tag_csv = b"Task,Tags\r\nAlpha,Backend|tag.blue; Launch|#ed3f3f\r\nBeta,Launch|#ed3f3f\r\n";
    let workspace_tag_input = json!({
      "workspaceId": workspace_id.to_string(),
      "databaseTitle": "Workspace tag import",
      "firstRowIsHeader": true,
      "mapping": [
        { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
        { "sourceIndex": 1, "importColumn": true, "fieldName": "Tags", "fieldType": "Tags", "isTitle": false }
      ]
    });
    let tag_preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation PreviewTagCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
            previewDatabaseCsvImport(file: $file, input: $input) {
              errors { code message }
              workspaceTagDiagnostics {
                targetId name slug sourceColor colorRole action affectedRows affectedFields message
              }
            }
          }
        "#,
        "variables": { "file": null, "input": workspace_tag_input.clone() }
      }),
      "workspace-tags.csv",
      workspace_tag_csv,
    )
    .await;
    let tag_preview = gql_data(&tag_preview, &["previewDatabaseCsvImport"]);
    assert!(tag_preview["errors"].as_array().expect("tag preview errors").is_empty());
    let diagnostics = tag_preview["workspaceTagDiagnostics"]
      .as_array()
      .expect("workspace tag preview diagnostics");
    assert_eq!(diagnostics.len(), 2, "preview must name each canonical tag once");
    let reused = diagnostics
      .iter()
      .find(|diagnostic| diagnostic["slug"] == "backend")
      .expect("reused Backend diagnostic");
    assert_eq!(reused["action"], "Reuse");
    assert_eq!(reused["targetId"], existing_tag_id);
    assert_eq!(reused["affectedRows"], json!([2]));
    let created = diagnostics
      .iter()
      .find(|diagnostic| diagnostic["slug"] == "launch")
      .expect("created Launch diagnostic");
    assert_eq!(created["action"], "Create");
    assert_eq!(created["sourceColor"], "#ed3f3f");
    assert_eq!(created["colorRole"], "tag.red");
    assert_eq!(created["affectedRows"], json!([2, 3]));
    assert_eq!(created["affectedFields"], json!(["Tags"]));

    let tag_import = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation ImportTagCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
            importDatabaseCsv(file: $file, input: $input) {
              database { database { id } fields { id name fieldType } rowCount }
              createdRowCount
              workspaceTagDiagnostics { targetId slug colorRole action }
            }
          }
        "#,
        "variables": { "file": null, "input": workspace_tag_input }
      }),
      "workspace-tags.csv",
      workspace_tag_csv,
    )
    .await;
    let tag_import = gql_data(&tag_import, &["importDatabaseCsv"]);
    assert_eq!(tag_import["createdRowCount"], 2);
    assert_eq!(tag_import["database"]["rowCount"], 2);
    let tag_database_id = tag_import["database"]["database"]["id"]
      .as_str()
      .expect("tag database id");
    let launch_tag_id = tag_import["workspaceTagDiagnostics"]
      .as_array()
      .expect("import tag diagnostics")
      .iter()
      .find(|diagnostic| diagnostic["slug"] == "launch")
      .and_then(|diagnostic| diagnostic["targetId"].as_str())
      .expect("created Launch tag id");

    let imported_tags = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          query ImportedWorkspaceTags($workspaceId: String!, $databaseId: ID!) {
            workspace(id: $workspaceId) {
              workspaceTags(includeArchived: true) { id slug colorRole }
              databaseRows(databaseId: $databaseId) {
                rows { row { title } cells { fieldType value { tags } } }
              }
              databaseCsvExport(databaseId: $databaseId) {
                content warnings { code } workspaceTagDiagnostics { sourceId slug colorRole }
              }
            }
          }
        "#,
        "variables": { "workspaceId": workspace_id.to_string(), "databaseId": tag_database_id }
      }),
    )
    .await;
    let imported_tags = gql_data(&imported_tags, &["workspace"]);
    let catalog = imported_tags["workspaceTags"]
      .as_array()
      .expect("workspace tag catalog");
    assert!(
      catalog
        .iter()
        .any(|tag| tag["id"] == existing_tag_id && tag["slug"] == "backend")
    );
    assert!(
      catalog
        .iter()
        .any(|tag| tag["id"] == launch_tag_id && tag["colorRole"] == "tag.red")
    );
    let alpha_tags = imported_tags["databaseRows"]["rows"]
      .as_array()
      .expect("imported rows")
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .and_then(|row| row["cells"].as_array())
      .and_then(|cells| cells.iter().find(|cell| cell["fieldType"] == "Tags"))
      .and_then(|cell| cell["value"]["tags"].as_array())
      .expect("Alpha workspace tag ids");
    assert_eq!(alpha_tags, &vec![json!(existing_tag_id), json!(launch_tag_id)]);
    assert!(
      imported_tags["databaseCsvExport"]["content"]
        .as_str()
        .expect("workspace tag CSV export")
        .contains("Backend|tag.blue; Launch|tag.red")
    );
    assert!(
      imported_tags["databaseCsvExport"]["warnings"]
        .as_array()
        .expect("workspace tag CSV warnings")
        .iter()
        .any(|warning| warning["code"] == "MIX_DATABASE_CSV_TAG_ROUNDTRIP_LOSSY")
    );

    let renamed_launch = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: RenameWorkspaceTagInput!) { renameWorkspaceTag(input: $input) { id slug } }",
        "variables": {
          "input": { "workspaceId": workspace_id, "tagId": launch_tag_id, "name": "Deployment Ready" }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&renamed_launch, &["renameWorkspaceTag"])["slug"],
      "deployment-ready"
    );
    let row_search_rows: Vec<(Value, String, bool, bool)> = sqlx::query_as(
      "SELECT workspace_tags, search_text, tsv @@ plainto_tsquery('simple', 'Launch'), tsv @@ plainto_tsquery('simple', 'Deployment') FROM workspace_database_row_search WHERE workspace_id = $1 AND database_id = $2 ORDER BY row_id",
    )
    .bind(workspace_id)
    .bind(Uuid::parse_str(tag_database_id).expect("tag database UUID"))
    .fetch_all(&pool)
    .await
    .expect("refreshed Database row tag search projections");
    assert_eq!(row_search_rows.len(), 2);
    assert!(
      row_search_rows
        .iter()
        .all(|(projection, search_text, matches_old_tag, matches_current_tag)| {
          let tags = projection.as_array().expect("row workspace tag projection");
          !search_text.contains(launch_tag_id)
            && !search_text.contains("Launch")
            && !matches_old_tag
            && *matches_current_tag
            && !tags.iter().any(|tag| tag["slug"] == "launch")
            && tags
              .iter()
              .any(|tag| tag["id"] == launch_tag_id && tag["slug"] == "deployment-ready")
        })
    );

    let json_export = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!) { workspace(id: $workspaceId) { databaseJsonExport(databaseId: $databaseId) { content } } }",
        "variables": { "workspaceId": workspace_id.to_string(), "databaseId": tag_database_id }
      }),
    )
    .await;
    let json_content = gql_data(&json_export, &["workspace", "databaseJsonExport"])["content"]
      .as_str()
      .expect("lossless workspace-tag JSON export");
    let json_snapshot: Value = serde_json::from_str(json_content).expect("workspace-tag JSON snapshot");
    assert_eq!(json_snapshot["schemaVersion"], DATABASE_SNAPSHOT_SCHEMA_VERSION);
    let manifest = json_snapshot["workspaceTagsManifest"]
      .as_array()
      .expect("workspace-tag manifest");
    assert!(
      manifest
        .iter()
        .any(|tag| tag["id"] == existing_tag_id && tag["slug"] == "backend")
    );
    assert!(
      manifest.iter().any(|tag| {
        tag["id"] == launch_tag_id && tag["slug"] == "deployment-ready" && tag["colorRole"] == "tag.red"
      })
    );

    let json_preview = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation PreviewTagJson($file: Upload!, $input: PreviewDatabaseJsonImportInput!) {
            previewDatabaseJsonImport(file: $file, input: $input) {
              errors { code message }
              workspaceTagDiagnostics { sourceId targetId slug colorRole action affectedRows affectedFields }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string(), "mode": "CREATE" }
        }
      }),
      "workspace-tags.database.json",
      json_content.as_bytes(),
    )
    .await;
    let json_preview = gql_data(&json_preview, &["previewDatabaseJsonImport"]);
    assert!(
      json_preview["errors"]
        .as_array()
        .expect("tag JSON preview errors")
        .is_empty()
    );
    assert!(
      json_preview["workspaceTagDiagnostics"]
        .as_array()
        .expect("tag JSON diagnostics")
        .iter()
        .all(|diagnostic| diagnostic["action"] == "Reuse" && diagnostic["sourceId"] == diagnostic["targetId"])
    );

    let json_import = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation ImportTagJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              database { database { id } rowCount }
              createdRowCount workspaceTagDiagnostics { sourceId targetId action }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string(), "mode": "CREATE" }
        }
      }),
      "workspace-tags.database.json",
      json_content.as_bytes(),
    )
    .await;
    let json_import = gql_data(&json_import, &["importDatabaseJson"]);
    assert_eq!(json_import["createdRowCount"], 2);
    assert_eq!(json_import["database"]["rowCount"], 2);
    assert!(
      json_import["workspaceTagDiagnostics"]
        .as_array()
        .expect("tag JSON import diagnostics")
        .iter()
        .all(|diagnostic| diagnostic["action"] == "Reuse" && diagnostic["sourceId"] == diagnostic["targetId"])
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_json_snapshot_export_preview_and_import_roundtrip_contract() {
  helpers::block_on_large_stack("database-json-snapshot-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-json-contract-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let csv_input = json!({
      "workspaceId": workspace_id.to_string(),
      "databaseTitle": "Snapshot source",
      "dialect": { "delimiter": "Comma" },
      "firstRowIsHeader": true,
      "mapping": [
        { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
        { "sourceIndex": 1, "importColumn": true, "fieldName": "Done", "fieldType": "Checkbox", "isTitle": false },
        { "sourceIndex": 2, "importColumn": true, "fieldName": "Link", "fieldType": "Url", "isTitle": false }
      ]
    });
    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database { database { id title } rowCount fields { id name fieldType } }
          }
        }
      "#,
        "variables": { "file": null, "input": csv_input }
      }),
      "snapshot-source.csv",
      b"Task,Done,Link\nAlpha,true,https://example.com/a\nBeta,false,https://example.com/b\n",
    )
    .await;
    let database_id = gql_data(&imported, &["importDatabaseCsv"])["database"]["database"]["id"]
      .as_str()
      .expect("imported database id")
      .to_string();
    let score_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateNumberField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Score",
            "fieldType": "Number",
            "config": { "number": {} },
            "required": false
          }
        }
      }),
    )
    .await;
    let score_field_id = gql_data(&score_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("Score field id")
      .to_string();

    let rich_text_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRichTextField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Brief",
            "fieldType": "RichText",
            "config": { "richText": { "maxPlainTextBytes": 1024 } },
            "required": false
          }
        }
      }),
    )
    .await;
    let rich_text_field_id = gql_data(&rich_text_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("Brief field id")
      .to_string();

    let relation_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRelationField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Related",
            "fieldType": "Relation",
            "config": {
              "relation": {
                "targetDatabaseId": database_id,
                "allowMultiple": true
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let relation_field_id = gql_data(&relation_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("Related field id")
      .to_string();

    let formula_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateFormulaField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Score x2",
            "fieldType": "Formula",
            "config": {
              "formula": {
                "expression": "[Score] * 2",
                "resultType": "Number",
                "dependencyFieldIds": [],
                "stalePolicy": "Async"
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let _formula_field_id = gql_data(&formula_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("Score x2 field id")
      .to_string();

    let rollup_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRollupField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Related score",
            "fieldType": "Rollup",
            "config": {
              "rollup": {
                "sourceRelationFieldId": relation_field_id,
                "targetFieldId": score_field_id,
                "aggregate": "Sum",
                "stalePolicy": "Async"
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let _rollup_field_id = gql_data(&rollup_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("Related score field id")
      .to_string();

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query SourceRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows { row { id title } }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let source_rows = gql_data(&imported_rows, &["workspace"])["databaseRows"]["rows"]
      .as_array()
      .expect("source rows");
    let alpha_row_id = source_rows
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .and_then(|row| row["row"]["id"].as_str())
      .expect("Alpha row id")
      .to_string();
    let beta_row_id = source_rows
      .iter()
      .find(|row| row["row"]["title"] == "Beta")
      .and_then(|row| row["row"]["id"].as_str())
      .expect("Beta row id")
      .to_string();

    for (row_id, score) in [(alpha_row_id.as_str(), 4.0), (beta_row_id.as_str(), 6.0)] {
      let score_update = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": r#"
          mutation UpdateScore($input: UpdateDatabaseCellValueInput!) {
            updateDatabaseCellValue(input: $input) { fieldId }
          }
        "#,
          "variables": {
            "input": {
              "databaseId": database_id,
              "rowId": row_id,
              "fieldId": score_field_id,
              "value": { "number": score }
            }
          }
        }),
      )
      .await;
      let _ = gql_data(&score_update, &["updateDatabaseCellValue"]);
    }

    let rich_text_document = json!({
      "type": "doc",
      "content": [{
        "type": "paragraph",
        "content": [
          { "type": "text", "text": "Bold", "marks": [{ "type": "bold" }] },
          { "type": "text", "text": " italic", "marks": [{ "type": "italic" }] },
          { "type": "text", "text": " strike", "marks": [{ "type": "strike" }] },
          { "type": "text", "text": " code", "marks": [{ "type": "code" }] },
          { "type": "hardBreak" },
          { "type": "text", "text": "link", "marks": [{
            "type": "link", "attrs": { "href": "https://example.test/spec" }
          }] }
        ]
      }]
    });
    let rich_text_update = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateRichText($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": alpha_row_id,
            "fieldId": rich_text_field_id,
            "value": { "richText": { "document": rich_text_document.clone() } }
          }
        }
      }),
    )
    .await;
    let _ = gql_data(&rich_text_update, &["updateDatabaseCellValue"]);

    let relation_update = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateRelation($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": alpha_row_id,
            "fieldId": relation_field_id,
            "value": { "relation": [beta_row_id] }
          }
        }
      }),
    )
    .await;
    let _ = gql_data(&relation_update, &["updateDatabaseCellValue"]);

    let permission_store: Arc<dyn AuthStore> = auth_store.clone();
    let repo = Arc::new(PgDatabaseRepository::new(
      pool.clone(),
      crate::helpers::database_starter_catalog(),
    ));
    let service = DatabaseServices::new(
      repo,
      DocService::new(Arc::new(SqlxDocStore::new(pool.clone()))),
      Arc::new(PermissionService::new(permission_store)),
      DatabaseLimits::default(),
      Arc::new(myoxus_infrastructure::workspace::SqlxWorkspaceStore::new(
        pool.clone(),
        crate::helpers::database_starter_catalog(),
      )),
      crate::helpers::database_starter_catalog(),
      myoxus_application::database::DatabaseServiceDependencies::disabled(),
    );
    service
      .projection
      .recompute_stale_formulas(Some(workspace_id), 10, 10, "json_roundtrip_formula")
      .await
      .expect("JSON roundtrip formula recompute");
    service
      .projection
      .recompute_stale_rollups(Some(workspace_id), 10, 10, "json_roundtrip_rollup")
      .await
      .expect("JSON roundtrip rollup recompute");

    let before = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ListDatabases($workspaceId: String!) {
          workspace(id: $workspaceId) { databases(first: 20) { id } }
        }
      "#,
        "variables": { "workspaceId": workspace_id.to_string() }
      }),
    )
    .await;
    let before_count = gql_data(&before, &["workspace"])["databases"]
      .as_array()
      .expect("database list before JSON preview")
      .len();

    let exported = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ExportJson($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseJsonExport(databaseId: $databaseId) {
              fileName
              contentType
              content
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let export = gql_data(&exported, &["workspace", "databaseJsonExport"]);
    assert_eq!(export["contentType"], "application/json");
    assert!(
      export["fileName"]
        .as_str()
        .expect("JSON export filename")
        .ends_with(".database.json"),
      "JSON export must use a product-specific snapshot extension"
    );
    let content = export["content"].as_str().expect("JSON snapshot content");
    let snapshot: Value = serde_json::from_str(content).expect("JSON snapshot must be parseable");
    assert_eq!(snapshot["schemaVersion"], DATABASE_SNAPSHOT_SCHEMA_VERSION);
    assert_eq!(snapshot["database"]["title"], "Snapshot source");
    assert_eq!(snapshot["database"]["rows"].as_array().expect("snapshot rows").len(), 2);
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| field["name"] == "Link" && field["fieldType"] == "url"),
      "JSON snapshot must preserve supported field schema: {snapshot:#}"
    );
    let snapshot_fields = snapshot["database"]["fields"].as_array().expect("snapshot fields");
    assert!(
      snapshot_fields
        .iter()
        .any(|field| field["name"] == "Related" && field["fieldType"] == "relation"),
      "JSON snapshot must preserve Relation field schema: {snapshot:#}"
    );
    assert!(
      snapshot_fields
        .iter()
        .any(|field| field["name"] == "Score x2" && field["fieldType"] == "formula"),
      "JSON snapshot must preserve Formula field schema: {snapshot:#}"
    );
    assert!(
      snapshot_fields
        .iter()
        .any(|field| field["name"] == "Related score" && field["fieldType"] == "rollup"),
      "JSON snapshot must preserve Rollup field schema: {snapshot:#}"
    );
    assert!(
      snapshot_fields
        .iter()
        .any(|field| field["name"] == "Brief" && field["fieldType"] == "rich_text"),
      "JSON snapshot must preserve RichText field schema: {snapshot:#}"
    );
    let alpha_snapshot_row = snapshot["database"]["rows"]
      .as_array()
      .expect("snapshot rows")
      .iter()
      .find(|row| row["title"] == "Alpha")
      .expect("Alpha snapshot row");
    assert!(
      alpha_snapshot_row["cells"]
        .as_array()
        .expect("Alpha snapshot cells")
        .iter()
        .any(|cell| cell["fieldType"] == "relation"
          && cell["value"]["kind"] == "relation"
          && cell["value"]["value"].as_array().expect("relation local ids").len() == 1),
      "JSON snapshot must export same-Database relation cells with portable local row ids: {snapshot:#}"
    );
    let rich_text_snapshot_cell = alpha_snapshot_row["cells"]
      .as_array()
      .expect("Alpha snapshot cells")
      .iter()
      .find(|cell| cell["fieldType"] == "rich_text")
      .expect("RichText snapshot cell");
    assert_eq!(rich_text_snapshot_cell["value"]["kind"], "domain");
    assert_eq!(rich_text_snapshot_cell["value"]["value"]["kind"], "rich_text");
    assert_eq!(
      rich_text_snapshot_cell["value"]["value"]["value"]["plainText"],
      "Bold italic strike code\nlink"
    );
    assert_eq!(
      rich_text_snapshot_cell["value"]["value"]["value"]["document"], rich_text_document,
      "JSON snapshot must preserve every canonical RichText mark and hard break"
    );
    assert!(
      alpha_snapshot_row["projections"]
        .as_array()
        .expect("Alpha snapshot projections")
        .iter()
        .any(|cell| cell["fieldType"] == "formula"
          && cell["value"]["kind"] == "domain"
          && cell["value"]["value"]["kind"] == "formula"),
      "JSON snapshot must export Formula projections as read-only projections: {snapshot:#}"
    );
    assert!(
      alpha_snapshot_row["projections"]
        .as_array()
        .expect("Alpha snapshot projections")
        .iter()
        .any(|cell| cell["fieldType"] == "rollup"
          && cell["value"]["kind"] == "domain"
          && cell["value"]["value"]["kind"] == "rollup"),
      "JSON snapshot must export Rollup projections as read-only projections: {snapshot:#}"
    );

    let preview = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewJson($file: Upload!, $input: PreviewDatabaseJsonImportInput!) {
          previewDatabaseJsonImport(file: $file, input: $input) {
            schemaVersion
            title
            fieldCount
            viewCount
            rowCount
            templateCount
            errors { code path message }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "snapshot-source.database.json",
      content.as_bytes(),
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseJsonImport"]);
    assert_eq!(preview["schemaVersion"], DATABASE_SNAPSHOT_SCHEMA_VERSION);
    assert_eq!(preview["title"], "Snapshot source");
    assert_eq!(preview["fieldCount"], 8);
    assert_eq!(preview["rowCount"], 2);
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);

    let after_preview = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ListDatabases($workspaceId: String!) {
          workspace(id: $workspaceId) { databases(first: 20) { id } }
        }
      "#,
        "variables": { "workspaceId": workspace_id.to_string() }
      }),
    )
    .await;
    let after_preview_count = gql_data(&after_preview, &["workspace"])["databases"]
      .as_array()
      .expect("database list after JSON preview")
      .len();
    assert_eq!(
      after_preview_count, before_count,
      "JSON preview must not write a database"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { database { id title } rowCount fields { id name fieldType } views { name viewKind } }
            createdFieldCount
            createdViewCount
            createdRowCount
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "snapshot-source.database.json",
      content.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_ne!(
      imported_json["database"]["database"]["id"].as_str(),
      Some(database_id.as_str())
    );
    assert_eq!(imported_json["database"]["database"]["title"], "Snapshot source");
    assert_eq!(imported_json["database"]["rowCount"], 2);
    assert_eq!(imported_json["createdFieldCount"], 8);
    assert_eq!(imported_json["createdRowCount"], 2);
    let imported_json_fields = imported_json["database"]["fields"]
      .as_array()
      .expect("imported JSON fields");
    assert!(
      imported_json_fields
        .iter()
        .any(|field| field["name"] == "Link" && field["fieldType"] == "Url"),
      "JSON import must recreate supported field schema: {imported_json:#}"
    );
    let imported_relation_field_id = imported_json_fields
      .iter()
      .find(|field| field["name"] == "Related" && field["fieldType"] == "Relation")
      .and_then(|field| field["id"].as_str())
      .expect("imported Relation field id")
      .to_string();
    let imported_rich_text_field_id = imported_json_fields
      .iter()
      .find(|field| field["name"] == "Brief" && field["fieldType"] == "RichText")
      .and_then(|field| field["id"].as_str())
      .expect("imported RichText field id")
      .to_string();
    assert!(
      imported_json_fields
        .iter()
        .any(|field| field["name"] == "Score x2" && field["fieldType"] == "Formula"),
      "JSON import must recreate Formula field schema: {imported_json:#}"
    );
    assert!(
      imported_json_fields
        .iter()
        .any(|field| field["name"] == "Related score" && field["fieldType"] == "Rollup"),
      "JSON import must recreate Rollup field schema: {imported_json:#}"
    );

    let imported_database_id = imported_json["database"]["database"]["id"]
      .as_str()
      .expect("imported JSON database id");
    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells {
                  fieldId
                  value {
                    kind
                    relation
                    relationTargets { title redacted deleted }
                    richText { plainText document }
                  }
                }
              }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let imported_alpha = gql_data(&imported_rows, &["workspace"])["databaseRows"]["rows"]
      .as_array()
      .expect("imported rows")
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .expect("imported Alpha row")
      .clone();
    let imported_relation_cell = imported_alpha["cells"]
      .as_array()
      .expect("imported Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_relation_field_id)
      .expect("imported relation cell");
    assert_eq!(imported_relation_cell["value"]["kind"], "Relation");
    assert_eq!(
      imported_relation_cell["value"]["relation"]
        .as_array()
        .expect("relation ids")
        .len(),
      1
    );
    let imported_target = &imported_relation_cell["value"]["relationTargets"][0];
    assert_eq!(imported_target["title"], "Beta");
    assert_eq!(imported_target["redacted"], false);
    assert_eq!(imported_target["deleted"], false);
    let imported_rich_text_cell = imported_alpha["cells"]
      .as_array()
      .expect("imported Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_rich_text_field_id)
      .expect("imported RichText cell");
    assert_eq!(
      imported_rich_text_cell["value"]["richText"]["plainText"],
      "Bold italic strike code\nlink"
    );
    assert_eq!(
      imported_rich_text_cell["value"]["richText"]["document"], rich_text_document,
      "JSON import must preserve canonical RichText marks"
    );

    let mut invalid_rich_text_snapshot = snapshot.clone();
    let invalid_cell = invalid_rich_text_snapshot["database"]["rows"]
      .as_array_mut()
      .expect("mutable snapshot rows")
      .iter_mut()
      .find(|row| row["title"] == "Alpha")
      .and_then(|row| row["cells"].as_array_mut())
      .and_then(|cells| cells.iter_mut().find(|cell| cell["fieldType"] == "rich_text"))
      .expect("mutable RichText snapshot cell");
    invalid_cell["value"]["value"]["value"]["document"] = json!({
      "type": "doc",
      "content": [{ "type": "heading", "content": [] }]
    });
    let invalid_import = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportInvalidRichText($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) { createdRowCount }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "invalid-rich-text.database.json",
      invalid_rich_text_snapshot.to_string().as_bytes(),
    )
    .await;
    assert_eq!(
      invalid_import["errors"][0]["extensions"]["code"], "MIX_DATABASE_RICH_TEXT_INVALID",
      "unsupported RichText snapshot payloads must fail at the canonical normalizer: {invalid_import:#}"
    );
    let after_invalid_import = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ListDatabasesAfterInvalid($workspaceId: String!) {
          workspace(id: $workspaceId) { databases(first: 20) { id } }
        }
      "#,
        "variables": { "workspaceId": workspace_id.to_string() }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&after_invalid_import, &["workspace"])["databases"]
        .as_array()
        .expect("database list after invalid RichText import")
        .len(),
      before_count + 1,
      "invalid RichText import must roll back the entire new Database"
    );

    let unsupported = snapshot
      .as_object()
      .map(|object| {
        let mut clone = object.clone();
        clone.insert("schemaVersion".to_string(), json!(999));
        Value::Object(clone)
      })
      .expect("snapshot object");
    let unsupported_preview = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewJson($file: Upload!, $input: PreviewDatabaseJsonImportInput!) {
          previewDatabaseJsonImport(file: $file, input: $input) {
            errors { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "unsupported.database.json",
      unsupported.to_string().as_bytes(),
    )
    .await;
    let errors = gql_data(&unsupported_preview, &["previewDatabaseJsonImport"])["errors"]
      .as_array()
      .expect("unsupported version errors");
    assert!(
      errors
        .iter()
        .any(|error| error["code"] == "MIX_DATABASE_JSON_UNSUPPORTED_VERSION"),
      "preview must reject unsupported major JSON snapshot versions: {errors:#?}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_export_includes_files_manifest_for_files_field_cells() {
  // P-DB-28: exporting a Database with a `Files` field populates
  // `filesManifest` with one entry per distinct `blob_key` and the
  // GraphQL export payload surfaces the snapshot via the standard
  // `databaseJsonExport` endpoint.
  helpers::block_on_large_stack("pdb28-files-manifest", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-files-manifest-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Create($input: CreateDatabaseInput!) {
            createDatabase(input: $input) {
              database { id }
              views { id }
            }
          }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Files manifest source",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase", "database"])["id"]
      .as_str()
      .expect("database id")
      .to_string();
    let files_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateFilesField($input: CreateDatabaseFieldInput!) {
            createDatabaseField(input: $input) { id fieldType }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Attachments",
            "fieldType": "Files",
            "config": {
              "files": {
                "allowedMimeCategories": ["Any"],
                "maxItemCount": 5,
                "maxItemSize": 1048576,
                "previewPolicy": "Auto"
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let files_field_id = gql_data(&files_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("files field id")
      .to_string();
    // P-DB-28: pre-register both blob references in the workspace
    // `blobs` table so the Files-cell write passes the
    // `MIX_DATABASE_FILES_INVALID` check that enforces blob keys are
    // known to the workspace.
    for (blob_key, mime, size) in [
      ("blob-1", "text/markdown", 1234_i64),
      ("blob-2", "image/png", 98_765_i64),
    ] {
      let full_key = format!("pdb28-files-manifest/{blob_key}");
      sqlx::query(
        "INSERT INTO blobs (workspace_id, key, size, mime, status, created_at, updated_at)
         VALUES ($1, $2, $3, $4, 'completed', now(), now())
         ON CONFLICT (workspace_id, key) DO NOTHING",
      )
      .bind(workspace_id)
      .bind(&full_key)
      .bind(size)
      .bind(mime)
      .execute(&pool)
      .await
      .expect("seed blob metadata");
    }
    // Write a row with a Files cell that has two distinct blob keys.
    let create_row_resp = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"mutation CreateRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells { fieldId value { kind } }
          }
        }"#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Sample row",
            "cells": [
              {
                "fieldId": files_field_id,
                "value": {
                  "files": {
                    "files": [
                      { "blobKey": "pdb28-files-manifest/blob-1", "name": "spec.md", "mime": "text/markdown", "size": 1234 },
                      { "blobKey": "pdb28-files-manifest/blob-2", "name": "diagram.png", "mime": "image/png", "size": 98765 }
                    ]
                  }
                }
              }
            ]
          }
        }
      }),
    )
    .await;
    if let Some(errors) = create_row_resp.get("errors") {
      panic!("row with Files cell failed to create: {errors:#}");
    }
    let created_row = gql_data(&create_row_resp, &["createDatabaseRow"]);
    assert_eq!(created_row["cells"][0]["value"]["kind"], "Files");
    let exported = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          query ExportJson($workspaceId: String!, $databaseId: ID!) {
            workspace(id: $workspaceId) {
              databaseJsonExport(databaseId: $databaseId) { content }
            }
          }
        "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let content = gql_data(&exported, &["workspace", "databaseJsonExport"])["content"]
      .as_str()
      .expect("export content");
    let snapshot: Value = serde_json::from_str(content).expect("JSON snapshot must parse");
    let manifest = snapshot["filesManifest"].as_array().expect("filesManifest array");
    assert_eq!(
      manifest.len(),
      2,
      "filesManifest must dedupe by blob_key and list every distinct blob: {snapshot:#}"
    );
    let blob_keys: Vec<&str> = manifest
      .iter()
      .map(|entry| entry["blobKey"].as_str().expect("blobKey"))
      .collect();
    assert_eq!(blob_keys, vec!["asset_0", "asset_1"]);
    let first = manifest
      .iter()
      .find(|entry| entry["name"] == "spec.md")
      .expect("blob-1 entry");
    assert_eq!(first["blobKey"], "asset_0");
    assert_eq!(first["name"], "spec.md");
    assert_eq!(first["mime"], "text/markdown");
    assert_eq!(first["size"], 1234);
    assert_eq!(first["fieldName"], "Attachments");
    assert!(
      first["rowId"].is_string(),
      "filesManifest entries must carry row context for diagnostics"
    );
    let _ = files_field_id;

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb38b_portable_row_and_template_content_preview_apply_and_link_contract() {
  helpers::block_on_large_stack("pdb38b-portable-content", || async {
    let _template_guard = helpers::TEMPLATE_REGISTRY_LOCK
      .get_or_init(|| std::sync::Mutex::new(()))
      .lock()
      .unwrap_or_else(|poisoned| poisoned.into_inner());
    let (app, pool, auth_store) = helpers::setup_app_with_template_registry_and_search_service().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb38b-portable-content-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    helpers::create_workspace_root_doc(&pool, workspace_id, owner_id).await;
    let source_blocks = serde_json::from_value::<Vec<yjs::PortableSnapshotBlock>>(json!([
      {
        "id": "source-paragraph",
        "flavour": "myoxus:paragraph",
        "children": [],
        "props": {
          "text": {
            "$virgultum:internal:text$": true,
            "delta": [
              { "insert": "Links to " },
              {
                "insert": "Target",
                "attributes": {
                  "reference": {
                    "type": "LinkedPage",
                    "pageId": "myoxus-snapshot-document:row-content-target",
                    "mode": "page"
                  }
                }
              },
              { "insert": "." }
            ]
          }
        }
      }
    ]))
    .expect("portable source blocks");
    let source_update = yjs::snapshot_blocks_to_yjs(&source_blocks).expect("source Yjs update");
    let target_update = yjs::markdown_to_yjs("Target body", "Target content.").expect("target Yjs update");
    let template_update =
      yjs::markdown_to_yjs("Template body", "Portable template content.").expect("template Yjs update");
    let source_template_id = Uuid::new_v4();
    let snapshot = json!({
      "schemaVersion": 3,
      "exportedAt": "2026-07-12T00:00:00Z",
      "source": { "product": "myoxus", "format": "database-json-snapshot" },
      "database": {
        "id": "database_0",
        "title": "Portable content contract",
        "description": null,
        "fields": [
          { "id": "field_0", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false }
        ],
        "views": [],
        "rows": [
          {
            "id": "row_source",
            "title": "Source",
            "position": 0,
            "contentDocument": {
              "documentKey": "row-content-source",
              "title": "Source body",
              "yjsUpdateBase64": STANDARD.encode(&source_update),
              "assetKeys": []
            },
            "cells": [],
            "projections": []
          },
          {
            "id": "row_target",
            "title": "Target",
            "position": 1,
            "contentDocument": {
              "documentKey": "row-content-target",
              "title": "Target body",
              "yjsUpdateBase64": STANDARD.encode(&target_update),
              "assetKeys": []
            },
            "cells": [],
            "projections": []
          }
        ],
        "rowTemplates": [
          {
            "id": "row_template_0",
            "templateId": source_template_id,
            "rowKind": "record",
            "name": "Portable template",
            "description": null,
            "position": 0,
            "enabled": true,
            "isDefault": true,
            "contentDocument": {
              "documentKey": "row-template-content-0",
              "title": "Template body",
              "yjsUpdateBase64": STANDARD.encode(&template_update),
              "assetKeys": []
            },
            "initialCellValues": {}
          }
        ]
      },
      "databases": [],
      "filesManifest": []
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("portable snapshot serialises");
    let docs_before: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("count documents before preview");
    let databases_before: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM workspace_databases WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("count Databases before preview");
    let templates_before: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM template_catalog_entries")
      .fetch_one(&pool)
      .await
      .expect("count templates before preview");

    let preview = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation PreviewPortableContent($file: Upload!, $input: PreviewDatabaseJsonImportInput!) {
            previewDatabaseJsonImport(file: $file, input: $input) {
              rowCount
              templateCount
              errors { code path message }
            }
          }
        "#,
        "variables": { "file": null, "input": { "workspaceId": workspace_id.to_string() } }
      }),
      "portable-content.database.json",
      &snapshot_bytes,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseJsonImport"]);
    assert_eq!(preview["rowCount"], 2);
    assert_eq!(preview["templateCount"], 1);
    assert_eq!(preview["errors"], json!([]));
    let docs_after_preview: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("count documents after preview");
    let databases_after_preview: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_databases WHERE workspace_id = $1")
        .bind(workspace_id)
        .fetch_one(&pool)
        .await
        .expect("count Databases after preview");
    let templates_after_preview: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM template_catalog_entries")
      .fetch_one(&pool)
      .await
      .expect("count templates after preview");
    assert_eq!(docs_after_preview, docs_before, "Preview must not create documents");
    assert_eq!(
      databases_after_preview, databases_before,
      "Preview must not create Databases"
    );
    assert_eq!(
      templates_after_preview, templates_before,
      "Preview must not create templates"
    );

    let imported = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation ImportPortableContent($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              database { database { id } rowCount }
              createdRowCount
              createdTemplateCount
            }
          }
        "#,
        "variables": { "file": null, "input": { "workspaceId": workspace_id.to_string() } }
      }),
      "portable-content.database.json",
      &snapshot_bytes,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseJson"]);
    assert_eq!(imported["createdRowCount"], 2);
    assert_eq!(imported["createdTemplateCount"], 1);
    let database_id = Uuid::parse_str(
      imported["database"]["database"]["id"]
        .as_str()
        .expect("imported Database id"),
    )
    .expect("imported Database UUID");
    let imported_rows: Vec<(String, Option<Uuid>)> =
      sqlx::query_as("SELECT title, doc_id FROM workspace_database_rows WHERE database_id = $1 ORDER BY title")
        .bind(database_id)
        .fetch_all(&pool)
        .await
        .expect("imported Row content associations");
    assert_eq!(imported_rows.len(), 2);
    let source_document_id = imported_rows
      .iter()
      .find(|(title, _)| title == "Source")
      .and_then(|(_, document_id)| *document_id)
      .expect("Source content document");
    let target_document_id = imported_rows
      .iter()
      .find(|(title, _)| title == "Target")
      .and_then(|(_, document_id)| *document_id)
      .expect("Target content document");
    assert_ne!(source_document_id, target_document_id);

    let doc_service = DocService::new(Arc::new(SqlxDocStore::new(pool.clone())));
    let source_persisted = doc_service
      .load_full_doc(workspace_id, source_document_id)
      .await
      .expect("load imported Source content");
    let references = yjs::extract_document_references_from_yjs(&source_persisted).expect("extract imported links");
    assert_eq!(references.occurrences.len(), 1);
    assert_eq!(
      references.occurrences[0].raw_target_doc_id,
      target_document_id.to_string()
    );
    let resource_values = yjs::collect_yjs_resource_values(&source_persisted).expect("inspect persisted resources");
    assert!(
      resource_values
        .iter()
        .all(|value| !value.starts_with("myoxus-snapshot-")),
      "reserved snapshot URIs must not persist: {resource_values:#?}"
    );

    let (row_template_id, template_document_id): (Uuid, Uuid) = sqlx::query_as(
      r#"
        SELECT rt.id, i.workspace_doc_id
        FROM workspace_database_row_templates rt
        JOIN workspace_template_instances i
          ON i.workspace_id = rt.workspace_id AND i.template_id = rt.template_id
        WHERE rt.database_id = $1
      "#,
    )
    .bind(database_id)
    .fetch_one(&pool)
    .await
    .expect("portable Row-template materialization");
    let applied = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation ApplyPortableRowTemplate($input: CreateDatabaseRowFromTemplateInput!) {
            createDatabaseRowFromTemplate(input: $input) {
              row { id title contentDocument { documentId state title } }
            }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowTemplateId": row_template_id,
            "title": "Applied portable template"
          }
        }
      }),
    )
    .await;
    let applied_row = gql_data(&applied, &["createDatabaseRowFromTemplate", "row"]);
    assert_eq!(applied_row["contentDocument"]["state"], "Available");
    let applied_document_id = Uuid::parse_str(
      applied_row["contentDocument"]["documentId"]
        .as_str()
        .expect("applied content document id"),
    )
    .expect("applied content document UUID");
    assert_ne!(applied_document_id, template_document_id);
    let applied_update = doc_service
      .load_full_doc(workspace_id, applied_document_id)
      .await
      .expect("load applied template body");
    let applied_text = yjs::extract_text_from_yjs(&applied_update).expect("extract applied template body");
    assert!(
      applied_text.markdown.contains("Portable template content"),
      "applied Row-template body lost imported content: {applied_text:#?}"
    );

    // Force the repository's late duplicate-template rejection after all
    // content documents and registry records have been materialized. The
    // service must compensate every side effect outside the SQL transaction.
    let mut failing_snapshot = snapshot.clone();
    let mut duplicate_template = failing_snapshot["database"]["rowTemplates"][0].clone();
    duplicate_template["contentDocument"]["documentKey"] = json!("row-template-content-duplicate");
    failing_snapshot["database"]["rowTemplates"]
      .as_array_mut()
      .expect("failing Row-template list")
      .push(duplicate_template);
    let failing_snapshot_bytes = serde_json::to_vec(&failing_snapshot).expect("failing snapshot serialises");
    let docs_before_failure: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("count documents before rollback probe");
    let databases_before_failure: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_databases WHERE workspace_id = $1")
        .bind(workspace_id)
        .fetch_one(&pool)
        .await
        .expect("count Databases before rollback probe");
    let templates_before_failure: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM template_catalog_entries")
      .fetch_one(&pool)
      .await
      .expect("count templates before rollback probe");
    let failed_import = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation ImportInvalidPortableContent($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              database { database { id } }
            }
          }
        "#,
        "variables": { "file": null, "input": { "workspaceId": workspace_id.to_string() } }
      }),
      "invalid-portable-content.database.json",
      &failing_snapshot_bytes,
    )
    .await;
    assert!(
      !gql_errors(&failed_import).is_empty(),
      "duplicate imported Row-template ids must fail: {failed_import:#}"
    );
    let docs_after_failure: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("count documents after rollback probe");
    let databases_after_failure: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_databases WHERE workspace_id = $1")
        .bind(workspace_id)
        .fetch_one(&pool)
        .await
        .expect("count Databases after rollback probe");
    let templates_after_failure: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM template_catalog_entries")
      .fetch_one(&pool)
      .await
      .expect("count templates after rollback probe");
    assert_eq!(docs_after_failure, docs_before_failure, "failed Apply leaked documents");
    assert_eq!(
      databases_after_failure, databases_before_failure,
      "failed Apply leaked a Database"
    );
    assert_eq!(
      templates_after_failure, templates_before_failure,
      "failed Apply leaked Template Registry records"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_preview_reports_missing_file_manifest_diagnostics() {
  // P-DB-28: importing a snapshot whose `filesManifest` references
  // blobs that are not carried alongside the snapshot surfaces
  // `MIX_DATABASE_JSON_MISSING_FILE` diagnostics in the preview
  // response so the wizard can warn before applying the import.
  helpers::block_on_large_stack("pdb28-missing-files", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-missing-files-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    // Build a synthetic snapshot referencing one manifest entry.
    let snapshot = json!({
      "schemaVersion": 2,
      "exportedAt": "2026-07-08T00:00:00Z",
      "source": {
        "product": "myoxus",
        "format": "database-json-snapshot",
        "databaseId": "00000000-0000-0000-0000-000000000001",
        "exportedBy": "00000000-0000-0000-0000-000000000002"
      },
      "database": {
        "id": "database_0",
        "title": "Standalone snapshot",
        "description": null,
        "fields": [
          { "id": "field_0", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false }
        ],
        "views": [],
        "rows": [],
        "rowTemplates": []
      },
      "databases": [],
      "filesManifest": [
        { "blobKey": "missing-blob-1", "name": "lost.md", "mime": "text/markdown", "size": 42, "fieldName": "Attachments", "rowId": "row_0" }
      ]
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("snapshot serialises");
    let preview = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Preview($file: Upload!, $input: PreviewDatabaseJsonImportInput!) {
            previewDatabaseJsonImport(file: $file, input: $input) {
              fileManifestCount
              schemaVersion
              schemaVersionSupported
              warnings { code message }
              errors { code }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "missing-files.json",
      &snapshot_bytes,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseJsonImport"]);
    assert_eq!(preview["schemaVersion"], 2);
    assert_eq!(preview["schemaVersionSupported"], true);
    assert_eq!(preview["fileManifestCount"], 1);
    let warnings = preview["warnings"].as_array().expect("warnings");
    assert!(
      warnings
        .iter()
        .any(|diag| diag["code"] == "MIX_DATABASE_JSON_MISSING_FILE"),
      "preview must surface missing-file diagnostics: {preview:#}"
    );
    assert!(
      warnings
        .iter()
        .any(|diag| diag["message"].as_str().unwrap_or("").contains("missing-blob-1")),
      "missing-file diagnostic must mention the blob_key: {preview:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_import_create_mode_rejects_when_target_required_but_omitted() {
  // P-DB-28: `mode = replace` without a targetDatabaseId must fail
  // fast with a stable error code so the wizard surfaces the
  // misconfiguration before persisting anything.
  helpers::block_on_large_stack("pdb28-target-required", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-target-required-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let snapshot = json!({
      "schemaVersion": 2,
      "exportedAt": "2026-07-08T00:00:00Z",
      "source": { "product": "myoxus", "format": "database-json-snapshot" },
      "database": {
        "id": "database_0",
        "title": "Target required snapshot",
        "description": null,
        "fields": [
          { "id": "field_0", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false }
        ],
        "views": [],
        "rows": [],
        "rowTemplates": []
      },
      "databases": [],
      "filesManifest": []
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("snapshot serialises");
    let resp = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) { database { database { id } } }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "REPLACE"
          }
        }
      }),
      "missing-target.json",
      &snapshot_bytes,
    )
    .await;
    let errors = gql_errors(&resp);
    assert!(
      errors
        .iter()
        .any(|err| err["message"].as_str().unwrap_or("").contains("targetDatabaseId")),
      "missing-target import must reject the request: {errors:#?}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_import_replace_requires_confirm_destructive() {
  // P-DB-28: even with a valid target, `mode = replace` without
  // `confirmDestructive = true` must be refused so the wizard can
  // surface the dangerous-mode confirmation prompt before any data
  // is dropped.
  helpers::block_on_large_stack("pdb28-confirm-destructive", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-confirm-destructive-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let target_resp = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateTarget($input: CreateDatabaseInput!) {
            createDatabase(input: $input) { database { id } }
          }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Destructive target",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let target_id = gql_data(&target_resp, &["createDatabase", "database"])["id"]
      .as_str()
      .expect("target id")
      .to_string();
    let snapshot = json!({
      "schemaVersion": 2,
      "exportedAt": "2026-07-08T00:00:00Z",
      "source": { "product": "myoxus", "format": "database-json-snapshot" },
      "database": {
        "id": "database_0",
        "title": "Replacement snapshot",
        "description": null,
        "fields": [
          { "id": "field_0", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false }
        ],
        "views": [],
        "rows": [],
        "rowTemplates": []
      },
      "databases": [],
      "filesManifest": []
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("snapshot serialises");
    let resp = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) { database { database { id } } }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "REPLACE",
            "targetDatabaseId": target_id
          }
        }
      }),
      "destructive.json",
      &snapshot_bytes,
    )
    .await;
    let errors = gql_errors(&resp);
    assert!(
      errors.iter().any(
        |err| err["extensions"]["code"] == "MIX_DATABASE_JSON_DESTRUCTIVE_NOT_CONFIRMED"
          || err["message"].as_str().unwrap_or("").contains("confirmDestructive")
      ),
      "destructive replace without confirmation must be refused: {errors:#?}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_import_replace_with_confirm_destructive_rebuilds_target() {
  // P-DB-28: `mode = replace` with `confirmDestructive = true`
  // deletes the existing target and rebuilds it from the snapshot,
  // returning the new Database record and a `conflictWarnings` list.
  helpers::block_on_large_stack("pdb28-replace-flow", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-replace-flow-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    helpers::create_workspace_root_doc(&pool, workspace_id, owner_id).await;
    let target_resp = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateTarget($input: CreateDatabaseInput!) {
            createDatabase(input: $input) { database { id } }
          }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Replace target",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let target_id = gql_data(&target_resp, &["createDatabase", "database"])["id"]
      .as_str()
      .expect("target id")
      .to_string();
    let snapshot = json!({
      "schemaVersion": 3,
      "exportedAt": "2026-07-08T00:00:00Z",
      "source": { "product": "myoxus", "format": "database-json-snapshot" },
      "database": {
        "id": "database_0",
        "title": "Replaced title",
        "description": null,
        "fields": [
          { "id": "field_0", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false }
        ],
        "views": [],
        "rows": [{
          "id": "row_0",
          "title": "Replaced content Row",
          "position": 0,
          "contentDocument": {
            "documentKey": "replace-content-0",
            "title": "Replaced content body",
            "yjsUpdateBase64": "AAA=",
            "assetKeys": []
          },
          "cells": [],
          "projections": []
        }],
        "rowTemplates": []
      },
      "databases": [],
      "filesManifest": []
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("snapshot serialises");
    let resp = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              mode
              conflictStrategy
              dryRun
              createdFieldCount
              createdRowCount
              database { database { id title } }
              warnings { code }
              conflictWarnings { code }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "REPLACE",
            "targetDatabaseId": target_id,
            "confirmDestructive": true
          }
        }
      }),
      "replace.json",
      &snapshot_bytes,
    )
    .await;
    let result = gql_data(&resp, &["importDatabaseJson"]);
    assert_eq!(result["mode"], "REPLACE");
    assert_eq!(result["conflictStrategy"], "ABORT");
    assert_eq!(result["dryRun"], false);
    assert_eq!(result["createdFieldCount"], 1);
    assert_eq!(result["createdRowCount"], 1);
    assert_eq!(result["database"]["database"]["title"], "Replaced title");
    // Replace must result in a non-empty database id; the snapshot's
    // local id is mapped to a fresh server UUID rather than preserving
    // the original target_id.
    assert!(
      result["database"]["database"]["id"]
        .as_str()
        .map(|s| !s.is_empty())
        .unwrap_or(false),
      "replace flow must yield a valid database id: {result:#}"
    );
    let replaced_database_id = Uuid::parse_str(
      result["database"]["database"]["id"]
        .as_str()
        .expect("replaced Database id"),
    )
    .expect("replaced Database UUID");
    let replacement_content_document: Option<Uuid> =
      sqlx::query_scalar("SELECT doc_id FROM workspace_database_rows WHERE database_id = $1")
        .bind(replaced_database_id)
        .fetch_one(&pool)
        .await
        .expect("replacement Row content");
    assert!(
      replacement_content_document.is_some(),
      "Replace must materialize explicit portable content"
    );
    assert!(
      result["warnings"]
        .as_array()
        .expect("warnings")
        .iter()
        .any(|diag| diag["code"] == "MIX_DATABASE_JSON_REPLACE_REPORT"),
      "replace flow must emit a replace-report warning: {result:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn pdb28_import_merge_strategies_apply_unique_id_conflicts_and_portable_content() {
  // P-DB-28/P-DB-38B: all strategies resolve the same actual UniqueId
  // collision after snapshot fields have been mapped to live fields.
  helpers::block_on_large_stack("pdb28-merge-conflict-strategies", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "pdb28-merge-rename-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    // Set up target Database with a Title field and a UniqueId field,
    // plus one row carrying a stable UniqueId.
    let target_resp = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateTarget($input: CreateDatabaseInput!) {
            createDatabase(input: $input) {
              database { id }
              fields { id fieldType }
            }
          }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Merge target",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let target_id = gql_data(&target_resp, &["createDatabase", "database"])["id"]
      .as_str()
      .expect("target id")
      .to_string();
    let target_title_field = gql_data(&target_resp, &["createDatabase", "fields"])
      .as_array()
      .expect("fields")
      .iter()
      .find(|field| field["fieldType"] == "Title")
      .and_then(|field| field["id"].as_str())
      .expect("title field id")
      .to_string();
    let unique_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateUniqueField($input: CreateDatabaseFieldInput!) {
            createDatabaseField(input: $input) { id fieldType }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": target_id,
            "name": "UID",
            "fieldType": "UniqueId",
            "config": { "uniqueId": { "prefix": "T" } },
            "required": false
          }
        }
      }),
    )
    .await;
    let unique_field_id = gql_data(&unique_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("unique field id")
      .to_string();
    let create_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation CreateTargetRow($input: CreateDatabaseRowInput!) {
            createDatabaseRow(input: $input) {
              row { id }
              cells { fieldId value { uniqueId { prefix sequence display } } }
            }
          }
        "#,
        "variables": {
          "input": {
            "databaseId": target_id,
            "title": "Existing alpha",
            "cells": []
          }
        }
      }),
    )
    .await;
    let existing_row_id = gql_data(&create_row, &["createDatabaseRow", "row"])["id"]
      .as_str()
      .expect("existing row id")
      .to_string();
    let existing_unique_id = gql_data(&create_row, &["createDatabaseRow"])["cells"]
      .as_array()
      .expect("generated cells")
      .iter()
      .find(|cell| cell["fieldId"] == unique_field_id)
      .map(|cell| &cell["value"]["uniqueId"])
      .expect("generated UniqueId cell");
    let unique_prefix = existing_unique_id["prefix"].as_str().expect("UniqueId prefix");
    let unique_sequence = existing_unique_id["sequence"].as_i64().expect("UniqueId sequence");
    let unique_display = existing_unique_id["display"].as_str().expect("UniqueId display");
    let merge_body = yjs::markdown_to_yjs("Merged body", "Portable merge content.").expect("merge Yjs update");
    // One real collision with explicit portable content exercises Abort,
    // Overwrite and Rename against an identical input.
    let snapshot = json!({
      "schemaVersion": 3,
      "exportedAt": "2026-07-08T00:00:00Z",
      "source": { "product": "myoxus", "format": "database-json-snapshot" },
      "database": {
        "id": "database_0",
        "title": "Merge snapshot",
        "description": null,
        "fields": [
          { "id": "field_title", "name": "Title", "fieldType": "title", "config": { "kind": "title" }, "position": 0, "required": true, "readOnly": false },
          { "id": "field_unique", "name": "UID", "fieldType": "unique_id", "config": { "kind": "unique_id", "prefix": "T", "startNumber": 1, "padding": 3 }, "position": 1, "required": false, "readOnly": false }
        ],
        "views": [],
        "rows": [
          {
            "id": "row_fresh_one",
            "title": "Snapshot alpha",
            "position": 0,
            "contentDocument": {
              "documentKey": "merge-row-content",
              "title": "Merged body",
              "yjsUpdateBase64": STANDARD.encode(&merge_body),
              "assetKeys": []
            },
            "cells": [],
            "projections": [{
              "fieldId": "field_unique",
              "fieldType": "unique_id",
              "value": {
                "kind": "domain",
                "value": {
                  "kind": "unique_id",
                  "value": {
                    "prefix": unique_prefix,
                    "sequence": unique_sequence,
                    "display": unique_display
                  }
                }
              }
            }]
          }
        ],
        "rowTemplates": []
      },
      "databases": [],
      "filesManifest": []
    });
    let snapshot_bytes = serde_json::to_vec(&snapshot).expect("snapshot serialises");
    let field_mapping = json!([
      { "snapshotFieldId": "field_title", "target": target_title_field },
      { "snapshotFieldId": "field_unique", "target": unique_field_id }
    ]);
    let target_uuid = Uuid::parse_str(&target_id).expect("target Database UUID");
    let rows_before_abort: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_database_rows WHERE database_id = $1")
        .bind(target_uuid)
        .fetch_one(&pool)
        .await
        .expect("rows before Merge+Abort");
    let docs_before_abort: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("documents before Merge+Abort");
    let abort = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) { createdRowCount }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "MERGE",
            "conflictStrategy": "ABORT",
            "targetDatabaseId": target_id,
            "fieldMapping": field_mapping
          }
        }
      }),
      "merge-abort.json",
      &snapshot_bytes,
    )
    .await;
    assert!(
      gql_errors(&abort)
        .iter()
        .any(|error| error["extensions"]["code"] == "MIX_DATABASE_JSON_CONFLICT"),
      "Merge+Abort must reject the actual UniqueId collision: {abort:#}"
    );
    let rows_after_abort: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM workspace_database_rows WHERE database_id = $1")
        .bind(target_uuid)
        .fetch_one(&pool)
        .await
        .expect("rows after Merge+Abort");
    let docs_after_abort: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM docs WHERE workspace_id = $1")
      .bind(workspace_id)
      .fetch_one(&pool)
      .await
      .expect("documents after Merge+Abort");
    assert_eq!(rows_after_abort, rows_before_abort, "Merge+Abort wrote a Row");
    assert_eq!(docs_after_abort, docs_before_abort, "Merge+Abort wrote content");

    let overwrite = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              createdRowCount
              updatedRowCount
              skippedRowCount
              conflictWarnings { code }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "MERGE",
            "conflictStrategy": "OVERWRITE",
            "targetDatabaseId": target_id,
            "fieldMapping": field_mapping
          }
        }
      }),
      "merge-overwrite.json",
      &snapshot_bytes,
    )
    .await;
    let overwrite = gql_data(&overwrite, &["importDatabaseJson"]);
    assert_eq!(overwrite["createdRowCount"], 0);
    assert_eq!(overwrite["updatedRowCount"], 1);
    assert_eq!(overwrite["skippedRowCount"], 0);
    let (overwritten_title, overwritten_document_id): (String, Option<Uuid>) =
      sqlx::query_as("SELECT title, doc_id FROM workspace_database_rows WHERE id = $1")
        .bind(Uuid::parse_str(&existing_row_id).expect("existing Row UUID"))
        .fetch_one(&pool)
        .await
        .expect("Merge+Overwrite Row");
    assert_eq!(overwritten_title, "Snapshot alpha");
    assert!(overwritten_document_id.is_some(), "Merge+Overwrite must attach content");

    let rename = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
          mutation Import($file: Upload!, $input: ImportDatabaseJsonInput!) {
            importDatabaseJson(file: $file, input: $input) {
              mode
              conflictStrategy
              createdRowCount
              updatedRowCount
              skippedRowCount
              conflictWarnings { code message }
            }
          }
        "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "mode": "MERGE",
            "conflictStrategy": "RENAME",
            "targetDatabaseId": target_id,
            "fieldMapping": field_mapping
          }
        }
      }),
      "merge-rename.json",
      &snapshot_bytes,
    )
    .await;
    let result = gql_data(&rename, &["importDatabaseJson"]);
    assert_eq!(result["mode"], "MERGE");
    assert_eq!(result["conflictStrategy"], "RENAME");
    assert_eq!(result["createdRowCount"], 1, "Merge+Rename must append one Row");
    assert_eq!(result["updatedRowCount"], 0);
    assert_eq!(result["skippedRowCount"], 0);
    assert!(
      result["conflictWarnings"]
        .as_array()
        .is_some_and(|warnings| warnings.len() == 1 && warnings[0]["code"] == "MIX_DATABASE_JSON_CONFLICT"),
      "Merge+Rename must report the resolved conflict: {result:#}"
    );
    let renamed_content_count: i64 = sqlx::query_scalar(
      "SELECT COUNT(*) FROM workspace_database_rows WHERE database_id = $1 AND title = 'Snapshot alpha' AND doc_id IS NOT NULL",
    )
    .bind(target_uuid)
    .fetch_one(&pool)
    .await
    .expect("Merge+Rename content count");
    assert_eq!(renamed_content_count, 2, "Merge+Rename must create fresh content");

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_percent_field_type_roundtrips_graphql_csv_and_json() {
  helpers::block_on_large_stack("database-percent-field-type", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-percent-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id title }
            fields { id fieldType }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Percent Contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreatePercentField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config { kind percent { minValue maxValue } number { format } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Progress",
            "fieldType": "Percent",
            "config": { "percent": { "minValue": 0, "maxValue": 100 } },
            "required": false
          }
        }
      }),
    )
    .await;
    let field = gql_data(&field, &["createDatabaseField"]);
    let percent_field_id = field["id"].as_str().expect("percent field id");
    assert_eq!(field["fieldType"], "Percent");
    assert_eq!(field["config"]["kind"], "Percent");
    assert_eq!(field["config"]["percent"]["minValue"], 0.0);
    assert_eq!(field["config"]["percent"]["maxValue"], 100.0);
    assert!(
      field["config"]["number"].is_null(),
      "Percent must not be represented as a Number format"
    );

    let row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreatePercentRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells { fieldId value { kind percent number } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Task A",
            "cells": [
              { "fieldId": percent_field_id, "value": { "percent": 42.5 } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["value"]["kind"], "Percent");
    assert_eq!(row["cells"][0]["value"]["percent"], 42.5);
    assert!(row["cells"][0]["value"]["number"].is_null());

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidPercent($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": percent_field_id,
            "value": { "percent": 101 }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_PERCENT_RANGE_INVALID"
    );

    let csv_content = b"Task,Progress\nAlpha,42%\nBeta,0.42\n";
    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewPercentCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields { name fieldType config { kind percent { minValue maxValue } } }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Percent CSV"
          }
        }
      }),
      "percent.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Percent");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "Percent");

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportPercentCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database { database { id title } fields { id name fieldType config { kind percent { minValue maxValue } } } rowCount }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Percent CSV"
          }
        }
      }),
      "percent.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_percent_field_id = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "Percent")
      .and_then(|field| field["id"].as_str())
      .expect("imported percent field id");

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedPercentRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows { row { title } cells { fieldId value { kind percent number } } }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
            databaseJsonExport(databaseId: $databaseId) { content contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let alpha = rows
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .expect("Alpha row");
    let alpha_percent = alpha["cells"]
      .as_array()
      .expect("Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_percent_field_id)
      .expect("Alpha percent cell");
    assert_eq!(alpha_percent["value"]["kind"], "Percent");
    assert_eq!(alpha_percent["value"]["percent"], 42.0);
    assert!(alpha_percent["value"]["number"].is_null());
    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains("42%"),
      "CSV export must preserve percent type inference by exporting percent units with %: {csv_export:?}"
    );

    let json_export = workspace["databaseJsonExport"]["content"]
      .as_str()
      .expect("JSON export");
    assert_eq!(workspace["databaseJsonExport"]["contentType"], "application/json");
    let snapshot: Value = serde_json::from_str(json_export).expect("percent JSON snapshot");
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| field["fieldType"] == "percent" && field["config"]["kind"] == "percent"),
      "JSON snapshot must preserve Percent field schema: {snapshot:#}"
    );
    assert!(
      snapshot["database"]["rows"]
        .as_array()
        .expect("snapshot rows")
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .any(|cell| {
          cell["fieldType"] == "percent"
            && cell["value"]["kind"] == "domain"
            && cell["value"]["value"]["kind"] == "percent"
            && cell["value"]["value"]["value"] == 42.0
        }),
      "JSON snapshot must preserve Percent cell values: {snapshot:#}"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportPercentJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { fields { name fieldType config { kind percent { minValue maxValue } } } rowCount }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "percent.database.json",
      json_export.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_eq!(
      imported_json["warnings"]
        .as_array()
        .expect("JSON import warnings")
        .len(),
      0
    );
    assert_eq!(imported_json["database"]["rowCount"], 2);
    assert!(
      imported_json["database"]["fields"]
        .as_array()
        .expect("JSON imported fields")
        .iter()
        .any(|field| field["name"] == "Progress" && field["fieldType"] == "Percent"),
      "JSON import must recreate Percent fields: {imported_json:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_project_contract_foundation_roundtrips_rich_text_tags_and_progress_view() {
  helpers::block_on_large_stack("database-project-contract-foundation", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) =
      helpers::seed_user(&pool, &auth_store, "database-project-contract-foundation-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
            fields { id fieldType }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Project Contract Foundation",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let created_database = gql_data(&created, &["createDatabase"]);
    let database_id = created_database["database"]["id"].as_str().expect("database id");
    let title_field_id = created_database["fields"]
      .as_array()
      .expect("created fields")
      .iter()
      .find(|field| field["fieldType"] == "Title")
      .and_then(|field| field["id"].as_str())
      .expect("title field id");

    async fn create_foundation_field(
      app: &axum::Router,
      owner_session: Uuid,
      database_id: &str,
      name: &str,
      field_type: &str,
      config: Value,
    ) -> Value {
      let response = helpers::gql(
        app,
        owner_session,
        json!({
          "query": r#"
          mutation CreateField($input: CreateDatabaseFieldInput!) {
            createDatabaseField(input: $input) {
              id
              fieldType
              config {
                kind
                richText { maxPlainTextBytes }
                tags { maxCount }
                percent { minValue maxValue }
              }
            }
          }
        "#,
          "variables": {
            "input": {
              "databaseId": database_id,
              "name": name,
              "fieldType": field_type,
              "config": config
            }
          }
        }),
      )
      .await;
      gql_data(&response, &["createDatabaseField"]).clone()
    }

    let rich_text_field = create_foundation_field(
      &app,
      owner_session,
      database_id,
      "Description",
      "RichText",
      json!({ "richText": { "maxPlainTextBytes": 512 } }),
    )
    .await;
    let rich_text_field_id = rich_text_field["id"].as_str().expect("RichText field id");
    assert_eq!(rich_text_field["fieldType"], "RichText");
    assert_eq!(rich_text_field["config"]["kind"], "RichText");
    assert_eq!(rich_text_field["config"]["richText"]["maxPlainTextBytes"], 512);

    let tags_field = create_foundation_field(
      &app,
      owner_session,
      database_id,
      "Tags",
      "Tags",
      json!({ "tags": { "maxCount": 3 } }),
    )
    .await;
    let tags_field_id = tags_field["id"].as_str().expect("Tags field id");
    assert_eq!(tags_field["fieldType"], "Tags");
    assert_eq!(tags_field["config"]["tags"]["maxCount"], 3);

    let progress_field = create_foundation_field(
      &app,
      owner_session,
      database_id,
      "Progress",
      "Percent",
      json!({ "percent": { "minValue": 0, "maxValue": 100 } }),
    )
    .await;
    let progress_field_id = progress_field["id"].as_str().expect("Percent field id");

    let status_field = create_foundation_field(
      &app,
      owner_session,
      database_id,
      "Status",
      "Status",
      json!({ "status": {
        "defaultOptionId": "todo",
        "options": [
          { "id": "todo", "name": "To do", "position": 0, "colorRole": "database.status.todo", "group": "NotStarted" },
          { "id": "doing", "name": "Doing", "position": 1, "colorRole": "database.status.inProgress", "group": "Active" },
          { "id": "done", "name": "Done", "position": 2, "colorRole": "database.status.done", "group": "Complete" }
        ]
      } }),
    )
    .await;
    let status_field_id = status_field["id"].as_str().expect("Status field id");

    async fn create_workspace_tag(
      app: &axum::Router,
      owner_session: Uuid,
      workspace_id: Uuid,
      name: &str,
      color_role: &str,
    ) -> String {
      let response = helpers::gql(
        app,
        owner_session,
        json!({
          "query": "mutation($input: CreateWorkspaceTagInput!) { createWorkspaceTag(input: $input) { id } }",
          "variables": {
            "input": {
              "workspaceId": workspace_id,
              "name": name,
              "colorRole": color_role
            }
          }
        }),
      )
      .await;
      gql_data(&response, &["createWorkspaceTag"])["id"]
        .as_str()
        .expect("workspace tag id")
        .to_string()
    }

    let first_tag = create_workspace_tag(&app, owner_session, workspace_id, "Backend", "tag.blue").await;
    let second_tag = create_workspace_tag(&app, owner_session, workspace_id, "Release", "tag.green").await;
    let row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateProjectFoundationRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              fieldType
              value {
                kind
                richText { plainText document }
                tags
                percent
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Task A",
            "cells": [
              {
                "fieldId": rich_text_field_id,
                "value": {
                  "richText": {
                    "document": {
                      "type": "doc",
                      "content": [{
                      "type": "paragraph",
                        "content": [
                          { "type": "text", "text": "Ship " },
                          {
                            "type": "text",
                            "text": "the foundation",
                            "marks": [
                              { "type": "bold" },
                              { "type": "link", "attrs": { "href": "https://example.test/spec" } }
                            ]
                          }
                        ]
                      }]
                    }
                  }
                }
              },
              { "fieldId": tags_field_id, "value": { "tags": [first_tag, second_tag] } },
              { "fieldId": status_field_id, "value": { "status": "doing" } },
              { "fieldId": progress_field_id, "value": { "percent": 35 } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert!(
      row["cells"]
        .as_array()
        .expect("row cells")
        .iter()
        .any(|cell| cell["fieldType"] == "RichText" && cell["value"]["richText"]["plainText"] == "Ship the foundation"),
      "RichText cell must roundtrip through GraphQL: {row:#}"
    );
    let rich_text_cell = row["cells"]
      .as_array()
      .expect("row cells")
      .iter()
      .find(|cell| cell["fieldType"] == "RichText")
      .expect("RichText cell");
    assert_eq!(
      rich_text_cell["value"]["richText"]["document"]["content"][0]["content"][1]["marks"][0]["type"],
      "bold"
    );
    assert_eq!(
      rich_text_cell["value"]["richText"]["document"]["content"][0]["content"][1]["marks"][1]["attrs"]["href"],
      "https://example.test/spec"
    );
    let invalid_rich_text = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { fieldId } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": rich_text_field_id,
          "value": { "richText": { "document": {
            "type": "doc",
            "content": [{ "type": "heading", "attrs": { "level": 1 }, "content": [] }]
          } } }
        } }
      }),
    )
    .await;
    assert_eq!(
      invalid_rich_text["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_RICH_TEXT_INVALID"
    );
    let persisted_rich_text: Value =
      sqlx::query_scalar("SELECT value_json FROM workspace_database_cell_values WHERE row_id = $1 AND field_id = $2")
        .bind(Uuid::parse_str(row_id).expect("row UUID"))
        .bind(Uuid::parse_str(rich_text_field_id).expect("field UUID"))
        .fetch_one(&pool)
        .await
        .expect("persisted RichText cell");
    assert_eq!(
      persisted_rich_text["plainText"], "Ship the foundation",
      "unsupported RichText must not partially replace the prior value"
    );
    let csv_export = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query RichTextCsv($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseCsvExport(databaseId: $databaseId) { content }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let rich_text_csv = gql_data(&csv_export, &["workspace", "databaseCsvExport"])["content"]
      .as_str()
      .expect("RichText CSV content");
    assert!(
      rich_text_csv.contains("Ship the foundation"),
      "CSV export must use the server plain-text projection: {rich_text_csv}"
    );
    assert!(
      !rich_text_csv.contains("marks") && !rich_text_csv.contains("https://example.test/spec"),
      "CSV export must not leak canonical RichText JSON or mark metadata: {rich_text_csv}"
    );

    let csv_rich_text_import = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportRichTextCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database { database { id } fields { id name fieldType } }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "CSV RichText projection",
            "firstRowIsHeader": true,
            "mapping": [
              { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
              { "sourceIndex": 1, "importColumn": true, "fieldName": "Description", "fieldType": "RichText", "isTitle": false }
            ]
          }
        }
      }),
      "rich-text.csv",
      b"Task,Description\nImported task,Plain **source** text\n",
    )
    .await;
    let imported_rich_text = gql_data(&csv_rich_text_import, &["importDatabaseCsv"]);
    assert_eq!(
      imported_rich_text["errors"]
        .as_array()
        .expect("RichText CSV errors")
        .len(),
      0,
      "RichText CSV import must succeed: {csv_rich_text_import:#}"
    );
    let csv_database_id = imported_rich_text["database"]["database"]["id"]
      .as_str()
      .expect("RichText CSV database id");
    let csv_field_id = imported_rich_text["database"]["fields"]
      .as_array()
      .expect("RichText CSV fields")
      .iter()
      .find(|field| field["fieldType"] == "RichText")
      .and_then(|field| field["id"].as_str())
      .expect("RichText CSV field id");
    let csv_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query RichTextCsvRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows { cells { fieldId value { richText { plainText document } } } }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": csv_database_id
        }
      }),
    )
    .await;
    let csv_cell = gql_data(&csv_rows, &["workspace"])["databaseRows"]["rows"][0]["cells"]
      .as_array()
      .expect("RichText CSV cells")
      .iter()
      .find(|cell| cell["fieldId"] == csv_field_id)
      .expect("RichText CSV cell");
    assert_eq!(csv_cell["value"]["richText"]["plainText"], "Plain **source** text");
    assert_eq!(
      csv_cell["value"]["richText"]["document"]["content"][0]["content"][0],
      json!({ "type": "text", "text": "Plain **source** text" }),
      "CSV import must construct canonical plain RichText without interpreting markup"
    );
    assert!(
      row["cells"]
        .as_array()
        .expect("row cells")
        .iter()
        .any(|cell| cell["fieldType"] == "Tags" && cell["value"]["tags"].as_array().expect("tags").len() == 2),
      "Tags cell must roundtrip through GraphQL: {row:#}"
    );

    let third_tag = create_workspace_tag(&app, owner_session, workspace_id, "Frontend", "tag.red").await;
    let archived_first = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: WorkspaceTagLifecycleInput!) { archiveWorkspaceTag(input: $input) { id archived } }",
        "variables": { "input": { "workspaceId": workspace_id, "tagId": first_tag } }
      }),
    )
    .await;
    assert_eq!(gql_data(&archived_first, &["archiveWorkspaceTag"])["archived"], true);

    let retain_archived_while_editing = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { value { tags } } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": tags_field_id,
            "value": { "tags": [first_tag, second_tag, third_tag] }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&retain_archived_while_editing, &["updateDatabaseCellValue"])["value"]["tags"],
      json!([first_tag, second_tag, third_tag])
    );

    let remove_archived = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { value { tags } } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": tags_field_id,
            "value": { "tags": [second_tag, third_tag] }
          }
        }
      }),
    )
    .await;
    let _ = gql_data(&remove_archived, &["updateDatabaseCellValue"]);

    let readd_archived = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { fieldId } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": tags_field_id,
            "value": { "tags": [first_tag, second_tag, third_tag] }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      readd_archived["errors"][0]["extensions"]["code"],
      "MIX_WORKSPACE_TAG_ARCHIVED_WRITE"
    );

    let progress_view = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateProgressView($input: CreateDatabaseViewInput!) {
          createDatabaseView(input: $input) {
            id
            viewKind
            config {
              kind
              progress {
                titleFieldId
                progressFieldId
                groupFieldId
                visibleFieldIds
                sort { fieldId direction }
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Progress",
            "viewKind": "Progress",
            "config": {
              "progress": {
                "titleFieldId": title_field_id,
                "progressFieldId": progress_field_id,
                "groupFieldId": status_field_id,
                "visibleFieldIds": [title_field_id, progress_field_id, status_field_id, rich_text_field_id],
                "sort": [{ "fieldId": progress_field_id, "direction": "Desc" }],
                "filter": []
              }
            }
          }
        }
      }),
    )
    .await;
    let progress_view = gql_data(&progress_view, &["createDatabaseView"]);
    assert_eq!(progress_view["viewKind"], "Progress");
    assert_eq!(progress_view["config"]["kind"], "Progress");
    assert_eq!(
      progress_view["config"]["progress"]["progressFieldId"],
      progress_field_id
    );
    assert_eq!(progress_view["config"]["progress"]["groupFieldId"], status_field_id);
    let progress_view_id = progress_view["id"].as_str().expect("progress view id");

    let done_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDoneProgressRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) { row { id title } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Task B",
            "cells": [
              { "fieldId": status_field_id, "value": { "status": "done" } },
              { "fieldId": progress_field_id, "value": { "percent": 100 } }
            ]
          }
        }
      }),
    )
    .await;
    assert_eq!(gql_data(&done_row, &["createDatabaseRow"])["row"]["title"], "Task B");

    let draft_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDraftProgressRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) { row { id title } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Task C",
            "cells": [
              { "fieldId": status_field_id, "value": { "status": "doing" } }
            ]
          }
        }
      }),
    )
    .await;
    assert_eq!(gql_data(&draft_row, &["createDatabaseRow"])["row"]["title"], "Task C");

    let progress_summary = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query DatabaseProgress($workspaceId: String!, $databaseId: ID!, $viewId: ID!) {
          workspace(id: $workspaceId) {
            databaseProgress(databaseId: $databaseId, viewId: $viewId) {
              viewId
              progressFieldId
              groupFieldId
              totalCount
              completedCount
              incompleteCount
              blockedCount
              overdueCount
              averageProgress
              groups {
                key
                totalCount
                completedCount
                incompleteCount
                blockedCount
                overdueCount
                averageProgress
              }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id,
          "viewId": progress_view_id
        }
      }),
    )
    .await;
    let summary = &gql_data(&progress_summary, &["workspace"])["databaseProgress"];
    assert_eq!(summary["viewId"], progress_view_id);
    assert_eq!(summary["progressFieldId"], progress_field_id);
    assert_eq!(summary["groupFieldId"], status_field_id);
    assert_eq!(summary["totalCount"], 3);
    assert_eq!(summary["completedCount"], 1);
    assert_eq!(summary["incompleteCount"], 2);
    assert_eq!(summary["blockedCount"], 0);
    assert_eq!(summary["overdueCount"], 0);
    assert_eq!(summary["averageProgress"], 45.0);
    let groups = summary["groups"].as_array().expect("progress groups");
    let complete_group = groups
      .iter()
      .find(|group| group["key"] == "complete")
      .expect("complete progress group");
    assert_eq!(complete_group["totalCount"], 1);
    assert_eq!(complete_group["completedCount"], 1);
    assert_eq!(complete_group["averageProgress"], 100.0);
    let active_group = groups
      .iter()
      .find(|group| group["key"] == "active")
      .expect("active progress group");
    assert_eq!(active_group["totalCount"], 2);
    assert_eq!(active_group["completedCount"], 0);
    assert_eq!(active_group["averageProgress"], 17.5);

    let invalid_progress_view = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidProgressView($input: CreateDatabaseViewInput!) {
          createDatabaseView(input: $input) { id }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Invalid Progress",
            "viewKind": "Progress",
            "config": {
              "progress": {
                "titleFieldId": title_field_id,
                "progressFieldId": tags_field_id,
                "visibleFieldIds": [title_field_id, tags_field_id]
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid_progress_view["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_VIEW_CONFIG_INVALID"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_project_creation_builds_profile_roles_presets_and_views() {
  helpers::block_on_large_stack("database-project-create-contract", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-project-create").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let response = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateProject($input: CreateProjectInput!) {
          createProject(input: $input) {
            database {
              id
              profileKind
              profileStructurePreset
              profileConfig
              title
            }
            fields {
              id
              name
              fieldType
              required
              config {
                kind
                select { options { id name position colorRole } }
                status { defaultOptionId options { id group position colorRole } }
                currency { defaultCurrency allowCurrencyOverride minValue maxValue }
                percent { minValue maxValue }
                relation { targetDatabaseId allowMultiple maxTargets }
                uniqueId { prefix startNumber padding }
              }
            }
            views {
              id
              name
              viewKind
              config {
                kind
                kanban { titleFieldId groupFieldId visibleFieldIds }
                table { titleFieldId visibleFieldIds }
                list { titleFieldId visibleFieldIds }
                progress { titleFieldId progressFieldId groupFieldId visibleFieldIds }
                calendar { titleFieldId dateFieldId visibleFieldIds }
                timeline { titleFieldId startFieldId endFieldId visibleFieldIds zoom }
                gallery { titleFieldId coverFieldId visibleFieldIds }
              }
            }
            fieldRoles { roleKey rowKindScope fieldId required config }
            viewRoles { roleKey viewId required }
          }
        }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Product Platform",
            "priorityPreset": "FiveStep",
            "complexityPreset": "ThreeStep",
            "structurePreset": "PhasesAndMilestones"
          }
        }
      }),
    )
    .await;
    let record = gql_data(&response, &["createProject"]);
    let database_id = record["database"]["id"].as_str().expect("database id");
    assert_eq!(record["database"]["profileKind"], "Project");
    assert_eq!(record["database"]["profileStructurePreset"], "phases_and_milestones");
    assert_eq!(record["database"]["profileConfig"]["priorityPreset"], "fiveStep");
    assert_eq!(record["database"]["profileConfig"]["complexityPreset"], "threeStep");
    assert_eq!(record["database"]["profileConfig"]["rowIdRole"], "task.id");

    let fields = record["fields"].as_array().expect("project fields");
    let field_by_name = fields
      .iter()
      .map(|field| (field["name"].as_str().expect("field name"), field))
      .collect::<std::collections::BTreeMap<_, _>>();
    let expected_fields = [
      ("Task", "Title", true),
      ("Description", "RichText", true),
      ("Status", "Status", true),
      ("Priority", "Select", true),
      ("Tags", "Tags", true),
      ("Owner", "User", true),
      ("Assignees", "Users", true),
      ("Assigned by", "User", true),
      ("Progress", "Percent", true),
      ("Task ID", "UniqueId", false),
      ("Complexity", "Select", false),
      ("Effort", "Duration", false),
      ("Cost", "Currency", false),
      ("Start date", "DateTime", false),
      ("Due date", "DateTime", false),
      ("Completed at", "DateTime", false),
      ("Attachments", "Files", false),
      ("Linked document", "DocumentLink", false),
      ("Parent", "Relation", false),
      ("Dependencies", "Relation", false),
      ("Blocked by", "Relation", false),
      ("Watchers", "Users", false),
      ("Acceptance criteria", "RichText", false),
      ("Phase", "Relation", true),
      ("Milestone", "Relation", true),
    ];
    assert_eq!(field_by_name.len(), expected_fields.len());
    for (name, field_type, required) in expected_fields {
      let field = field_by_name
        .get(name)
        .unwrap_or_else(|| panic!("missing Project field {name}"));
      assert_eq!(
        field["fieldType"], field_type,
        "Project field {name} must use the semantic field kind"
      );
      assert_eq!(
        field["required"], required,
        "Project field {name} requiredness must match its semantic roles"
      );
    }

    let priority_options = field_by_name["Priority"]["config"]["select"]["options"]
      .as_array()
      .expect("priority options")
      .iter()
      .map(|option| option["id"].as_str().expect("priority option id"))
      .collect::<Vec<_>>();
    assert_eq!(
      priority_options,
      vec![
        "priority.lowest",
        "priority.low",
        "priority.normal",
        "priority.high",
        "priority.critical"
      ]
    );
    let complexity_options = field_by_name["Complexity"]["config"]["select"]["options"]
      .as_array()
      .expect("complexity options")
      .iter()
      .map(|option| option["id"].as_str().expect("complexity option id"))
      .collect::<Vec<_>>();
    assert_eq!(
      complexity_options,
      vec!["complexity.simple", "complexity.moderate", "complexity.complex"]
    );
    assert_eq!(
      field_by_name["Cost"]["config"]["currency"]["defaultCurrency"], "EUR",
      "Project cost must inherit the server/Admin localization default currency"
    );
    assert_eq!(
      field_by_name["Cost"]["config"]["currency"]["allowCurrencyOverride"],
      true
    );
    assert_eq!(field_by_name["Task ID"]["config"]["uniqueId"]["prefix"], "TASK-");
    assert_eq!(
      field_by_name["Status"]["config"]["status"]["defaultOptionId"],
      "status.todo"
    );

    for relation_name in ["Parent", "Dependencies", "Blocked by", "Phase", "Milestone"] {
      assert_eq!(
        field_by_name[relation_name]["config"]["relation"]["targetDatabaseId"], database_id,
        "{relation_name} must be a self-database relation in the Project profile"
      );
    }

    let roles = record["fieldRoles"].as_array().expect("project field roles");
    let role_by_key = roles
      .iter()
      .map(|role| (role["roleKey"].as_str().expect("role key"), role))
      .collect::<std::collections::BTreeMap<_, _>>();
    let expected_roles = [
      ("task.title", "task", true),
      ("task.description", "task", true),
      ("task.status", "task", true),
      ("task.priority", "task", true),
      ("task.tags", "task", true),
      ("task.owner", "task", true),
      ("task.assignees", "task", true),
      ("task.assignedBy", "task", true),
      ("task.progress", "task", true),
      ("task.publicId", "task", false),
      ("task.complexity", "task", false),
      ("task.effort", "task", false),
      ("task.cost", "task", false),
      ("task.startDate", "task", false),
      ("task.dueDate", "task", false),
      ("task.completedAt", "task", false),
      ("task.attachments", "task", false),
      ("task.document", "task", false),
      ("task.parent", "task", false),
      ("task.dependencies", "task", false),
      ("task.blockedBy", "task", false),
      ("task.watchers", "task", false),
      ("task.acceptanceCriteria", "task", false),
      ("task.phase", "task", true),
      ("task.milestone", "task", true),
      ("phase.title", "phase", true),
      ("phase.description", "phase", false),
      ("phase.status", "phase", false),
      ("phase.startDate", "phase", false),
      ("phase.dueDate", "phase", false),
      ("milestone.title", "milestone", true),
      ("milestone.description", "milestone", false),
      ("milestone.status", "milestone", false),
      ("milestone.dueDate", "milestone", false),
      ("milestone.phase", "milestone", true),
    ];
    assert_eq!(role_by_key.len(), expected_roles.len() + 1);
    for (role_key, scope, required) in expected_roles {
      let role = role_by_key
        .get(role_key)
        .unwrap_or_else(|| panic!("missing Project role {role_key}"));
      assert_eq!(role["rowKindScope"], scope, "Project role {role_key} scope");
      assert_eq!(
        role["required"], required,
        "Project role {role_key} requiredness must match the catalog"
      );
      assert!(
        role["fieldId"].as_str().is_some_and(|value| !value.is_empty()),
        "Project role {role_key} must map to an explicit field id"
      );
    }
    assert_eq!(role_by_key["task.assignedBy"]["config"]["manualEdit"], false);
    assert_eq!(
      role_by_key["task.completedAt"]["config"]["maintainedBy"],
      "statusCompletionPolicy"
    );

    let views = record["views"].as_array().expect("project views");
    let view_by_name = views
      .iter()
      .map(|view| (view["name"].as_str().expect("view name"), view))
      .collect::<std::collections::BTreeMap<_, _>>();
    let view_roles = record["viewRoles"].as_array().expect("project view roles");
    for (name, kind) in [
      ("Kanban", "Kanban"),
      ("Table", "Table"),
      ("List", "List"),
      ("Progress", "Progress"),
      ("Calendar", "Calendar"),
      ("Timeline", "Timeline"),
      ("Gallery", "Gallery"),
    ] {
      assert_eq!(
        view_by_name
          .get(name)
          .unwrap_or_else(|| panic!("missing Project view {name}"))["viewKind"],
        kind
      );
    }
    for (name, role_key) in [
      ("Table", "project.table"),
      ("Kanban", "project.kanban"),
      ("List", "project.list"),
      ("Progress", "project.progress"),
      ("Calendar", "project.calendar"),
      ("Timeline", "project.timeline"),
      ("Gallery", "project.gallery"),
    ] {
      let role = view_roles
        .iter()
        .find(|role| role["roleKey"] == role_key)
        .unwrap_or_else(|| panic!("missing Project view role {role_key}"));
      assert_eq!(role["viewId"], view_by_name[name]["id"]);
      assert_eq!(role["required"], true);
    }
    assert_eq!(
      view_by_name["Kanban"]["config"]["kanban"]["groupFieldId"], field_by_name["Status"]["id"],
      "Project Kanban must group by task.status"
    );
    assert_eq!(
      view_by_name["Kanban"]["config"]["kanban"]["visibleFieldIds"],
      json!([
        field_by_name["Task"]["id"],
        field_by_name["Description"]["id"],
        field_by_name["Status"]["id"],
        field_by_name["Priority"]["id"],
        field_by_name["Assignees"]["id"],
        field_by_name["Due date"]["id"],
        field_by_name["Progress"]["id"],
      ]),
      "new Project Kanban must persist task.description directly after task.title"
    );
    assert_eq!(
      view_by_name["Calendar"]["config"]["calendar"]["dateFieldId"], field_by_name["Due date"]["id"],
      "Project Calendar must use task.dueDate"
    );
    assert_eq!(
      view_by_name["Timeline"]["config"]["timeline"]["startFieldId"], field_by_name["Start date"]["id"],
      "Project Timeline must use task.startDate"
    );
    assert_eq!(
      view_by_name["Timeline"]["config"]["timeline"]["endFieldId"], field_by_name["Due date"]["id"],
      "Project Timeline must use task.dueDate as its end field"
    );
    assert_eq!(
      view_by_name["Gallery"]["config"]["gallery"]["coverFieldId"], field_by_name["Attachments"]["id"],
      "Project Gallery must use task.attachments as its cover field"
    );
    assert_eq!(
      view_by_name["Progress"]["config"]["progress"]["progressFieldId"], field_by_name["Progress"]["id"],
      "Project Progress must use task.progress"
    );
    assert_eq!(
      view_by_name["Progress"]["config"]["progress"]["groupFieldId"], field_by_name["Phase"]["id"],
      "Project Progress defaults to phase grouping when phases are enabled"
    );

    let progress_view_id = view_by_name["Progress"]["id"].as_str().expect("Progress view id");
    let renamed_progress = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseViewInput!) { updateDatabaseView(input: $input) { id name } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": progress_view_id,
            "name": "Delivery overview"
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_errors(&renamed_progress)[0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );

    let incompatible_kind = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseViewInput!) { updateDatabaseView(input: $input) { id viewKind } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": progress_view_id,
            "viewKind": "Table"
          }
        }
      }),
    )
    .await;
    assert_eq!(
      incompatible_kind["errors"][0]["extensions"]["code"], "MIX_DATABASE_FORBIDDEN",
      "required semantic view roles must reject incompatible kind changes"
    );

    let reordered_ids = views
      .iter()
      .rev()
      .map(|view| view["id"].as_str().expect("Project view id"))
      .collect::<Vec<_>>();
    let reordered = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: ReorderDatabaseViewsInput!) { reorderDatabaseViews(input: $input) { id } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewIds": reordered_ids
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_errors(&reordered)[0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );
    let stable_roles = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!) { workspace(id: $workspaceId) { database(databaseId: $databaseId) { viewRoles { roleKey viewId } } } }",
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let stable_roles = gql_data(&stable_roles, &["workspace", "database", "viewRoles"])
      .as_array()
      .expect("stable Project view roles");
    assert!(stable_roles.iter().all(|role| {
      view_roles
        .iter()
        .any(|original| original["roleKey"] == role["roleKey"] && original["viewId"] == role["viewId"])
    }));

    let created_task = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseRowInput!) { createDatabaseRow(input: $input) { row { rowKind title } } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Project task without template"
          }
        }
      }),
    )
    .await;
    let created_task = gql_data(&created_task, &["createDatabaseRow", "row"]);
    assert_eq!(created_task["rowKind"], "task");
    assert_eq!(created_task["title"], "Project task without template");

    let replacement_progress = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseViewInput!) { createDatabaseView(input: $input) { id viewKind } }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Delivery progress",
            "viewKind": "Progress",
            "config": {
              "progress": {
                "titleFieldId": field_by_name["Task"]["id"],
                "progressFieldId": field_by_name["Progress"]["id"],
                "groupFieldId": field_by_name["Phase"]["id"],
                "visibleFieldIds": [field_by_name["Task"]["id"], field_by_name["Progress"]["id"]],
                "sort": [],
                "filter": []
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_errors(&replacement_progress)[0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );
    let replacement_progress_id = progress_view_id;
    let required_delete = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DeleteDatabaseViewInput!) { deleteDatabaseView(input: $input) }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": view_by_name["Progress"]["id"]
          }
        }
      }),
    )
    .await;
    assert_eq!(
      required_delete["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );
    let replaced_delete = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DeleteDatabaseViewInput!) { deleteDatabaseView(input: $input) }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": view_by_name["Progress"]["id"],
            "replacementViewId": replacement_progress_id
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_errors(&replaced_delete)[0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );
    let replaced_roles = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!) { workspace(id: $workspaceId) { database(databaseId: $databaseId) { viewRoles { roleKey viewId } } } }",
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let progress_role = gql_data(&replaced_roles, &["workspace", "database", "viewRoles"])
      .as_array()
      .expect("replaced view roles")
      .iter()
      .find(|role| role["roleKey"] == "project.progress")
      .expect("replaced Progress role");
    assert_eq!(progress_role["viewId"], replacement_progress_id);

    let optional_field_id = field_by_name["Complexity"]["id"].as_str().expect("Complexity field id");
    let deleted_optional_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DeleteDatabaseFieldInput!) { deleteDatabaseField(input: $input) }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "fieldId": optional_field_id
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_errors(&deleted_optional_field)[0]["extensions"]["code"],
      "MIX_DATABASE_FORBIDDEN"
    );
    let optional_role_count: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM database_field_roles WHERE database_id = $1 AND field_id = $2")
        .bind(Uuid::parse_str(database_id).expect("database UUID"))
        .bind(Uuid::parse_str(optional_field_id).expect("field UUID"))
        .fetch_one(&pool)
        .await
        .expect("optional role count");
    assert_eq!(
      optional_role_count, 1,
      "protected optional field retains its semantic role"
    );

    let required_field_delete = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DeleteDatabaseFieldInput!) { deleteDatabaseField(input: $input) }",
        "variables": {
          "input": {
            "databaseId": database_id,
            "fieldId": field_by_name["Status"]["id"]
          }
        }
      }),
    )
    .await;
    assert_eq!(
      required_field_delete["errors"][0]["extensions"]["code"], "MIX_DATABASE_FORBIDDEN",
      "required semantic roles must be rejected before the repository delete"
    );

    let generic = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateGenericDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id profileKind profileStructurePreset profileConfig }
            views { id viewKind }
            fieldRoles { roleKey }
            viewRoles { roleKey }
          }
        }
        "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Generic database",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let generic = gql_data(&generic, &["createDatabase"]);
    assert_eq!(generic["database"]["profileKind"], "Generic");
    assert!(generic["database"]["profileStructurePreset"].is_null());
    assert!(
      generic["fieldRoles"].as_array().is_some_and(Vec::is_empty),
      "generic Database creation must not silently create Project roles"
    );
    assert!(
      generic["viewRoles"].as_array().is_some_and(Vec::is_empty),
      "generic Database creation must not silently create Project view roles"
    );
    let generic_table_id = generic["views"][0]["id"].as_str().expect("generic Table view id");
    let cross_database_role = execute_catalog_pinned_content_fixture(
      &pool,
      sqlx::query(
        "UPDATE database_view_roles SET view_id = $1 WHERE database_id = $2 AND role_key = 'project.progress'",
      )
      .bind(Uuid::parse_str(generic_table_id).expect("generic Table UUID"))
      .bind(Uuid::parse_str(database_id).expect("Project database UUID")),
    )
    .await;
    assert!(
      cross_database_role.is_err(),
      "managed structure protection rejects replacing the Progress binding with a foreign View"
    );
    let kind_mismatched_role = execute_catalog_pinned_content_fixture(
      &pool,
      sqlx::query(
        "UPDATE database_view_roles SET view_id = $1 WHERE database_id = $2 AND role_key = 'project.progress'",
      )
      .bind(Uuid::parse_str(view_by_name["Kanban"]["id"].as_str().expect("Kanban view id")).expect("Kanban UUID"))
      .bind(Uuid::parse_str(database_id).expect("Project database UUID")),
    )
    .await;
    assert!(
      kind_mismatched_role.is_err(),
      "managed structure protection rejects replacing the Progress binding with a Kanban View"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_currency_field_type_roundtrips_graphql_csv_and_json() {
  helpers::block_on_large_stack("database-currency-field-type", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-currency-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id title }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Currency Contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateCurrencyField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config {
              kind
              currency { defaultCurrency allowCurrencyOverride minValue maxValue }
              number { format }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Budget",
            "fieldType": "Currency",
            "config": {
              "currency": {
                "defaultCurrency": "EUR",
                "allowCurrencyOverride": false,
                "minValue": 0,
                "maxValue": 1000
              }
            },
            "required": false
          }
        }
      }),
    )
    .await;
    let field = gql_data(&field, &["createDatabaseField"]);
    let currency_field_id = field["id"].as_str().expect("currency field id");
    assert_eq!(field["fieldType"], "Currency");
    assert_eq!(field["config"]["kind"], "Currency");
    assert_eq!(field["config"]["currency"]["defaultCurrency"], "EUR");
    assert_eq!(field["config"]["currency"]["allowCurrencyOverride"], false);
    assert_eq!(field["config"]["currency"]["minValue"], 0.0);
    assert_eq!(field["config"]["currency"]["maxValue"], 1000.0);
    assert!(
      field["config"]["number"].is_null(),
      "Currency must not be represented as a Number format"
    );

    let row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateCurrencyRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              value {
                kind
                currency { amount currencyCode }
                number
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Task A",
            "cells": [
              {
                "fieldId": currency_field_id,
                "value": { "currency": { "amount": 42.5, "currencyCode": "EUR" } }
              }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["value"]["kind"], "Currency");
    assert_eq!(row["cells"][0]["value"]["currency"]["amount"], 42.5);
    assert_eq!(row["cells"][0]["value"]["currency"]["currencyCode"], "EUR");
    assert!(row["cells"][0]["value"]["number"].is_null());

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidCurrency($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": currency_field_id,
            "value": { "currency": { "amount": 43, "currencyCode": "USD" } }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_CURRENCY_INVALID"
    );

    let csv_content = b"Task,Budget\nAlpha,42 EUR\nBeta,GBP 12.5\n";
    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewCurrencyCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields {
              name
              fieldType
              config { kind currency { defaultCurrency allowCurrencyOverride minValue maxValue } }
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Currency CSV"
          }
        }
      }),
      "currency.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Currency");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "Currency");
    assert_eq!(
      preview["inferredFields"][1]["config"]["currency"]["defaultCurrency"],
      "EUR"
    );

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportCurrencyCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { id name fieldType config { kind currency { defaultCurrency allowCurrencyOverride minValue maxValue } } }
              rowCount
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Currency CSV"
          }
        }
      }),
      "currency.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_currency_field_id = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "Currency")
      .and_then(|field| field["id"].as_str())
      .expect("imported currency field id");

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedCurrencyRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells { fieldId value { kind currency { amount currencyCode } number } }
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
            databaseJsonExport(databaseId: $databaseId) { content contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let alpha = rows
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .expect("Alpha row");
    let alpha_currency = alpha["cells"]
      .as_array()
      .expect("Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_currency_field_id)
      .expect("Alpha currency cell");
    assert_eq!(alpha_currency["value"]["kind"], "Currency");
    assert_eq!(alpha_currency["value"]["currency"]["amount"], 42.0);
    assert_eq!(alpha_currency["value"]["currency"]["currencyCode"], "EUR");
    assert!(alpha_currency["value"]["number"].is_null());

    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains("42 EUR"),
      "CSV export must preserve currency amount and code: {csv_export:?}"
    );
    assert!(
      csv_export.contains("12.5 GBP"),
      "CSV export must preserve mixed imported currency codes: {csv_export:?}"
    );

    let json_export = workspace["databaseJsonExport"]["content"]
      .as_str()
      .expect("JSON export");
    assert_eq!(workspace["databaseJsonExport"]["contentType"], "application/json");
    let snapshot: Value = serde_json::from_str(json_export).expect("currency JSON snapshot");
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| field["fieldType"] == "currency" && field["config"]["kind"] == "currency"),
      "JSON snapshot must preserve Currency field schema: {snapshot:#}"
    );
    assert!(
      snapshot["database"]["rows"]
        .as_array()
        .expect("snapshot rows")
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .any(|cell| {
          cell["fieldType"] == "currency"
            && cell["value"]["kind"] == "domain"
            && cell["value"]["value"]["kind"] == "currency"
            && cell["value"]["value"]["value"]["amount"] == 42.0
            && cell["value"]["value"]["value"]["currencyCode"] == "EUR"
        }),
      "JSON snapshot must preserve Currency cell values: {snapshot:#}"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportCurrencyJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { fields { name fieldType config { kind currency { defaultCurrency allowCurrencyOverride minValue maxValue } } } rowCount }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "currency.database.json",
      json_export.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_eq!(
      imported_json["warnings"]
        .as_array()
        .expect("JSON import warnings")
        .len(),
      0
    );
    assert_eq!(imported_json["database"]["rowCount"], 2);
    assert!(
      imported_json["database"]["fields"]
        .as_array()
        .expect("JSON imported fields")
        .iter()
        .any(|field| field["name"] == "Budget" && field["fieldType"] == "Currency"),
      "JSON import must recreate Currency fields: {imported_json:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_duration_field_type_roundtrips_graphql_csv_and_json() {
  helpers::block_on_large_stack("database-duration-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-duration-roundtrip-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let csv_content = b"Task,Effort\nAlpha,90 min\nBeta,2h\n";

    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewDurationCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields { name fieldType config { kind duration { displayUnit minMinutes maxMinutes } } }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Duration CSV"
          }
        }
      }),
      "duration.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Duration");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "Duration");
    assert_eq!(
      preview["inferredFields"][1]["config"]["duration"]["displayUnit"],
      "Minutes"
    );

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportDurationCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { id name fieldType config { kind duration { displayUnit minMinutes maxMinutes } } }
              rowCount
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Duration CSV"
          }
        }
      }),
      "duration.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_duration_field_id = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "Duration")
      .and_then(|field| field["id"].as_str())
      .expect("imported duration field id");

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedDurationRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells { fieldId value { kind duration { minutes } number } }
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
            databaseJsonExport(databaseId: $databaseId) { content contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let alpha = rows
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .expect("Alpha row");
    let alpha_duration = alpha["cells"]
      .as_array()
      .expect("Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_duration_field_id)
      .expect("Alpha duration cell");
    assert_eq!(alpha_duration["value"]["kind"], "Duration");
    assert_eq!(alpha_duration["value"]["duration"]["minutes"], 90);
    assert!(alpha_duration["value"]["number"].is_null());

    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains("90 min"),
      "CSV export must preserve canonical duration minutes: {csv_export:?}"
    );
    assert!(
      csv_export.contains("120 min"),
      "CSV export must normalize hour input to canonical minutes: {csv_export:?}"
    );

    let json_export = workspace["databaseJsonExport"]["content"]
      .as_str()
      .expect("JSON export");
    assert_eq!(workspace["databaseJsonExport"]["contentType"], "application/json");
    let snapshot: Value = serde_json::from_str(json_export).expect("duration JSON snapshot");
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| field["fieldType"] == "duration" && field["config"]["kind"] == "duration"),
      "JSON snapshot must preserve Duration field schema: {snapshot:#}"
    );
    assert!(
      snapshot["database"]["rows"]
        .as_array()
        .expect("snapshot rows")
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .any(|cell| {
          cell["fieldType"] == "duration"
            && cell["value"]["kind"] == "domain"
            && cell["value"]["value"]["kind"] == "duration"
            && cell["value"]["value"]["value"]["minutes"] == 90
        }),
      "JSON snapshot must preserve Duration cell values: {snapshot:#}"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportDurationJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { fields { name fieldType config { kind duration { displayUnit minMinutes maxMinutes } } } rowCount }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "duration.database.json",
      json_export.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_eq!(
      imported_json["warnings"]
        .as_array()
        .expect("JSON import warnings")
        .len(),
      0
    );
    assert_eq!(imported_json["database"]["rowCount"], 2);
    assert!(
      imported_json["database"]["fields"]
        .as_array()
        .expect("JSON imported fields")
        .iter()
        .any(|field| field["name"] == "Effort" && field["fieldType"] == "Duration"),
      "JSON import must recreate Duration fields: {imported_json:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_date_time_field_roundtrips_graphql_and_csv() {
  helpers::block_on_large_stack("database-date-time-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-date-time-roundtrip-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDateTimeDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) { database { id } }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "DateTime contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let date_time_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDateTimeField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config { kind dateTime { defaultTimeZone allowReminders } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Starts at",
            "fieldType": "DateTime",
            "config": {
              "dateTime": {
                "defaultTimeZone": "Europe/Berlin",
                "allowReminders": true
              }
            }
          }
        }
      }),
    )
    .await;
    let date_time_field = gql_data(&date_time_field, &["createDatabaseField"]);
    let date_time_field_id = date_time_field["id"].as_str().expect("DateTime field id");
    assert_eq!(date_time_field["fieldType"], "DateTime");
    assert_eq!(
      date_time_field["config"]["dateTime"]["defaultTimeZone"],
      "Europe/Berlin"
    );
    assert_eq!(date_time_field["config"]["dateTime"]["allowReminders"], true);

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDateTimeRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              fieldType
              value {
                kind
                dateTime { start end allDay timeZone }
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Kickoff",
            "cells": [
              {
                "fieldId": date_time_field_id,
                "value": {
                  "dateTime": {
                    "start": "2026-07-06T09:00:00Z",
                    "end": "2026-07-06T10:00:00Z",
                    "allDay": false,
                    "timeZone": "Europe/Berlin"
                  }
                }
              }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["fieldType"], "DateTime");
    assert_eq!(row["cells"][0]["value"]["kind"], "DateTime");
    assert_eq!(
      row["cells"][0]["value"]["dateTime"]["start"],
      "2026-07-06T09:00:00+00:00"
    );
    assert_eq!(row["cells"][0]["value"]["dateTime"]["timeZone"], "Europe/Berlin");
    assert!(
      row["cells"][0]["value"]["dateTime"].get("reminders").is_none(),
      "personal reminders must never be projected as shared Cell content"
    );

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidDateTime($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": date_time_field_id,
            "value": {
              "dateTime": {
                "start": "2026-07-06T10:00:00Z",
                "end": "2026-07-06T09:00:00Z",
                "allDay": false,
                "timeZone": "Europe/Berlin"
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("DateTime validation error code"),
      "MIX_DATABASE_DATE_TIME_INVALID"
    );

    let csv_content = b"Task,Due At\nAlpha,2026-07-07T08:30:00Z\nBeta,2026-07-08T11:45:00Z/2026-07-08T12:15:00Z\n";
    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewDateTimeCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields { name fieldType config { kind dateTime { defaultTimeZone allowReminders } } }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "DateTime CSV"
          }
        }
      }),
      "date-time.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(
      preview["errors"].as_array().expect("preview errors").len(),
      0,
      "DateTime CSV preview errors: {preview:#}"
    );
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "DateTime");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "DateTime");
    assert_eq!(
      preview["inferredFields"][1]["config"]["dateTime"]["defaultTimeZone"],
      "UTC"
    );

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportDateTimeCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { id name fieldType config { kind dateTime { defaultTimeZone allowReminders } } }
              rowCount
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "DateTime CSV"
          }
        }
      }),
      "date-time.csv",
      csv_content,
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    assert_eq!(imported["database"]["rowCount"], 2);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_date_time_field = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "DateTime")
      .expect("imported DateTime field");
    let imported_date_time_field_id = imported_date_time_field["id"]
      .as_str()
      .expect("imported DateTime field id");

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedDateTimeRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells { fieldId value { kind dateTime { start end allDay timeZone } date { start } } }
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let beta = rows.iter().find(|row| row["row"]["title"] == "Beta").expect("Beta row");
    let beta_date_time = beta["cells"]
      .as_array()
      .expect("Beta cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_date_time_field_id)
      .expect("Beta DateTime cell");
    assert_eq!(beta_date_time["value"]["kind"], "DateTime");
    assert_eq!(
      beta_date_time["value"]["dateTime"]["start"],
      "2026-07-08T11:45:00+00:00"
    );
    assert_eq!(beta_date_time["value"]["dateTime"]["end"], "2026-07-08T12:15:00+00:00");
    assert!(beta_date_time["value"]["date"].is_null());

    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains("2026-07-08T11:45:00+00:00/2026-07-08T12:15:00+00:00"),
      "CSV export must preserve DateTime range instants: {csv_export:?}"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_row_reminders_are_personal_and_follow_cell_lifecycle() {
  helpers::block_on_large_stack("database-row-reminders", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-reminder-owner").await;
    let (member_id, member_session) = helpers::seed_user(&pool, &auth_store, "database-reminder-member").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    sqlx::query(
      "INSERT INTO workspace_memberships (workspace_id, user_id, role, status, joined_at) VALUES ($1, $2, 'Collaborator', 'Accepted', now())",
    )
    .bind(workspace_id)
    .bind(member_id)
    .execute(&pool)
    .await
    .expect("seed reminder collaborator");

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseInput!) { createDatabase(input: $input) { database { id } } }",
        "variables": { "input": {
          "workspaceId": workspace_id.to_string(),
          "title": "Personal reminders",
          "initialViewKind": "Table"
        }}
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");
    let field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseFieldInput!) { createDatabaseField(input: $input) { id } }",
        "variables": { "input": {
          "databaseId": database_id,
          "name": "Due",
          "fieldType": "DateTime",
          "config": { "dateTime": { "defaultTimeZone": "UTC", "allowReminders": true } }
        }}
      }),
    )
    .await;
    let field_id = gql_data(&field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("field id");
    let start = (Utc::now() + chrono::Duration::days(2)).to_rfc3339();
    let row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseRowInput!) { createDatabaseRow(input: $input) { row { id } } }",
        "variables": { "input": {
          "databaseId": database_id,
          "title": "Private target",
          "cells": [{
            "fieldId": field_id,
            "value": { "dateTime": {
              "start": start,
              "allDay": false,
              "timeZone": "UTC"
            }}
          }]
        }}
      }),
    )
    .await;
    let row_id = gql_data(&row, &["createDatabaseRow"])["row"]["id"]
      .as_str()
      .expect("row id");

    let set = |session, offset_minutes| {
      helpers::gql(
        &app,
        session,
        json!({
          "query": "mutation($input: SetDatabaseRowReminderInput!) { setDatabaseRowReminder(input: $input) { id offsetMinutes scheduleRevision } }",
          "variables": { "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": field_id,
            "offsetMinutes": offset_minutes
          }}
        }),
      )
    };
    let owner_reminder = set(owner_session, 10).await;
    let owner_reminder_id = gql_data(&owner_reminder, &["setDatabaseRowReminder"])["id"]
      .as_str()
      .expect("owner reminder id");
    let owner_repeat = set(owner_session, 10).await;
    assert_eq!(
      gql_data(&owner_repeat, &["setDatabaseRowReminder"])["id"],
      owner_reminder_id,
      "same personal offset must update one durable reminder"
    );
    let member_reminder = set(member_session, 30).await;
    gql_data(&member_reminder, &["setDatabaseRowReminder"]);

    for (session, expected_offset) in [(owner_session, 10), (member_session, 30)] {
      let listed = helpers::gql(
        &app,
        session,
        json!({
          "query": "query($workspaceId: String!, $databaseId: ID!, $rowId: ID!, $fieldId: ID!) { workspace(id: $workspaceId) { databaseRowReminders(databaseId: $databaseId, rowId: $rowId, fieldId: $fieldId) { offsetMinutes } } }",
          "variables": {
            "workspaceId": workspace_id.to_string(),
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": field_id
          }
        }),
      )
      .await;
      assert_eq!(
        gql_data(&listed, &["workspace", "databaseRowReminders"]),
        &json!([{ "offsetMinutes": expected_offset }])
      );
    }

    let cross_user_delete = helpers::gql(
      &app,
      member_session,
      json!({
        "query": "mutation($input: DeleteDatabaseRowReminderInput!) { deleteDatabaseRowReminder(input: $input) }",
        "variables": { "input": {
          "databaseId": database_id,
          "reminderId": owner_reminder_id
        }}
      }),
    )
    .await;
    assert_eq!(
      cross_user_delete["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_REMINDER_NOT_FOUND"
    );

    let owner_delete = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: DeleteDatabaseRowReminderInput!) { deleteDatabaseRowReminder(input: $input) }",
        "variables": { "input": {
          "databaseId": database_id,
          "reminderId": owner_reminder_id
        }}
      }),
    )
    .await;
    assert_eq!(gql_data(&owner_delete, &["deleteDatabaseRowReminder"]), true);
    gql_data(&set(owner_session, 10).await, &["setDatabaseRowReminder"]);

    let past = set(owner_session, 3_000).await;
    assert_eq!(past["errors"][0]["extensions"]["code"], "MIX_DATABASE_REMINDER_PAST");
    for offset in [20, 30, 40, 50] {
      gql_data(&set(owner_session, offset).await, &["setDatabaseRowReminder"]);
    }
    let over_limit = set(owner_session, 60).await;
    assert_eq!(
      over_limit["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_REMINDER_LIMIT"
    );

    let disabled_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseFieldInput!) { createDatabaseField(input: $input) { id } }",
        "variables": { "input": {
          "databaseId": database_id,
          "name": "Private disabled date",
          "fieldType": "DateTime",
          "config": { "dateTime": { "defaultTimeZone": "UTC", "allowReminders": false } }
        }}
      }),
    )
    .await;
    let disabled_field_id = gql_data(&disabled_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("disabled DateTime field id");
    let disabled = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: SetDatabaseRowReminderInput!) { setDatabaseRowReminder(input: $input) { id } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": disabled_field_id,
          "offsetMinutes": 10
        }}
      }),
    )
    .await;
    assert_eq!(
      disabled["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_REMINDER_DISABLED"
    );

    let deep_link_target = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!, $rowId: ID!) { workspace(id: $workspaceId) { databaseRow(databaseId: $databaseId, rowId: $rowId) { row { id title } } } }",
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id,
          "rowId": row_id
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&deep_link_target, &["workspace", "databaseRow", "row"])["title"],
      "Private target"
    );

    let revisions_before: Vec<(Uuid, i64, chrono::DateTime<Utc>)> = sqlx::query_as(
      "SELECT id, schedule_revision, trigger_at FROM database_row_reminders WHERE row_id = $1 AND status IN ('scheduled', 'claimed') ORDER BY id",
    )
    .bind(Uuid::parse_str(row_id).expect("row UUID"))
    .fetch_all(&pool)
    .await
    .expect("reminder generations before stale Cell edit");
    let stale_cell = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { editRevision } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": field_id,
          "value": { "dateTime": {
            "start": (Utc::now() + chrono::Duration::days(3)).to_rfc3339(),
            "allDay": false,
            "timeZone": "UTC"
          }},
          "expectedEditRevision": 999,
          "force": false
        }}
      }),
    )
    .await;
    assert_eq!(
      stale_cell["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_CELL_CONFLICT"
    );
    let revisions_after: Vec<(Uuid, i64, chrono::DateTime<Utc>)> = sqlx::query_as(
      "SELECT id, schedule_revision, trigger_at FROM database_row_reminders WHERE row_id = $1 AND status IN ('scheduled', 'claimed') ORDER BY id",
    )
    .bind(Uuid::parse_str(row_id).expect("row UUID"))
    .fetch_all(&pool)
    .await
    .expect("reminder generations after stale Cell edit");
    assert_eq!(
      revisions_after, revisions_before,
      "a stale Cell write must not reschedule reminders"
    );

    let immediate_due = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { editRevision } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": field_id,
          "value": { "dateTime": {
            "start": (Utc::now() + chrono::Duration::minutes(5)).to_rfc3339(),
            "allDay": false,
            "timeZone": "UTC"
          }}
        }}
      }),
    )
    .await;
    gql_data(&immediate_due, &["updateDatabaseCellValue"]);
    let due_count: i64 = sqlx::query_scalar(
      "SELECT COUNT(*) FROM database_row_reminders WHERE row_id = $1 AND status = 'scheduled' AND trigger_at <= now()",
    )
    .bind(Uuid::parse_str(row_id).expect("row UUID"))
    .fetch_one(&pool)
    .await
    .expect("immediately due reminders after DateTime edit");
    assert_eq!(
      due_count, 6,
      "moving the DateTime inside every offset makes each personal reminder due"
    );

    let cleared = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: ClearDatabaseCellValueInput!) { clearDatabaseCellValue(input: $input) { hasValue } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": field_id
        }}
      }),
    )
    .await;
    assert_eq!(gql_data(&cleared, &["clearDatabaseCellValue"])["hasValue"], false);
    let cancelled: i64 =
      sqlx::query_scalar("SELECT COUNT(*) FROM database_row_reminders WHERE row_id = $1 AND status = 'cancelled'")
        .bind(Uuid::parse_str(row_id).expect("row UUID"))
        .fetch_one(&pool)
        .await
        .expect("cancelled reminder count");
    assert_eq!(
      cancelled, 7,
      "clearing the DateTime Cell cancels every user's live reminder"
    );

    let restored = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { editRevision } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": field_id,
          "value": { "dateTime": {
            "start": (Utc::now() + chrono::Duration::days(2)).to_rfc3339(),
            "allDay": false,
            "timeZone": "UTC"
          }}
        }}
      }),
    )
    .await;
    gql_data(&restored, &["updateDatabaseCellValue"]);
    gql_data(&set(owner_session, 10).await, &["setDatabaseRowReminder"]);
    let disable_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseFieldInput!) { updateDatabaseField(input: $input) { id config { dateTime { allowReminders } } } }",
        "variables": { "input": {
          "databaseId": database_id,
          "fieldId": field_id,
          "config": { "dateTime": { "defaultTimeZone": "UTC", "allowReminders": false } }
        }}
      }),
    )
    .await;
    assert_eq!(
      gql_data(&disable_field, &["updateDatabaseField"])["config"]["dateTime"]["allowReminders"],
      false
    );
    let live_after_disable: i64 = sqlx::query_scalar(
      "SELECT COUNT(*) FROM database_row_reminders WHERE field_id = $1 AND status IN ('scheduled', 'claimed')",
    )
    .bind(Uuid::parse_str(field_id).expect("field UUID"))
    .fetch_one(&pool)
    .await
    .expect("live reminders after field disable");
    assert_eq!(
      live_after_disable, 0,
      "field disable cancels pending personal reminders transactionally"
    );

    helpers::cleanup_users(&pool, &[owner_id, member_id]).await;
  });
}

#[test]
fn database_reminder_dispatch_uses_redis_and_rejects_stale_generations() {
  helpers::block_on_large_stack("database-reminder-dispatch", || async {
    let (app, pool, auth_store, state) = helpers::setup_app_with_template_registry_and_sql_notifications_state().await;
    let stale_user_ids: Vec<Uuid> =
      sqlx::query_scalar("SELECT id FROM users WHERE email LIKE 'database-reminder-dispatch-%@example.test'")
        .fetch_all(&pool)
        .await
        .expect("find stale dispatch-test users");
    helpers::cleanup_users(&pool, &stale_user_ids).await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-reminder-dispatch-owner").await;
    let (member_id, _) = helpers::seed_user(&pool, &auth_store, "database-reminder-dispatch-member").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let redis_url = std::env::var("TEST_REDIS_URL").unwrap_or_else(|_| "redis://127.0.0.1:6380".to_string());
    let prefix = format!("pdb15-reminder-{}", Uuid::new_v4());
    let body = AssertUnwindSafe(async {
    execute_catalog_pinned_content_fixture(&pool, sqlx::query(
      "INSERT INTO workspace_memberships (workspace_id, user_id, role, status, joined_at) VALUES ($1, $2, 'Collaborator', 'Accepted', now())",
    )
    .bind(workspace_id)
    .bind(member_id)
    )
    .await
    .expect("dispatch collaborator membership");
    let scheduled_for = Utc::now() + chrono::Duration::hours(2);
    let created_database = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseInput!) { createDatabase(input: $input) { database { id } } }",
        "variables": { "input": {
          "workspaceId": workspace_id.to_string(),
          "title": "Dispatch DB",
          "initialViewKind": "Table"
        }}
      }),
    )
    .await;
    let database_id = Uuid::parse_str(
      gql_data(&created_database, &["createDatabase"])["database"]["id"]
        .as_str()
        .expect("dispatch database id"),
    )
    .expect("dispatch database UUID");
    let created_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseFieldInput!) { createDatabaseField(input: $input) { id config { dateTime { defaultTimeZone allowReminders } } } }",
        "variables": { "input": {
          "databaseId": database_id.to_string(),
          "name": "Due",
          "fieldType": "DateTime",
          "config": { "dateTime": { "defaultTimeZone": "UTC", "allowReminders": true } }
        }}
      }),
    )
    .await;
    let field_id = Uuid::parse_str(
      gql_data(&created_field, &["createDatabaseField"])["id"]
        .as_str()
        .expect("dispatch field id"),
    )
    .expect("dispatch field UUID");
    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseRowInput!) { createDatabaseRow(input: $input) { row { id } } }",
        "variables": { "input": {
          "databaseId": database_id.to_string(),
          "title": "Dispatch target",
          "cells": [{
            "fieldId": field_id.to_string(),
            "value": { "dateTime": {
              "start": scheduled_for,
              "end": null,
              "allDay": false,
              "timeZone": "UTC"
            }}
          }]
        }}
      }),
    )
    .await;
    let row_id = Uuid::parse_str(
      gql_data(&created_row, &["createDatabaseRow"])["row"]["id"]
        .as_str()
        .expect("dispatch row id"),
    )
    .expect("dispatch row UUID");

    let repo = Arc::new(PgDatabaseRepository::new(pool.clone(), crate::helpers::database_starter_catalog()));
    let queue = RedisQueue::new(&redis_url, prefix.clone()).expect("isolated reminder Redis queue");
    let service = Arc::new(DatabaseServices::new(
      repo.clone(),
      DocService::new(Arc::new(SqlxDocStore::new(pool.clone()))),
      Arc::new(PermissionService::new(auth_store.clone())),
      DatabaseLimits::default(), Arc::new(myoxus_infrastructure::workspace::SqlxWorkspaceStore::new(pool.clone(), crate::helpers::database_starter_catalog())), crate::helpers::database_starter_catalog(),
      myoxus_application::database::DatabaseServiceDependencies::disabled()
        .with_job_queue(Arc::new(DatabaseRedisQueue { queue: queue.clone() })),
    ));
    let mut reminder = service
      .reminders.set_database_row_reminder(owner_id, database_id, row_id, field_id, 10)
      .await
      .expect("set reminder through canonical Application path");
    let due_trigger = chrono::DateTime::parse_from_rfc3339("2000-01-01T00:00:00Z")
      .expect("fixed due trigger")
      .with_timezone(&Utc);
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE database_row_reminders SET trigger_at = $2, updated_at = now() WHERE id = $1")
      .bind(reminder.id)
      .bind(due_trigger)
      )
      .await
      .expect("advance reminder to deterministic due instant");
    reminder.trigger_at = due_trigger;

    let outcome = service
      .reminders.fire_due_database_row_reminders(1)
      .await
      .expect("dispatch due reminder");
    assert_eq!(outcome.claimed_count, 1);
    assert_eq!(outcome.enqueued_count, 1);
    assert_eq!(outcome.failed_count, 0);
    let job = queue
      .dequeue("notification", 1)
      .await
      .expect("dequeue notification job")
      .expect("notification job exists");
    assert_eq!(job.name, "notification.sendDatabaseRowReminder");
    assert_eq!(job.data["notificationType"], "database_row_reminder");
    assert_eq!(
      job.data["idempotencyKey"],
      format!(
        "database.row.reminder:{}:{}",
        reminder.id,
        reminder.trigger_at.timestamp()
      )
    );
    let envelope: DatabaseRowReminderDispatchEnvelope =
      serde_json::from_value(job.data["dispatch"].clone()).expect("typed dispatch envelope");
    assert!(
      service
        .reminders.validate_database_row_reminder_dispatch(&envelope)
        .await
        .expect("validate current dispatch")
        .is_some()
    );
    let notification_service = state.notification().clone();
    let first_notification = myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
      &notification_service,
      None,
      Some(service.reminders.as_ref()),
      &job.data,
    )
    .await
    .expect("consume current reminder dispatch")
    .expect("current reminder creates a notification");
    let retried_notification = myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
      &notification_service,
      None,
      Some(service.reminders.as_ref()),
      &job.data,
    )
    .await
    .expect("retry current reminder dispatch")
    .expect("idempotent retry returns the persisted notification");
    assert_eq!(retried_notification.id, first_notification.id);
    let notifications = notification_service
      .list_notifications(
        owner_id,
        NotificationListRequest {
          first: Some(10),
          include_read: Some(true),
          ..Default::default()
        },
      )
      .await
      .expect("list persisted reminder notification");
    assert_eq!(
      notifications.total_count, 1,
      "stable idempotency key prevents duplicates"
    );
    assert_eq!(notifications.edges[0].node.notification_type, "database_row_reminder");
    assert_eq!(notifications.edges[0].node.payload["rowTitle"], "Dispatch target");
    assert!(notifications.edges[0].node.payload.get("scheduleRevision").is_none());
    assert!(notifications.edges[0].node.payload.get("reminderId").is_none());

    let invalid_envelope = myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
      &notification_service,
      None,
      None,
      &json!({"dispatch":{"reminderId":"PRIVATE ENVELOPE SECRET"}}),
    )
    .await;
    assert!(
      matches!(invalid_envelope,Err(JobError::Permanent(ref message)) if message=="invalid database reminder dispatch envelope")
    );
    // A corrupt legacy value may appear in PostgreSQL's decoder error. The
    // worker keeps retry classification without copying that value into status.
    let valid_date: Value =
      sqlx::query_scalar("SELECT value_json FROM workspace_database_cell_values WHERE row_id=$1 AND field_id=$2")
        .bind(row_id)
        .bind(field_id)
        .fetch_one(&pool)
        .await
        .unwrap();
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE workspace_database_cell_values SET value_json=jsonb_set(value_json,'{start}',to_jsonb($3::text)) WHERE row_id=$1 AND field_id=$2")
        .bind(row_id).bind(field_id).bind("PRIVATE REMINDER DATE SECRET")).await.unwrap();
    let corrupt = myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
      &notification_service,
      None,
      Some(service.reminders.as_ref()),
      &job.data,
    )
    .await;
    let corrupt_feed=helpers::gql(&app,owner_session,json!({"query":"query{currentUser{notifications(pagination:{first:10},filter:{types:[DatabaseRowReminder],includeRead:true}){totalCount edges{node{id body}}}}}"})).await;
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE workspace_database_cell_values SET value_json=$3 WHERE row_id=$1 AND field_id=$2")
      .bind(row_id)
      .bind(field_id)
      .bind(valid_date)
      )
      .await
      .unwrap();
    assert!(
      matches!(corrupt,Err(JobError::Retryable(ref message)) if message=="database reminder eligibility lookup failed")
    );
    assert!(corrupt_feed.get("errors").is_none(), "{corrupt_feed}");
    assert!(
      !corrupt_feed.to_string().contains("PRIVATE"),
      "public decoder errors must not copy stored values"
    );
    let corrupt_feed = &corrupt_feed["data"]["currentUser"]["notifications"];
    assert_eq!(corrupt_feed["totalCount"], 1);
    let node = &corrupt_feed["edges"][0]["node"];
    assert_eq!(node["id"], first_notification.id.to_string());
    assert_eq!(node["body"]["state"], "Unavailable");
    for key in [
      "rowTitle",
      "fieldName",
      "scheduledFor",
      "allDay",
      "timeZone",
      "targetKind",
    ] {
      assert!(node["body"][key].is_null());
    }

    repo
      .upsert_database_row_reminder(DatabaseRowReminder {
        id: Uuid::new_v4(),
        workspace_id,
        database_id,
        row_id,
        field_id,
        user_id: owner_id,
        offset_minutes: 20,
        trigger_at: due_trigger + chrono::Duration::minutes(1),
        status: DatabaseRowReminderStatus::Scheduled,
        schedule_revision: 1,
        claim_token: None,
        claim_expires_at: None,
        claim_attempts: 0,
        fired_at: None,
        cancelled_at: None,
        created_at: Utc::now(),
        updated_at: Utc::now(),
      })
      .await
      .expect("paused notification reminder fixture");
    let paused_outcome = service
      .reminders.fire_due_database_row_reminders(1)
      .await
      .expect("enqueue reminder while notification consumer is paused");
    assert_eq!(paused_outcome.enqueued_count, 1);
    let paused_job = queue
      .dequeue("notification", 1)
      .await
      .expect("dequeue paused notification job")
      .expect("paused notification job exists");
    let paused_envelope: DatabaseRowReminderDispatchEnvelope =
      serde_json::from_value(paused_job.data["dispatch"].clone()).expect("paused dispatch envelope");

    service
      .editing.update_cell_value(
        owner_id,
        database_id,
        row_id,
        field_id,
        DatabaseCellValueData::DateTime(DatabaseDateTimeValue {
          start: scheduled_for + chrono::Duration::days(1),
          end: None,
          all_day: false,
          time_zone: "UTC".to_string(),
        }),
      )
      .await
      .expect("reschedule DateTime after notification enqueue");
    assert!(
      service
        .reminders.validate_database_row_reminder_dispatch(&paused_envelope)
        .await
        .expect("validate stale dispatch")
        .is_none(),
      "a DateTime edit after enqueue must invalidate the old Redis generation"
    );
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
      None,
        Some(service.reminders.as_ref()),
        &paused_job.data,
      )
      .await
      .expect("consume stale reminder dispatch")
      .is_none(),
      "the notification handler must acknowledge a stale generation without publishing"
    );
    assert_eq!(
      notification_service
        .list_notifications(
          owner_id,
          NotificationListRequest {
            first: Some(10),
            include_read: Some(true),
            ..Default::default()
          },
        )
        .await
        .expect("list after stale dispatch")
        .total_count,
      1,
      "rescheduling while the notification consumer is paused must not create a stale notification"
    );

    let retry = repo
      .upsert_database_row_reminder(DatabaseRowReminder {
        id: Uuid::new_v4(),
        workspace_id,
        database_id,
        row_id,
        field_id,
        user_id: owner_id,
        offset_minutes: 30,
        trigger_at: due_trigger + chrono::Duration::minutes(2),
        status: DatabaseRowReminderStatus::Scheduled,
        schedule_revision: 1,
        claim_token: None,
        claim_expires_at: None,
        claim_attempts: 0,
        fired_at: None,
        cancelled_at: None,
        created_at: Utc::now(),
        updated_at: Utc::now(),
      })
      .await
      .expect("retry reminder fixture");
    let failing_service = DatabaseServices::new(
      repo.clone(),
      DocService::new(Arc::new(SqlxDocStore::new(pool.clone()))),
      Arc::new(PermissionService::new(auth_store.clone())),
      DatabaseLimits::default(), Arc::new(myoxus_infrastructure::workspace::SqlxWorkspaceStore::new(pool.clone(), crate::helpers::database_starter_catalog())), crate::helpers::database_starter_catalog(),
      myoxus_application::database::DatabaseServiceDependencies::disabled()
        .with_job_queue(Arc::new(FailingReminderQueue)),
    );
    let failed = failing_service
      .reminders.fire_due_database_row_reminders(1)
      .await
      .expect("queue outage is a retryable batch outcome");
    assert_eq!(failed.failed_count, 1);
    let retry_state: String = sqlx::query_scalar("SELECT status FROM database_row_reminders WHERE id = $1")
      .bind(retry.id)
      .fetch_one(&pool)
      .await
      .expect("retry reminder status");
    assert_eq!(retry_state, "scheduled", "queue failure releases the claim for retry");
    assert!(
      repo
        .cancel_database_row_reminder(database_id, retry.id, owner_id, Utc::now())
        .await
        .expect("cancel retry fixture")
    );

    let inaccessible = repo
      .upsert_database_row_reminder(DatabaseRowReminder {
        id: Uuid::new_v4(),
        workspace_id,
        database_id,
        row_id,
        field_id,
        user_id: member_id,
        offset_minutes: 45,
        trigger_at: due_trigger + chrono::Duration::minutes(3),
        status: DatabaseRowReminderStatus::Scheduled,
        schedule_revision: 1,
        claim_token: None,
        claim_expires_at: None,
        claim_attempts: 0,
        fired_at: None,
        cancelled_at: None,
        created_at: Utc::now(),
        updated_at: Utc::now(),
      })
      .await
      .expect("membership-loss reminder fixture");
    assert_eq!(
      service
        .reminders.fire_due_database_row_reminders(1)
        .await
        .expect("enqueue membership-loss reminder")
        .enqueued_count,
      1
    );
    let inaccessible_job = queue
      .dequeue("notification", 1)
      .await
      .expect("dequeue membership-loss job")
      .expect("membership-loss job exists");
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("DELETE FROM workspace_memberships WHERE workspace_id = $1 AND user_id = $2")
      .bind(workspace_id)
      .bind(member_id)
      )
      .await
      .expect("remove reminder recipient membership");
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
      None,
        Some(service.reminders.as_ref()),
        &inaccessible_job.data,
      )
      .await
      .expect("consume inaccessible reminder dispatch")
      .is_none()
    );
    let inaccessible_status: String = sqlx::query_scalar("SELECT status FROM database_row_reminders WHERE id = $1")
      .bind(inaccessible.id)
      .fetch_one(&pool)
      .await
      .expect("inaccessible reminder status");
    assert_eq!(inaccessible_status, "cancelled");
    assert_eq!(notification_service.unread_count(member_id).await.unwrap(), 0);

    let clear_target = repo
      .upsert_database_row_reminder(DatabaseRowReminder {
        id: Uuid::new_v4(),
        workspace_id,
        database_id,
        row_id,
        field_id,
        user_id: owner_id,
        offset_minutes: 70,
        trigger_at: due_trigger + chrono::Duration::minutes(4),
        status: DatabaseRowReminderStatus::Scheduled,
        schedule_revision: 1,
        claim_token: None,
        claim_expires_at: None,
        claim_attempts: 0,
        fired_at: None,
        cancelled_at: None,
        created_at: Utc::now(),
        updated_at: Utc::now(),
      })
      .await
      .expect("clear-after-enqueue reminder fixture");
    assert_eq!(
      service
        .reminders.fire_due_database_row_reminders(1)
        .await
        .expect("enqueue clear-after-enqueue reminder")
        .enqueued_count,
      1
    );
    let clear_job = queue
      .dequeue("notification", 1)
      .await
      .expect("dequeue clear-after-enqueue job")
      .expect("clear-after-enqueue job exists");
    service
      .editing.clear_cell_value(owner_id, database_id, row_id, field_id)
      .await
      .expect("clear DateTime while notification consumer is paused");
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
      None,
        Some(service.reminders.as_ref()),
        &clear_job.data,
      )
      .await
      .expect("consume cleared reminder dispatch")
      .is_none()
    );
    assert_eq!(
      sqlx::query_scalar::<_, String>("SELECT status FROM database_row_reminders WHERE id = $1")
        .bind(clear_target.id)
        .fetch_one(&pool)
        .await
        .expect("cleared reminder status"),
      "cancelled"
    );

    service
      .editing.update_cell_value(
        owner_id,
        database_id,
        row_id,
        field_id,
        DatabaseCellValueData::DateTime(DatabaseDateTimeValue {
          start: Utc::now() + chrono::Duration::days(1),
          end: None,
          all_day: false,
          time_zone: "UTC".to_string(),
        }),
      )
      .await
      .expect("restore DateTime for delete-after-enqueue case");
    let delete_target = repo
      .upsert_database_row_reminder(DatabaseRowReminder {
        id: Uuid::new_v4(),
        workspace_id,
        database_id,
        row_id,
        field_id,
        user_id: owner_id,
        offset_minutes: 80,
        trigger_at: due_trigger + chrono::Duration::minutes(5),
        status: DatabaseRowReminderStatus::Scheduled,
        schedule_revision: 1,
        claim_token: None,
        claim_expires_at: None,
        claim_attempts: 0,
        fired_at: None,
        cancelled_at: None,
        created_at: Utc::now(),
        updated_at: Utc::now(),
      })
      .await
      .expect("delete-after-enqueue reminder fixture");
    assert_eq!(
      service
        .reminders.fire_due_database_row_reminders(1)
        .await
        .expect("enqueue delete-after-enqueue reminder")
        .enqueued_count,
      1
    );
    let delete_job = queue
      .dequeue("notification", 1)
      .await
      .expect("dequeue delete-after-enqueue job")
      .expect("delete-after-enqueue job exists");
    service
      .editing.delete_row(owner_id, database_id, row_id)
      .await
      .expect("delete Row while notification consumer is paused");
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
      None,
        Some(service.reminders.as_ref()),
        &delete_job.data,
      )
      .await
      .expect("consume deleted reminder dispatch")
      .is_none()
    );
    assert_eq!(
      sqlx::query_scalar::<_, String>("SELECT status FROM database_row_reminders WHERE id = $1")
        .bind(delete_target.id)
        .fetch_one(&pool)
        .await
        .expect("deleted reminder status"),
      "cancelled"
    );

    // Task reminders retain enabled DateTime semantics, but their current
    // canonical status gates both scheduling and already queued generations.
    use myoxus_domain::database::{DatabaseEditPrecondition, DatabaseStatusGroup};
    let project = helpers::gql(&app, owner_session, json!({
        "query":"mutation($i:CreateProjectInput!){createProject(input:$i){database{id} fieldRoles{roleKey fieldId}}}",
        "variables":{"i":{"workspaceId":workspace_id,"title":"Open Task reminders","structurePreset":"TasksOnly","priorityPreset":"ThreeStep","complexityPreset":"ThreeStep"}}
      })).await;
    let project = gql_data(&project, &["createProject"]);
    let task_database: Uuid = project["database"]["id"].as_str().unwrap().parse().unwrap();
    let status: Uuid = project["fieldRoles"]
      .as_array()
      .unwrap()
      .iter()
      .find(|role| role["roleKey"] == "task.status")
      .unwrap()["fieldId"]
      .as_str()
      .unwrap()
      .parse()
      .unwrap();
    // The installed Start role is a reminder-enabled DateTime outside task.dueDate.
    let custom: Uuid = project["fieldRoles"].as_array().unwrap().iter()
      .find(|role|role["roleKey"] == "task.startDate").unwrap()["fieldId"].as_str().unwrap().parse().unwrap();
    let all_day = DatabaseDateTimeValue {
      start: Utc::now() + chrono::Duration::days(3),
      end: None,
      all_day: true,
      time_zone: "Europe/Berlin".into(),
    };
    let task = service
      .editing
      .create_row(
        owner_id,
        task_database,
        Some("Personal Task reminder".into()),
        vec![(custom, DatabaseCellValueData::DateTime(all_day.clone()))],
      )
      .await
      .unwrap();
    let task = task.row.id;
    let record = repo.get_database(task_database).await.unwrap().unwrap();
    let mut status_config = record
      .fields
      .iter()
      .find(|field| field.id == status)
      .unwrap()
      .config
      .clone();
    let DatabaseFieldConfig::Status(ref mut options) = status_config else {
      panic!("Status config")
    };
    let open = options.default_option_id.clone();
    let complete = options
      .options
      .iter()
      .find(|option| option.group == DatabaseStatusGroup::Complete)
      .unwrap()
      .id
      .clone();
    let all_day_reminder = service
      .reminders
      .set_database_row_reminder(owner_id, task_database, task, custom, 60)
      .await
      .unwrap();
    assert_eq!(
      all_day_reminder.trigger_at,
      myoxus_domain::database::database_row_reminder_trigger_at(&all_day, 60).unwrap(),
      "non-UTC date-only baseline remains canonical"
    );
    service
      .reminders
      .delete_database_row_reminder(owner_id, task_database, all_day_reminder.id)
      .await
      .unwrap();

    async fn queue_task_reminder(
      service: &DatabaseServices,
      pool: &PgPool,
      queue: &RedisQueue,
      owner: Uuid,
      database: Uuid,
      row: Uuid,
      field: Uuid,
    ) -> (DatabaseRowReminder, Job) {
      let reminder = service
        .reminders
        .set_database_row_reminder(owner, database, row, field, 10)
        .await
        .unwrap();
      sqlx::query("UPDATE database_row_reminders SET trigger_at='2000-01-01T00:00:00Z' WHERE id=$1")
        .bind(reminder.id)
        .execute(pool)
        .await
        .unwrap();
      assert_eq!(
        service
          .reminders
          .fire_due_database_row_reminders(1)
          .await
          .unwrap()
          .enqueued_count,
        1
      );
      let job = queue.dequeue("notification", 1).await.unwrap().unwrap();
      assert_eq!(job.data["dispatch"]["reminderId"], json!(reminder.id));
      (reminder, job)
    }
    for (mode, closed) in [
      ("single", complete.clone()),
      ("bulk", complete.clone()),
      ("patch", complete.clone()),
      ("trash", open.clone()),
    ] {
      let (reminder, job) = queue_task_reminder(&service, &pool, &queue, owner_id, task_database, task, custom).await;
      let pending = service
        .reminders
        .set_database_row_reminder(owner_id, task_database, task, custom, 20)
        .await
        .unwrap();
      let before: Value =
        sqlx::query_scalar("SELECT to_jsonb(reminder) FROM database_row_reminders reminder WHERE id=$1")
          .bind(reminder.id)
          .fetch_one(&pool)
          .await
          .unwrap();
      let cells_before: Value = sqlx::query_scalar(
        "SELECT jsonb_agg(to_jsonb(cell) ORDER BY field_id) FROM workspace_database_cell_values cell WHERE row_id=$1",
      )
      .bind(task)
      .fetch_one(&pool)
      .await
      .unwrap();
      // Late workspace admission fails after native cancellation. Both the
      // canonical status/revisions and the queued reminder must roll back.
      assert!(
        repo
          .update_cell_value(
            task,
            status,
            DatabaseCellValueData::Status(complete.clone()),
            owner_id,
            DatabaseEditPrecondition::default().in_workspace(Uuid::new_v4()),
            None
          )
          .await
          .is_err()
      );
      assert_eq!(
        sqlx::query_scalar::<_, Value>("SELECT to_jsonb(reminder) FROM database_row_reminders reminder WHERE id=$1")
          .bind(reminder.id)
          .fetch_one(&pool)
          .await
          .unwrap(),
        before
      );
      assert_eq!(
        sqlx::query_scalar::<_, Value>(
          "SELECT jsonb_agg(to_jsonb(cell) ORDER BY field_id) FROM workspace_database_cell_values cell WHERE row_id=$1"
        )
        .bind(task)
        .fetch_one(&pool)
        .await
        .unwrap(),
        cells_before
      );
      assert_eq!(
        sqlx::query_scalar::<_, String>("SELECT status FROM database_row_reminders WHERE id=$1")
          .bind(pending.id)
          .fetch_one(&pool)
          .await
          .unwrap(),
        "scheduled",
        "late rollback retains pending schedule too"
      );
      match mode {
        "single" => {
          repo
            .update_cell_value(
              task,
              status,
              DatabaseCellValueData::Status(closed),
              owner_id,
              Default::default(),
              None,
            )
            .await
            .unwrap();
        }
        "bulk" => {
          let outcomes = repo
            .bulk_set_cell_value(
              &[task],
              status,
              DatabaseCellValueData::Status(closed),
              owner_id,
              &HashMap::new(),
              true,
              vec![],
              Default::default(),
            )
            .await
            .unwrap();
          assert!(outcomes.into_iter().all(|outcome| outcome.is_ok()));
        }
        "patch" => {
          let outcomes = repo
            .bulk_apply_cell_patches(
              task_database,
              &[(task, status, Some(DatabaseCellValueData::Status(closed)))],
              owner_id,
              &HashMap::new(),
              true,
              vec![],
              Default::default(),
            )
            .await
            .unwrap();
          assert!(outcomes.into_iter().all(|outcome| outcome.is_ok()));
        }
        "trash" => {
          repo
            .bulk_delete_rows(&[task], owner_id, &HashMap::new(), true, Default::default())
            .await
            .unwrap()
            .into_iter()
            .for_each(|outcome| {
              outcome.unwrap();
            });
        }
        _ => unreachable!(),
      }
      assert_eq!(
        sqlx::query_scalar::<_, String>("SELECT status FROM database_row_reminders WHERE id=$1")
          .bind(pending.id)
          .fetch_one(&pool)
          .await
          .unwrap(),
        "cancelled",
        "Closed/Trash cancels pending and queued together"
      );
      let cancelled: (String, i64) =
        sqlx::query_as("SELECT status,schedule_revision FROM database_row_reminders WHERE id=$1")
          .bind(reminder.id)
          .fetch_one(&pool)
          .await
          .unwrap();
      assert_eq!(cancelled.0, "cancelled");
      assert!(cancelled.1 > reminder.schedule_revision);
      assert!(
        myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
          &notification_service,
          None,
          Some(service.reminders.as_ref()),
          &job.data
        )
        .await
        .unwrap()
        .is_none()
      );
      assert!(
        service
          .reminders
          .set_database_row_reminder(owner_id, task_database, task, custom, 20)
          .await
          .is_err(),
        "Closed/Trash cannot schedule"
      );
      if mode == "trash" {
        repo
          .bulk_restore_rows(&[task], owner_id, &HashMap::new(), true, Default::default())
          .await
          .unwrap()
          .into_iter()
          .for_each(|outcome| {
            outcome.unwrap();
          });
      }
      repo
        .update_cell_value(
          task,
          status,
          DatabaseCellValueData::Status(open.clone()),
          owner_id,
          Default::default(),
          None,
        )
        .await
        .unwrap();
      assert!(
        myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
          &notification_service,
          None,
          Some(service.reminders.as_ref()),
          &job.data
        )
        .await
        .unwrap()
        .is_none(),
        "reopen cannot resurrect a cancelled queued generation"
      );
      assert!(
        repo
          .list_database_row_reminders(task_database, task, custom, owner_id)
          .await
          .unwrap()
          .is_empty()
      );
    }
    // Root restore cannot revive a queued generation cancelled by Trash.
    {
      let lifecycle = "database-trash";
      let (reminder, job) = queue_task_reminder(&service, &pool, &queue, owner_id, task_database, task, custom).await;
      {
        repo
          .trash_database(task_database, owner_id, Default::default())
          .await
          .unwrap();
        repo
          .restore_database(task_database, owner_id, Default::default())
          .await
          .unwrap();
      }
      let cancelled: (String, i64) =
        sqlx::query_as("SELECT status,schedule_revision FROM database_row_reminders WHERE id=$1")
          .bind(reminder.id)
          .fetch_one(&pool)
          .await
          .unwrap();
      assert_eq!(cancelled.0, "cancelled", "{lifecycle}");
      assert!(cancelled.1 > reminder.schedule_revision, "{lifecycle}");
      assert!(
        myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
          &notification_service,
          None,
          Some(service.reminders.as_ref()),
          &job.data,
        )
        .await
        .unwrap()
        .is_none(),
        "{lifecycle}: restoring capability must not revive queued work"
      );
      let explicit = service
        .reminders
        .set_database_row_reminder(owner_id, task_database, task, custom, 10)
        .await
        .unwrap();
      assert_ne!(
        explicit.id, reminder.id,
        "explicit scheduling after recovery owns new work"
      );
      service
        .reminders
        .delete_database_row_reminder(owner_id, task_database, explicit.id)
        .await
        .unwrap();
    }

    let (old, old_job) = queue_task_reminder(&service, &pool, &queue, owner_id, task_database, task, custom).await;
    let next_date = DatabaseDateTimeValue {
      start: all_day.start + chrono::Duration::days(1),
      ..all_day.clone()
    };
    service
      .editing
      .update_cell_value(
        owner_id,
        task_database,
        task,
        custom,
        DatabaseCellValueData::DateTime(next_date.clone()),
      )
      .await
      .unwrap();
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
        None,
        Some(service.reminders.as_ref()),
        &old_job.data
      )
      .await
      .unwrap()
      .is_none()
    );
    let fresh = service
      .reminders
      .set_database_row_reminder(owner_id, task_database, task, custom, 10)
      .await
      .unwrap();
    assert_ne!(
      fresh.id, old.id,
      "explicit new schedule owns a fresh generation after fired cancellation"
    );
    let mut stale = fresh.clone();
    stale.offset_minutes = 25;
    stale.trigger_at = myoxus_domain::database::database_row_reminder_trigger_at(&all_day, 25).unwrap();
    assert!(
      matches!(
        repo.upsert_database_row_reminder(stale).await,
        Err(myoxus_domain::repositories::RepositoryError::Conflict(
          "database reminder schedule revision"
        ))
      ),
      "a stale DateTime pre-read cannot schedule against the newer canonical date"
    );
    service
      .reminders
      .delete_database_row_reminder(owner_id, task_database, fresh.id)
      .await
      .unwrap();
    // The app's pre-read may race a status commit. Hold the actual source Row,
    // observe the native setter waiting on it, then publish Closed. No sleep,
    // retry or extra pool lease can substitute for the observed lock edge.
    let candidate = service
      .reminders
      .set_database_row_reminder(owner_id, task_database, task, custom, 25)
      .await
      .unwrap();
    service
      .reminders
      .delete_database_row_reminder(owner_id, task_database, candidate.id)
      .await
      .unwrap();
    let mut candidate = DatabaseRowReminder {
      id: Uuid::new_v4(),
      ..candidate
    };
    candidate.trigger_at = myoxus_domain::database::database_row_reminder_trigger_at(&next_date, 25).unwrap();
    let mut barrier = pool.begin().await.unwrap();
    pin_catalog_content_fixture(&mut barrier).await.unwrap();
    let barrier_pid: i32 = sqlx::query_scalar("SELECT pg_backend_pid()")
      .fetch_one(&mut *barrier)
      .await
      .unwrap();
    sqlx::query("SELECT id FROM workspace_database_rows WHERE id=$1 FOR UPDATE")
      .bind(task)
      .fetch_one(&mut *barrier)
      .await
      .unwrap();
    sqlx::query("UPDATE workspace_database_cell_values SET value_json=$2 WHERE row_id=$1 AND field_id=$3")
      .bind(task)
      .bind(json!(complete))
      .bind(status)
      .execute(&mut *barrier)
      .await
      .unwrap();
    use sqlx::Connection;
    let mut observer = sqlx::PgConnection::connect_with(pool.connect_options().as_ref())
      .await
      .unwrap();
    let setter = repo.upsert_database_row_reminder(candidate);
    tokio::pin!(setter);
    tokio::time::timeout(std::time::Duration::from_secs(5),async {
        loop {
          tokio::select! {
            result=&mut setter => panic!("native setter bypassed held Row admission: {result:?}"),
            observed=sqlx::query_scalar::<_,bool>("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE wait_event_type='Lock' AND $1=ANY(pg_blocking_pids(pid)) AND query LIKE '%workspace_database_rows%FOR UPDATE%')").bind(barrier_pid).fetch_one(&mut observer) => {
              if observed.unwrap() { break; }
            }
          }
          tokio::task::yield_now().await;
        }
      }).await.expect("native reminder setter reaches held source Row");
    barrier.commit().await.unwrap();
    assert!(
      matches!(setter.await,Err(myoxus_domain::repositories::RepositoryError::Validation(ref message)) if message=="database reminder Task is not open")
    );
    observer.close().await.unwrap();
    repo
      .update_cell_value(
        task,
        status,
        DatabaseCellValueData::Status(open.clone()),
        owner_id,
        Default::default(),
        None,
      )
      .await
      .unwrap();

    // Simulate a queued generation created before the completion guard existed:
    // no mutation-side cancellation can substitute for dispatch authorization.
    let (_, legacy_closed_job) =
      queue_task_reminder(&service, &pool, &queue, owner_id, task_database, task, custom).await;
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE workspace_database_cell_values SET value_json=$2 WHERE row_id=$1 AND field_id=$3")
      .bind(task)
      .bind(json!(complete))
      .bind(status)
      )
      .await
      .unwrap();
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
        None,
        Some(service.reminders.as_ref()),
        &legacy_closed_job.data
      )
      .await
      .unwrap()
      .is_none(),
      "legacy Closed generation must fail the current status check"
    );
    repo
      .update_cell_value(
        task,
        status,
        DatabaseCellValueData::Status(open.clone()),
        owner_id,
        Default::default(),
        None,
      )
      .await
      .unwrap();

    let (_, disabled_job) = queue_task_reminder(&service, &pool, &queue, owner_id, task_database, task, custom).await;
    let owner_inbox_before = notification_service.unread_count(owner_id).await.unwrap();
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE users SET status='disabled' WHERE id=$1")
      .bind(owner_id)
      )
      .await
      .unwrap();
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
        None,
        Some(service.reminders.as_ref()),
        &disabled_job.data
      )
      .await
      .unwrap()
      .is_none()
    );
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("UPDATE users SET status='active' WHERE id=$1")
      .bind(owner_id)
      )
      .await
      .unwrap();
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
        None,
        Some(service.reminders.as_ref()),
        &disabled_job.data
      )
      .await
      .unwrap()
      .is_none(),
      "active account restore cannot revive dropped generation"
    );
    assert_eq!(
      notification_service.unread_count(owner_id).await.unwrap(),
      owner_inbox_before
    );
    helpers::add_workspace_member(&pool, workspace_id, member_id).await;
    let (_, revoked_job) = queue_task_reminder(&service, &pool, &queue, member_id, task_database, task, custom).await;
    execute_catalog_pinned_content_fixture(&pool, sqlx::query("DELETE FROM workspace_memberships WHERE workspace_id=$1 AND user_id=$2")
      .bind(workspace_id)
      .bind(member_id)
      )
      .await
      .unwrap();
    assert!(
      myoxus_api::database_reminder_notification::dispatch_database_row_reminder_notification(
        &notification_service,
        None,
        Some(service.reminders.as_ref()),
        &revoked_job.data
      )
      .await
      .unwrap()
      .is_none()
    );
    assert_eq!(notification_service.unread_count(member_id).await.unwrap(), 0);

    assert!(execute_catalog_pinned_content_fixture(&pool,sqlx::query("DELETE FROM database_field_roles WHERE database_id=$1 AND role_key='task.status'").bind(task_database)).await.is_err());
    assert!(execute_catalog_pinned_content_fixture(&pool,sqlx::query("UPDATE workspace_database_fields SET config_json='{}'::jsonb WHERE id=$1").bind(custom)).await.is_err());
    let current=service.reminders.set_database_row_reminder(owner_id,task_database,task,custom,30).await.expect("protected Start role remains usable");
    service.reminders.delete_database_row_reminder(owner_id,task_database,current.id).await.unwrap();
    })
    .catch_unwind()
    .await;

    let redis_client = redis::Client::open(redis_url).expect("reminder Redis cleanup client");
    let mut redis = redis_client
      .get_multiplexed_async_connection()
      .await
      .expect("reminder Redis cleanup connection");
    let keys: Vec<String> = redis.keys(format!("{prefix}:*")).await.expect("reminder Redis keys");
    if !keys.is_empty() {
      let _: usize = redis.del(keys).await.expect("delete reminder Redis keys");
    }

    helpers::cleanup_users(&pool, &[owner_id, member_id]).await;
    if let Err(panic) = body {
      resume_unwind(panic);
    }
  });
}

#[test]
fn database_schedule_window_pushes_inclusive_overlap_and_pagination_to_postgres() {
  helpers::block_on_large_stack("database-schedule-window", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-schedule-window-owner").await;
    let body = AssertUnwindSafe(async {
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseInput!) { createDatabase(input: $input) { database { id } fields { id fieldType } } }",
        "variables": { "input": {
          "workspaceId": workspace_id.to_string(),
          "title": "Schedule overlap",
          "initialViewKind": "Table"
        }}
      }),
    )
    .await;
    let database_id = Uuid::parse_str(
      gql_data(&created, &["createDatabase"])["database"]["id"]
        .as_str()
        .expect("database id"),
    )
    .expect("database UUID");
    let title_field_id = gql_data(&created, &["createDatabase", "fields"])
      .as_array()
      .expect("initial fields")
      .iter()
      .find(|field| field["fieldType"] == "Title")
      .and_then(|field| field["id"].as_str())
      .expect("Title field id")
      .to_string();
    let field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseFieldInput!) { createDatabaseField(input: $input) { id } }",
        "variables": { "input": {
          "databaseId": database_id.to_string(),
          "name": "Window",
          "fieldType": "DateTime",
          "config": { "dateTime": { "defaultTimeZone": "UTC", "allowReminders": false } }
        }}
      }),
    )
    .await;
    let field_id = Uuid::parse_str(
      gql_data(&field, &["createDatabaseField"])["id"]
        .as_str()
        .expect("field id"),
    )
    .expect("field UUID");
    let composed_query_view = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseViewInput!) { createDatabaseView(input: $input) { id } }",
        "variables": { "input": {
          "databaseId": database_id.to_string(),
          "name": "Boundary schedule query",
          "viewKind": "Table",
          "config": { "table": {
            "titleFieldId": title_field_id,
            "visibleFieldIds": [title_field_id, field_id.to_string()],
            "searchFieldIds": [title_field_id],
            "sort": [{ "fieldId": title_field_id, "direction": "Desc" }],
            "filter": [{ "fieldId": title_field_id, "operator": "Contains", "value": { "text": "boundary" } }]
          }}
        }}
      }),
    )
    .await;
    let composed_query_view_id = gql_data(&composed_query_view, &["createDatabaseView"])["id"]
      .as_str()
      .expect("composed query view id");

    let notes_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: CreateDatabaseFieldInput!) { createDatabaseField(input: $input) { id } }",
        "variables": { "input": { "databaseId": database_id.to_string(), "name": "Search notes", "fieldType": "Text" } }
      }),
    )
    .await;
    let notes_field_id = gql_data(&notes_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("notes field id");
    let gantt_view = helpers::gql(&app, owner_session, json!({
      "query": "mutation($input: CreateDatabaseViewInput!) { createDatabaseView(input: $input) { id } }",
      "variables": { "input": { "databaseId": database_id.to_string(), "name": "Gantt search before paging", "viewKind": "Gantt", "config": { "gantt": {
        "titleFieldId": title_field_id, "startFieldId": field_id.to_string(), "visibleFieldIds": [title_field_id, notes_field_id],
        "sort": [{ "fieldId": title_field_id, "direction": "Desc" }],
        "group": { "fieldId": field_id.to_string(), "showEmptyGroups": true }
      }}}}
    })).await;
    let gantt_view_id = gql_data(&gantt_view, &["createDatabaseView"])["id"]
      .as_str()
      .expect("Gantt view id");

    let fixtures = [
      (
        "left-boundary",
        "2026-07-09T20:00:00Z",
        Some("2026-07-10T00:00:00Z"),
        false,
      ),
      (
        "right-boundary",
        "2026-07-10T23:59:59Z",
        Some("2026-07-11T08:00:00Z"),
        false,
      ),
      (
        "encompassing",
        "2026-07-01T00:00:00Z",
        Some("2026-07-20T00:00:00Z"),
        false,
      ),
      ("point", "2026-07-10T12:00:00Z", None, false),
      ("all-day", "2026-07-10T00:00:00Z", None, true),
      ("outside", "2026-07-11T12:00:00Z", None, false),
      ("timezone-normalized", "2026-07-09T22:00:00Z", None, false),
    ];
    for (position, (title, start, end, all_day)) in fixtures.into_iter().enumerate() {
      let row_id = Uuid::new_v4();
      sqlx::query(
        "INSERT INTO workspace_database_rows (id, database_id, title, position, created_by, updated_by) VALUES ($1, $2, $3, $4, $5, $5)",
      )
      .bind(row_id)
      .bind(database_id)
      .bind(title)
      .bind(position as i32)
      .bind(owner_id)
      .execute(&pool)
      .await
      .expect("schedule Row fixture");
      sqlx::query(
        "INSERT INTO workspace_database_cell_values (row_id, field_id, database_id, value_json, updated_by) VALUES ($1, $2, $3, $4, $5)",
      )
      .bind(row_id)
      .bind(field_id)
      .bind(database_id)
      .bind(json!({
        "start": start,
        "end": end,
        "allDay": all_day,
        "timeZone": if title == "timezone-normalized" { "Europe/Berlin" } else { "UTC" }
      }))
      .bind(owner_id)
      .execute(&pool)
      .await
      .expect("schedule Cell fixture");
      if title == "point" || title == "outside" {
        let note = helpers::gql(&app, owner_session, json!({
          "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { fieldId } }",
          "variables": { "input": { "databaseId": database_id.to_string(), "rowId": row_id.to_string(), "fieldId": notes_field_id, "value": { "text": "boundary" } } }
        })).await;
        gql_data(&note, &["updateDatabaseCellValue"]);
      }
    }

    let query_window = |first: i64, offset: Option<i64>, after: Option<&str>, start: &str, end: &str| {
      helpers::gql(
        &app,
        owner_session,
        json!({
          "query": "query($workspaceId: String!, $databaseId: ID!, $first: Int, $offset: Int, $after: String, $scheduleWindow: DatabaseScheduleWindowInput) { workspace(id: $workspaceId) { databaseRows(databaseId: $databaseId, first: $first, offset: $offset, after: $after, scheduleWindow: $scheduleWindow) { totalCount endCursor rows { row { title } } } } }",
          "variables": {
            "workspaceId": workspace_id.to_string(),
            "databaseId": database_id.to_string(),
            "first": first,
            "offset": offset,
            "after": after,
            "scheduleWindow": { "fieldId": field_id.to_string(), "start": start, "end": end }
          }
        }),
      )
    };
    let first_page = query_window(2, None, None, "2026-07-10T00:00:00Z", "2026-07-10T23:59:59Z").await;
    let first_page = gql_data(&first_page, &["workspace", "databaseRows"]);
    assert_eq!(first_page["totalCount"], 5);
    assert_eq!(first_page["rows"].as_array().expect("first schedule page").len(), 2);
    let first_cursor = first_page["endCursor"]
      .as_str()
      .expect("schedule page returns a stable cursor");
    let first_titles = first_page["rows"]
      .as_array()
      .expect("first schedule rows")
      .iter()
      .map(|row| row["row"]["title"].as_str().expect("first schedule title"))
      .collect::<BTreeSet<_>>();
    let second_page = query_window(
      10,
      None,
      Some(first_cursor),
      "2026-07-10T00:00:00Z",
      "2026-07-10T23:59:59Z",
    )
    .await;
    let second_rows = gql_data(&second_page, &["workspace", "databaseRows"])["rows"]
      .as_array()
      .expect("second schedule page");
    assert_eq!(second_rows.len(), 3);
    assert!(
      second_rows
        .iter()
        .all(|row| { !first_titles.contains(row["row"]["title"].as_str().expect("second schedule title"),) })
    );

    let normalized = query_window(20, Some(0), None, "2026-07-09T22:00:00Z", "2026-07-09T22:00:00Z").await;
    let normalized_titles = gql_data(&normalized, &["workspace", "databaseRows", "rows"])
      .as_array()
      .expect("normalized rows")
      .iter()
      .map(|row| row["row"]["title"].as_str().expect("normalized title"))
      .collect::<Vec<_>>();
    assert!(normalized_titles.contains(&"timezone-normalized"));
    assert!(!normalized_titles.contains(&"outside"));

    let composed = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!, $viewId: ID!, $scheduleWindow: DatabaseScheduleWindowInput!, $search: String!) { workspace(id: $workspaceId) { databaseRows(databaseId: $databaseId, viewId: $viewId, scheduleWindow: $scheduleWindow, search: $search) { totalCount rows { row { title } } } } }",
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id.to_string(),
          "viewId": composed_query_view_id,
          "scheduleWindow": {
            "fieldId": field_id.to_string(),
            "start": "2026-07-10T00:00:00Z",
            "end": "2026-07-10T23:59:59Z"
          },
          "search": "boundary"
        }
      }),
    )
    .await;
    let composed = gql_data(&composed, &["workspace", "databaseRows"]);
    assert_eq!(composed["totalCount"], 2);
    assert_eq!(composed["rows"][0]["row"]["title"], "right-boundary");
    assert_eq!(composed["rows"][1]["row"]["title"], "left-boundary");

    let gantt_page = |first: i64, after: Option<&str>| {
      helpers::gql(
        &app,
        owner_session,
        json!({
          "query": "query($workspaceId: String!, $databaseId: ID!, $viewId: ID!, $first: Int, $after: String, $scheduleWindow: DatabaseScheduleWindowInput!, $search: String!) { workspace(id: $workspaceId) { databaseRows(databaseId: $databaseId, viewId: $viewId, first: $first, after: $after, scheduleWindow: $scheduleWindow, search: $search) { totalCount endCursor rows { row { title } groupKeys } } databaseRowGroups(databaseId: $databaseId, viewId: $viewId, scheduleWindow: $scheduleWindow, search: $search) { key rowCount } } }",
          "variables": { "workspaceId": workspace_id.to_string(), "databaseId": database_id.to_string(), "viewId": gantt_view_id, "first": first, "after": after,
            "scheduleWindow": { "fieldId": field_id.to_string(), "start": "2026-07-10T00:00:00Z", "end": "2026-07-10T23:59:59Z" }, "search": "boundary" }
        }),
      )
    };
    let gantt_first = gantt_page(1, None).await;
    let first = gql_data(&gantt_first, &["workspace", "databaseRows"]);
    assert_eq!(
      first["totalCount"], 3,
      "Title OR visible searchable metadata must filter before paging and exclude out-of-window matches"
    );
    assert_eq!(first["rows"][0]["row"]["title"], "right-boundary");
    let gantt_rest = gantt_page(10, Some(first["endCursor"].as_str().expect("filtered cursor"))).await;
    let rest = gql_data(&gantt_rest, &["workspace", "databaseRows"]);
    assert_eq!(rest["rows"].as_array().map(Vec::len), Some(2));
    assert_eq!(rest["rows"][0]["row"]["title"], "point");
    assert_eq!(rest["rows"][1]["row"]["title"], "left-boundary");
    let groups = gql_data(&gantt_first, &["workspace", "databaseRowGroups"])
      .as_array()
      .expect("Gantt summaries");
    assert_eq!(
      groups
        .iter()
        .map(|group| group["rowCount"].as_i64().expect("group count"))
        .sum::<i64>(),
      3
    );
    for row in first["rows"]
      .as_array()
      .expect("first filtered rows")
      .iter()
      .chain(rest["rows"].as_array().expect("remaining filtered rows"))
    {
      assert!(
        row["groupKeys"]
          .as_array()
          .expect("server membership")
          .iter()
          .all(|key| groups
            .iter()
            .any(|group| &group["key"] == key && group["rowCount"].as_i64().expect("matching count") > 0))
      );
    }
    }).catch_unwind().await;
    finish_database_fixture(&pool, &[owner_id], body).await;
  });
}

#[test]
fn database_files_field_roundtrips_graphql_blob_references() {
  helpers::block_on_large_stack("database-files-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-files-roundtrip-owner").await;
    let (reader_id, reader_session) = helpers::seed_user(&pool, &auth_store, "database-files-roundtrip-reader").await;
    let (outsider_id, outsider_session) =
      helpers::seed_user(&pool, &auth_store, "database-files-roundtrip-outsider").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    helpers::add_workspace_member(&pool, workspace_id, reader_id).await;
    let blob_key = format!("database-files/{}.png", Uuid::new_v4());
    helpers::upload_blob(&app, owner_session, workspace_id, &blob_key, "image/png", &[7_u8; 512]).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateFilesDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) { database { id } }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Files contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let files_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateFilesField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config {
              kind
              files { allowedMimeCategories maxItemCount maxItemSize previewPolicy }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Attachments",
            "fieldType": "Files",
            "config": {
              "files": {
                "allowedMimeCategories": ["Image"],
                "maxItemCount": 2,
                "maxItemSize": 1024,
                "previewPolicy": "Auto"
              }
            }
          }
        }
      }),
    )
    .await;
    let files_field = gql_data(&files_field, &["createDatabaseField"]);
    let files_field_id = files_field["id"].as_str().expect("Files field id");
    assert_eq!(files_field["fieldType"], "Files");
    assert_eq!(files_field["config"]["files"]["allowedMimeCategories"][0], "Image");
    assert_eq!(files_field["config"]["files"]["previewPolicy"], "Auto");

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateFilesRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id title }
            cells {
              fieldId
              fieldType
              value {
                kind
                files { files { blobKey name mime size caption cover } }
              }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Asset row",
            "cells": [
              {
                "fieldId": files_field_id,
                "value": {
                  "files": {
                    "files": [
                      {
                        "blobKey": blob_key,
                        "name": "cover.png",
                        "mime": "image/png",
                        "size": 512,
                        "caption": "Cover",
                        "cover": true
                      }
                    ]
                  }
                }
              }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    assert_eq!(row["cells"][0]["fieldType"], "Files");
    assert_eq!(row["cells"][0]["value"]["kind"], "Files");
    assert_eq!(row["cells"][0]["value"]["files"]["files"][0]["blobKey"], blob_key);
    assert_eq!(row["cells"][0]["value"]["files"]["files"][0]["mime"], "image/png");
    assert_eq!(row["cells"][0]["value"]["files"]["files"][0]["cover"], true);

    for (session, expected_success) in [(reader_session, true), (outsider_session, false)] {
      let response = app
        .clone()
        .oneshot(
          Request::builder()
            .method("GET")
            .uri(format!("/api/workspaces/{workspace_id}/blobs/{blob_key}"))
            .header("cookie", format!("affine_session={session}"))
            .body(Body::empty())
            .expect("blob read request"),
        )
        .await
        .expect("blob read response");
      assert_eq!(
        response.status().is_success(),
        expected_success,
        "workspace BlobService ACL must match Database visibility"
      );
    }
    let outsider_database = helpers::gql(
      &app,
      outsider_session,
      json!({
        "query": "query($workspaceId: String!, $databaseId: ID!) { workspace(id: $workspaceId) { database(databaseId: $databaseId) { database { id } } } }",
        "variables": { "workspaceId": workspace_id.to_string(), "databaseId": database_id }
      }),
    )
    .await;
    assert!(
      outsider_database.get("errors").is_some(),
      "non-member must not read the Database"
    );

    let invalid = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidFiles($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": files_field_id,
            "value": {
              "files": {
                "files": [
                  {
                    "blobKey": blob_key,
                    "name": "cover.png",
                    "mime": "application/pdf",
                    "size": 512,
                    "caption": "Cover",
                    "cover": true
                  }
                ]
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("Files validation error code"),
      "MIX_DATABASE_FILES_INVALID"
    );

    let foreign_workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let foreign_blob_key = format!("database-files/{}.png", Uuid::new_v4());
    helpers::upload_blob(
      &app,
      owner_session,
      foreign_workspace_id,
      &foreign_blob_key,
      "image/png",
      &[9_u8; 64],
    )
    .await;
    let cross_workspace = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { fieldId } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": files_field_id,
          "value": { "files": { "files": [{
            "blobKey": foreign_blob_key,
            "name": "foreign.png",
            "mime": "image/png",
            "size": 64,
            "cover": false
          }] } }
        } }
      }),
    )
    .await;
    assert_eq!(
      cross_workspace["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_FILES_INVALID"
    );

    let deleted = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($workspaceId: String!, $key: String!) { deleteBlob(workspaceId: $workspaceId, key: $key) }",
        "variables": { "workspaceId": workspace_id.to_string(), "key": blob_key }
      }),
    )
    .await;
    assert_eq!(deleted["data"]["deleteBlob"], true);
    let deleted_reference = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": "mutation($input: UpdateDatabaseCellValueInput!) { updateDatabaseCellValue(input: $input) { fieldId } }",
        "variables": { "input": {
          "databaseId": database_id,
          "rowId": row_id,
          "fieldId": files_field_id,
          "value": { "files": { "files": [{
            "blobKey": blob_key,
            "name": "cover.png",
            "mime": "image/png",
            "size": 512,
            "cover": true
          }] } }
        } }
      }),
    )
    .await;
    assert_eq!(
      deleted_reference["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_FILES_INVALID"
    );

    helpers::cleanup_users(&pool, &[owner_id, reader_id, outsider_id]).await;
  });
}

#[test]
fn database_unique_id_field_generates_readonly_transaction_safe_sequences() {
  helpers::block_on_large_stack("database-unique-id-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-unique-id-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateUniqueIdDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) { database { id } }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Unique ID contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let unique_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateUniqueIdField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) {
            id
            fieldType
            config { kind uniqueId { prefix startNumber padding } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Public ID",
            "fieldType": "UniqueId",
            "config": {
              "uniqueId": {
                "prefix": "TASK-",
                "startNumber": 7,
                "padding": 3
              }
            }
          }
        }
      }),
    )
    .await;
    let unique_field = gql_data(&unique_field, &["createDatabaseField"]);
    let unique_field_id = unique_field["id"].as_str().expect("UniqueId field id");
    assert_eq!(unique_field["fieldType"], "UniqueId");
    assert_eq!(unique_field["config"]["uniqueId"]["prefix"], "TASK-");
    assert_eq!(unique_field["config"]["uniqueId"]["startNumber"], 7);
    assert_eq!(unique_field["config"]["uniqueId"]["padding"], 3);

    let invalid_manual_cell = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation InvalidManualUniqueIdCell($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) { row { id editRevision } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Manual value",
            "cells": [
              {
                "fieldId": unique_field_id,
                "value": { "text": "TASK-999" }
              }
            ]
          }
        }
      }),
    )
    .await;
    assert_eq!(
      invalid_manual_cell["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("UniqueId manual write error code"),
      "MIX_DATABASE_CELL_VALUE_INVALID"
    );

    let create_futures = (0..10).map(|index| {
      let app = app.clone();
      let database_id = database_id.to_string();
      async move {
        helpers::gql(
          &app,
          owner_session,
          json!({
            "query": r#"
            mutation CreateGeneratedUniqueIdRow($input: CreateDatabaseRowInput!) {
              createDatabaseRow(input: $input) {
                row { id title }
                cells {
                  fieldId
                  fieldType
                  value { kind uniqueId { prefix sequence display } }
                }
              }
            }
          "#,
            "variables": {
              "input": {
                "databaseId": database_id,
                "title": format!("Generated row {index}")
              }
            }
          }),
        )
        .await
      }
    });
    let created_rows = join_all(create_futures).await;
    let mut sequences = Vec::new();
    let mut displays = BTreeSet::new();
    for response in &created_rows {
      let row = gql_data(response, &["createDatabaseRow"]);
      let generated_cell = row["cells"]
        .as_array()
        .expect("row cells")
        .iter()
        .find(|cell| cell["fieldId"] == unique_field_id)
        .expect("generated UniqueId cell");
      assert_eq!(generated_cell["fieldType"], "UniqueId");
      assert_eq!(generated_cell["value"]["kind"], "UniqueId");
      assert_eq!(generated_cell["value"]["uniqueId"]["prefix"], "TASK-");
      sequences.push(
        generated_cell["value"]["uniqueId"]["sequence"]
          .as_i64()
          .expect("generated sequence"),
      );
      displays.insert(
        generated_cell["value"]["uniqueId"]["display"]
          .as_str()
          .expect("generated display")
          .to_string(),
      );
    }
    sequences.sort_unstable();
    assert_eq!(sequences, (7..17).collect::<Vec<_>>());
    assert_eq!(
      displays.len(),
      10,
      "concurrent row creation must not duplicate generated UniqueId displays"
    );
    assert_eq!(
      displays,
      (7..17)
        .map(|sequence| format!("TASK-{sequence:03}"))
        .collect::<BTreeSet<_>>()
    );

    async fn filtered_unique_id_sequences(
      app: &axum::Router,
      session: Uuid,
      workspace_id: Uuid,
      database_id: &str,
      field_id: &str,
      filter_value: serde_json::Value,
      operator: &str,
    ) -> Vec<i64> {
      let response = helpers::gql(
        app,
        session,
        json!({
          "query": r#"
            query FilterUniqueIdRows(
              $workspaceId: ID!
              $databaseId: ID!
              $filter: [DatabaseFilterRuleInput!]!
            ) {
              workspace(id: $workspaceId) {
                databaseRows(databaseId: $databaseId, filter: $filter, first: 100) {
                  rows {
                    cells { fieldId value { uniqueId { sequence } } }
                  }
                }
              }
            }
          "#,
          "variables": {
            "workspaceId": workspace_id.to_string(),
            "databaseId": database_id,
            "filter": [{
              "fieldId": field_id,
              "operator": operator,
              "value": filter_value,
            }],
          }
        }),
      )
      .await;
      assert!(response.get("errors").is_none(), "UniqueId filter failed: {response:#}");
      let mut sequences = gql_data(&response, &["workspace", "databaseRows", "rows"])
        .as_array()
        .expect("filtered rows")
        .iter()
        .map(|row| {
          row["cells"]
            .as_array()
            .expect("filtered row cells")
            .iter()
            .find(|cell| cell["fieldId"] == field_id)
            .and_then(|cell| cell["value"]["uniqueId"]["sequence"].as_i64())
            .expect("filtered UniqueId sequence")
        })
        .collect::<Vec<_>>();
      sequences.sort_unstable();
      sequences
    }

    assert_eq!(
      filtered_unique_id_sequences(
        &app,
        owner_session,
        workspace_id,
        database_id,
        unique_field_id,
        json!({ "number": 11 }),
        "Equals",
      )
      .await,
      vec![11],
      "Equals must compare the generated numeric sequence, not the display value"
    );
    assert_eq!(
      filtered_unique_id_sequences(
        &app,
        owner_session,
        workspace_id,
        database_id,
        unique_field_id,
        json!({ "numberRange": { "start": 9, "end": 12 } }),
        "Between",
      )
      .await,
      vec![9, 10, 11, 12],
      "Between must use the repository UniqueId scalar projection"
    );

    for invalid_value in [
      json!({ "text": "TASK-011" }),
      json!({ "text": created_rows[0]["data"]["createDatabaseRow"]["row"]["id"] }),
    ] {
      let response = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": r#"
            query RejectTextUniqueIdFilter(
              $workspaceId: ID!
              $databaseId: ID!
              $filter: [DatabaseFilterRuleInput!]!
            ) {
              workspace(id: $workspaceId) {
                databaseRows(databaseId: $databaseId, filter: $filter, first: 100) {
                  totalCount
                }
              }
            }
          "#,
          "variables": {
            "workspaceId": workspace_id.to_string(),
            "databaseId": database_id,
            "filter": [{
              "fieldId": unique_field_id,
              "operator": "Equals",
              "value": invalid_value,
            }],
          }
        }),
      )
      .await;
      assert_eq!(
        response["errors"][0]["extensions"]["code"], "MIX_DATABASE_VIEW_CONFIG_INVALID",
        "UniqueId filters must reject display prefixes and internal row UUIDs: {response:#}"
      );
    }

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_unique_id_csv_mapping_rejects_imported_display_ids() {
  helpers::block_on_large_stack("database-unique-id-csv-reject", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-unique-id-csv-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let csv_content = b"Task,Public ID\nAlpha,TASK-001\n";
    let input = json!({
      "workspaceId": workspace_id.to_string(),
      "databaseTitle": "Unique ID import conflict",
      "firstRowIsHeader": true,
      "mapping": [
        { "sourceIndex": 0, "importColumn": true, "fieldName": "Task", "fieldType": "Title", "isTitle": true },
        { "sourceIndex": 1, "importColumn": true, "fieldName": "Public ID", "fieldType": "UniqueId", "isTitle": false }
      ]
    });

    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewUniqueIdCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            appliedMapping { fieldName fieldType importColumn }
            errors { code source field message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": input.clone()
        }
      }),
      "unique-id.csv",
      csv_content,
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["appliedMapping"][1]["fieldType"], "UniqueId");
    let errors = preview["errors"].as_array().expect("preview errors");
    assert!(
      errors.iter().any(|error| {
        error["code"] == "MIX_DATABASE_CSV_INVALID"
          && error["field"] == "Public ID"
          && error["message"]
            .as_str()
            .is_some_and(|message| message.contains("cannot be imported"))
      }),
      "UniqueId mapping must be rejected until an explicit preserve/remap/reject import policy exists: {errors:#?}"
    );

    let import = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportUniqueIdCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) { createdRowCount }
        }
      "#,
        "variables": {
          "file": null,
          "input": input
        }
      }),
      "unique-id.csv",
      csv_content,
    )
    .await;
    assert_eq!(
      import["errors"][0]["extensions"]["code"]
        .as_str()
        .expect("UniqueId import conflict error code"),
      "MIX_DATABASE_CSV_INVALID"
    );

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_users_field_type_roundtrips_csv_email_resolution_and_json() {
  helpers::block_on_large_stack("database-users-roundtrip", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "database-users-roundtrip-owner").await;
    let (member_id, _) = helpers::seed_user(&pool, &auth_store, "database-users-roundtrip-member").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    sqlx::query(
      "INSERT INTO workspace_memberships (workspace_id, user_id, role, status, joined_at)
       VALUES ($1, $2, 'Collaborator', 'Accepted', now())",
    )
    .bind(workspace_id)
    .bind(member_id)
    .execute(&pool)
    .await
    .expect("insert accepted workspace member");
    let member_email: String = sqlx::query_scalar("SELECT email FROM users WHERE id = $1")
      .bind(member_id)
      .fetch_one(&pool)
      .await
      .expect("member email");
    let csv_content = format!("Task,Assignees\nAlpha,{member_email}; {}\n", owner_id);

    let preview = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation PreviewUsersCsv($file: Upload!, $input: PreviewDatabaseCsvImportInput!) {
          previewDatabaseCsvImport(file: $file, input: $input) {
            detectedColumns { fieldName fieldType }
            inferredFields { name fieldType config { kind users { minCount maxCount } } }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Users CSV"
          }
        }
      }),
      "users.csv",
      csv_content.as_bytes(),
    )
    .await;
    let preview = gql_data(&preview, &["previewDatabaseCsvImport"]);
    assert_eq!(preview["errors"].as_array().expect("preview errors").len(), 0);
    assert_eq!(preview["detectedColumns"][1]["fieldType"], "Users");
    assert_eq!(preview["inferredFields"][1]["config"]["kind"], "Users");

    let imported = gql_csv_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportUsersCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database {
              database { id title }
              fields { id name fieldType config { kind users { minCount maxCount } } }
              rowCount
            }
            errors { code message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": {
            "workspaceId": workspace_id.to_string(),
            "databaseTitle": "Users CSV"
          }
        }
      }),
      "users.csv",
      csv_content.as_bytes(),
    )
    .await;
    let imported = gql_data(&imported, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    let imported_database_id = imported["database"]["database"]["id"]
      .as_str()
      .expect("imported database id");
    let imported_users_field_id = imported["database"]["fields"]
      .as_array()
      .expect("imported fields")
      .iter()
      .find(|field| field["fieldType"] == "Users")
      .and_then(|field| field["id"].as_str())
      .expect("imported users field id");

    let imported_rows = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query ImportedUsersRows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows {
                row { title }
                cells { fieldId value { kind users user } }
              }
            }
            databaseCsvExport(databaseId: $databaseId) { content }
            databaseJsonExport(databaseId: $databaseId) { content contentType }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": imported_database_id
        }
      }),
    )
    .await;
    let workspace = gql_data(&imported_rows, &["workspace"]);
    let rows = workspace["databaseRows"]["rows"].as_array().expect("imported rows");
    let alpha = rows
      .iter()
      .find(|row| row["row"]["title"] == "Alpha")
      .expect("Alpha row");
    let alpha_users = alpha["cells"]
      .as_array()
      .expect("Alpha cells")
      .iter()
      .find(|cell| cell["fieldId"] == imported_users_field_id)
      .expect("Alpha users cell");
    assert_eq!(alpha_users["value"]["kind"], "Users");
    assert_eq!(
      alpha_users["value"]["users"]
        .as_array()
        .expect("users cell")
        .iter()
        .map(|value| value.as_str().expect("user id").to_string())
        .collect::<Vec<_>>(),
      vec![member_id.to_string(), owner_id.to_string()]
    );
    assert!(alpha_users["value"]["user"].is_null());

    let csv_export = workspace["databaseCsvExport"]["content"].as_str().expect("CSV export");
    assert!(
      csv_export.contains(&format!("{}; {}", member_id, owner_id)),
      "CSV export must use stable UUID references for Users values: {csv_export:?}"
    );

    let json_export = workspace["databaseJsonExport"]["content"]
      .as_str()
      .expect("JSON export");
    assert_eq!(workspace["databaseJsonExport"]["contentType"], "application/json");
    let snapshot: Value = serde_json::from_str(json_export).expect("users JSON snapshot");
    assert!(
      snapshot["database"]["fields"]
        .as_array()
        .expect("snapshot fields")
        .iter()
        .any(|field| field["fieldType"] == "users" && field["config"]["kind"] == "users"),
      "JSON snapshot must preserve Users field schema: {snapshot:#}"
    );
    assert!(
      snapshot["database"]["rows"]
        .as_array()
        .expect("snapshot rows")
        .iter()
        .flat_map(|row| row["cells"].as_array().into_iter().flatten())
        .any(|cell| {
          cell["fieldType"] == "users"
            && cell["value"]["kind"] == "domain"
            && cell["value"]["value"]["kind"] == "users"
            && cell["value"]["value"]["value"]
              .as_array()
              .is_some_and(|ids| ids.len() == 2 && ids[0] == member_id.to_string() && ids[1] == owner_id.to_string())
        }),
      "JSON snapshot must preserve ordered Users cell values: {snapshot:#}"
    );

    let imported_json = gql_json_upload(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation ImportUsersJson($file: Upload!, $input: ImportDatabaseJsonInput!) {
          importDatabaseJson(file: $file, input: $input) {
            database { fields { name fieldType config { kind users { minCount maxCount } } } rowCount }
            warnings { code path message }
          }
        }
      "#,
        "variables": {
          "file": null,
          "input": { "workspaceId": workspace_id.to_string() }
        }
      }),
      "users.database.json",
      json_export.as_bytes(),
    )
    .await;
    let imported_json = gql_data(&imported_json, &["importDatabaseJson"]);
    assert_eq!(
      imported_json["warnings"]
        .as_array()
        .expect("JSON import warnings")
        .len(),
      0
    );
    assert_eq!(imported_json["database"]["rowCount"], 1);
    assert!(
      imported_json["database"]["fields"]
        .as_array()
        .expect("JSON imported fields")
        .iter()
        .any(|field| field["name"] == "Assignees" && field["fieldType"] == "Users"),
      "JSON import must preserve Users field metadata: {imported_json:#}"
    );

    helpers::cleanup_users(&pool, &[owner_id, member_id]).await;
  });
}

#[test]
fn database_rows_are_decoupled_from_documents_and_use_document_link_cells() {
  helpers::block_on_large_stack("p38-row-document-decoupling", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-p38-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;
    let linked_doc_id = helpers::create_doc(&pool, workspace_id, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
            fields { id fieldType }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "P38 row document decoupling",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let created_record = gql_data(&created, &["createDatabase"]);
    let database_id = created_record["database"]["id"].as_str().expect("database id");
    let title_field_id = created_record["fields"][0]["id"].as_str().expect("title field id");

    let document_link_field = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateField($input: CreateDatabaseFieldInput!) {
          createDatabaseField(input: $input) { id fieldType config { kind } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "name": "Linked document",
            "fieldType": "DocumentLink",
            "required": false
          }
        }
      }),
    )
    .await;
    let document_link_field_id = gql_data(&document_link_field, &["createDatabaseField"])["id"]
      .as_str()
      .expect("document link field id");

    let first_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id contentDocument { documentId state title } title }
            cells { fieldId value { kind documentLink { docId target { documentId state title } } } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "First linked row",
            "cells": [{
              "fieldId": document_link_field_id,
              "value": { "documentLink": { "docId": linked_doc_id.to_string() } }
            }]
          }
        }
      }),
    )
    .await;
    let second_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id contentDocument { documentId state title } title }
            cells { fieldId value { kind documentLink { docId target { documentId state title } } } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Second linked row",
            "cells": [{
              "fieldId": document_link_field_id,
              "value": { "documentLink": { "docId": linked_doc_id.to_string() } }
            }]
          }
        }
      }),
    )
    .await;
    let first = gql_data(&first_row, &["createDatabaseRow"]);
    let second = gql_data(&second_row, &["createDatabaseRow"]);
    assert!(
      first["row"]["contentDocument"].is_null(),
      "new rows must not create optional content documents"
    );
    assert!(
      second["row"]["contentDocument"].is_null(),
      "same linked document can be used by multiple rows"
    );
    assert_eq!(
      first["cells"][0]["value"]["documentLink"]["docId"],
      linked_doc_id.to_string()
    );
    assert_eq!(
      second["cells"][0]["value"]["documentLink"]["docId"],
      linked_doc_id.to_string()
    );
    for row in [first, second] {
      let target = &row["cells"][0]["value"]["documentLink"]["target"];
      assert_eq!(target["documentId"], linked_doc_id.to_string());
      assert_eq!(target["state"], "Available");
      assert!(target["title"].as_str().is_some_and(|title| !title.is_empty()));
    }

    let first_row_id = first["row"]["id"].as_str().expect("first row id");
    let linked_doc_title_before: String = sqlx::query_scalar("SELECT title FROM docs WHERE id = $1")
      .bind(linked_doc_id)
      .fetch_one(&pool)
      .await
      .expect("linked doc title before row title update");

    let updated_title = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateTitle($input: UpdateDatabaseRowTitleInput!) {
          updateDatabaseRowTitle(input: $input) { value { kind text } }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": first_row_id,
            "titleFieldId": title_field_id,
            "title": "Renamed row title"
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&updated_title, &["updateDatabaseRowTitle"])["value"]["text"],
      "Renamed row title"
    );
    let linked_doc_title_after: String = sqlx::query_scalar("SELECT title FROM docs WHERE id = $1")
      .bind(linked_doc_id)
      .fetch_one(&pool)
      .await
      .expect("linked doc title after row title update");
    assert_eq!(
      linked_doc_title_after, linked_doc_title_before,
      "row-owned title update must not mutate linked document title"
    );

    sqlx::query("DELETE FROM docs WHERE id = $1")
      .bind(linked_doc_id)
      .execute(&pool)
      .await
      .expect("delete linked document");
    let missing_target = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query MissingDocumentLink($workspaceId: String!, $databaseId: ID!, $rowId: ID!) {
          workspace(id: $workspaceId) {
            databaseRow(databaseId: $databaseId, rowId: $rowId) {
              cells {
                fieldId
                value { documentLink { docId target { documentId state title } } }
              }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id,
          "rowId": first_row_id
        }
      }),
    )
    .await;
    let missing_document_link = gql_data(&missing_target, &["workspace", "databaseRow"])["cells"]
      .as_array()
      .expect("database row cells")
      .iter()
      .find(|cell| cell["fieldId"] == document_link_field_id)
      .expect("document link cell");
    let missing_projection = &missing_document_link["value"]["documentLink"]["target"];
    assert_eq!(missing_projection["documentId"], linked_doc_id.to_string());
    assert_eq!(missing_projection["state"], "Missing");
    assert!(
      missing_projection["title"].is_null(),
      "missing target title must not leak"
    );
    let row_count: i64 =
      sqlx::query_scalar("SELECT COUNT(*)::BIGINT FROM workspace_database_rows WHERE database_id = $1")
        .bind(Uuid::parse_str(database_id).expect("database id uuid"))
        .fetch_one(&pool)
        .await
        .expect("row count after linked document delete");
    assert_eq!(row_count, 2, "deleting a linked document must not delete database rows");

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_simple_property_pack_roundtrips_and_keeps_projections_readonly() {
  helpers::block_on_large_stack("p9i-simple-property-pack", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-p9i-owner").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
            fields { id fieldType }
            views { id viewKind config { table { titleFieldId visibleFieldIds } } }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "P9I Properties",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");
    let title_field_id = gql_data(&created, &["createDatabase"])["fields"][0]["id"]
      .as_str()
      .expect("title field id")
      .to_string();
    let table_view_id = gql_data(&created, &["createDatabase"])["views"][0]["id"]
      .as_str()
      .expect("table view id")
      .to_string();

    async fn create_field(
      app: &axum::Router,
      session_id: Uuid,
      database_id: &str,
      name: &str,
      field_type: &str,
    ) -> String {
      let response = helpers::gql(
        app,
        session_id,
        json!({
          "query": r#"
          mutation CreateField($input: CreateDatabaseFieldInput!) {
            createDatabaseField(input: $input) { id fieldType config { kind } }
          }
        "#,
          "variables": {
            "input": {
              "databaseId": database_id,
              "name": name,
              "fieldType": field_type
            }
          }
        }),
      )
      .await;
      let field = gql_data(&response, &["createDatabaseField"]);
      assert_eq!(field["fieldType"], field_type);
      field["id"].as_str().expect("field id").to_string()
    }

    let url_field_id = create_field(&app, owner_session, database_id, "Website", "Url").await;
    let email_field_id = create_field(&app, owner_session, database_id, "Email", "Email").await;
    let phone_field_id = create_field(&app, owner_session, database_id, "Phone", "Phone").await;
    let created_time_field_id = create_field(&app, owner_session, database_id, "Created", "CreatedTime").await;
    let created_by_field_id = create_field(&app, owner_session, database_id, "Creator", "CreatedBy").await;
    let updated_time_field_id = create_field(&app, owner_session, database_id, "Updated", "UpdatedTime").await;
    let updated_by_field_id = create_field(&app, owner_session, database_id, "Updater", "UpdatedBy").await;
    let visible_field_ids = vec![
      title_field_id.clone(),
      url_field_id.clone(),
      email_field_id.clone(),
      phone_field_id.clone(),
      created_time_field_id.clone(),
      created_by_field_id.clone(),
      updated_time_field_id.clone(),
      updated_by_field_id.clone(),
    ];

    let updated_view = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateView($input: UpdateDatabaseViewInput!) {
          updateDatabaseView(input: $input) {
            config { table { visibleFieldIds } }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "viewId": table_view_id,
            "config": {
              "table": {
                "titleFieldId": title_field_id,
                "visibleFieldIds": visible_field_ids,
                "fieldWidths": [],
                "sort": [],
                "filter": []
              }
            }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      gql_data(&updated_view, &["updateDatabaseView"])["config"]["table"]["visibleFieldIds"]
        .as_array()
        .expect("visible field ids")
        .len(),
      visible_field_ids.len()
    );

    let created_row = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateRow($input: CreateDatabaseRowInput!) {
          createDatabaseRow(input: $input) {
            row { id createdBy updatedBy }
            cells {
              fieldId
              fieldType
              value { kind url email phone createdTime createdBy updatedTime updatedBy }
            }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "title": "Property row",
            "cells": [
              { "fieldId": url_field_id, "value": { "url": "example.test/path" } },
              { "fieldId": email_field_id, "value": { "email": "Owner@Example.TEST" } },
              { "fieldId": phone_field_id, "value": { "phone": "+49 (30) 123-456" } }
            ]
          }
        }
      }),
    )
    .await;
    let row = gql_data(&created_row, &["createDatabaseRow"]);
    let row_id = row["row"]["id"].as_str().expect("row id");
    let cells = row["cells"].as_array().expect("row cells");
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == url_field_id && cell["value"]["url"] == "https://example.test/path")
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == email_field_id && cell["value"]["email"] == "Owner@example.test")
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == phone_field_id && cell["value"]["phone"] == "+49 (30) 123-456")
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == created_time_field_id && cell["value"]["createdTime"].is_string())
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == created_by_field_id && cell["value"]["createdBy"] == owner_id.to_string())
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == updated_time_field_id && cell["value"]["updatedTime"].is_string())
    );
    assert!(
      cells
        .iter()
        .any(|cell| cell["fieldId"] == updated_by_field_id && cell["value"]["updatedBy"] == owner_id.to_string())
    );

    let rejected_projection_write = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation UpdateCell($input: UpdateDatabaseCellValueInput!) {
          updateDatabaseCellValue(input: $input) { fieldId }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_id,
            "fieldId": created_time_field_id,
            "value": { "text": "not editable" }
          }
        }
      }),
    )
    .await;
    assert_eq!(
      rejected_projection_write["errors"][0]["extensions"]["code"],
      "MIX_DATABASE_CELL_VALUE_READONLY"
    );

    let cell_values_table = ["workspace", "database", "cell", "values"].join("_");
    let projection_storage_count: i64 = sqlx::query_scalar(&format!(
      "SELECT COUNT(*)::BIGINT FROM {cell_values_table} WHERE field_id = ANY($1)"
    ))
    .bind(vec![
      uuid::Uuid::parse_str(&created_time_field_id).expect("created time field uuid"),
      uuid::Uuid::parse_str(&created_by_field_id).expect("created by field uuid"),
      uuid::Uuid::parse_str(&updated_time_field_id).expect("updated time field uuid"),
      uuid::Uuid::parse_str(&updated_by_field_id).expect("updated by field uuid"),
    ])
    .fetch_one(&pool)
    .await
    .expect("projection cell storage count");
    assert_eq!(
      projection_storage_count, 0,
      "projection cells must not be stored as editable cell values"
    );

    let exported = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query Export($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseCsvExport(databaseId: $databaseId) { content }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let csv = gql_data(&exported, &["workspace"])["databaseCsvExport"]["content"]
      .as_str()
      .expect("csv content");
    for expected in ["Website", "Email", "Phone", "Created", "Creator", "Updated", "Updater"] {
      assert!(csv.contains(expected), "P9I CSV export must include {expected}: {csv}");
    }

    let import = gql_csv_upload(
    &app,
    owner_session,
    json!({
      "query": r#"
        mutation ImportDatabaseCsv($file: Upload!, $input: ImportDatabaseCsvInput!) {
          importDatabaseCsv(file: $file, input: $input) {
            database { fields { name fieldType } rowCount }
            errors { code message field }
            warnings { code message field }
          }
        }
      "#,
      "variables": {
        "file": null,
        "input": {
          "workspaceId": workspace_id.to_string(),
          "databaseTitle": "P9I Imported"
        }
      }
    }),
    "p9i.csv",
    b"Name,Website,Email,Phone,created_time,updated_by\r\nOne,example.test,Owner@Example.TEST,+49 30 12345678,2026-07-01T12:00:00Z,user-1\r\n",
  )
  .await;
    let imported = gql_data(&import, &["importDatabaseCsv"]);
    assert_eq!(imported["errors"].as_array().expect("import errors").len(), 0);
    assert_eq!(imported["database"]["rowCount"], 1);
    let warnings = imported["warnings"].as_array().expect("import warnings");
    assert!(
      warnings
        .iter()
        .filter(|warning| warning["code"] == "MIX_DATABASE_CELL_VALUE_READONLY")
        .count()
        >= 2,
      "projection import columns must be ignored with structured readonly warnings: {warnings:#?}"
    );
    let fields = imported["database"]["fields"].as_array().expect("imported fields");
    for field_type in ["Url", "Email", "Phone", "CreatedTime", "UpdatedBy"] {
      assert!(
        fields.iter().any(|field| field["fieldType"] == field_type),
        "CSV import must infer P9I field type {field_type}: {fields:#?}"
      );
    }

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

#[test]
fn database_graphql_row_position_update_keeps_dense_order() {
  helpers::block_on_large_stack("workspace-db-row-position", || async {
    let (app, pool, auth_store) = helpers::setup_app().await;
    let (owner_id, owner_session) = helpers::seed_user(&pool, &auth_store, "workspace-db-row-position").await;
    let workspace_id = helpers::create_workspace(&pool, owner_id).await;

    let created = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation CreateDatabase($input: CreateDatabaseInput!) {
          createDatabase(input: $input) {
            database { id }
          }
        }
      "#,
        "variables": {
          "input": {
            "workspaceId": workspace_id.to_string(),
            "title": "Kanban Position Contract",
            "initialViewKind": "Table"
          }
        }
      }),
    )
    .await;
    let database_id = gql_data(&created, &["createDatabase"])["database"]["id"]
      .as_str()
      .expect("database id");

    let mut row_ids = Vec::new();
    for title in ["First", "Second", "Third"] {
      let created_row = helpers::gql(
        &app,
        owner_session,
        json!({
          "query": r#"
          mutation CreateRow($input: CreateDatabaseRowInput!) {
            createDatabaseRow(input: $input) {
              row { id title position }
            }
          }
        "#,
          "variables": {
            "input": {
              "databaseId": database_id,
              "title": title
            }
          }
        }),
      )
      .await;
      row_ids.push(
        gql_data(&created_row, &["createDatabaseRow"])["row"]["id"]
          .as_str()
          .expect("row id")
          .to_string(),
      );
    }

    let moved = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        mutation MoveRow($input: UpdateDatabaseRowPositionInput!) {
          updateDatabaseRowPosition(input: $input) {
            row { id title position }
          }
        }
      "#,
        "variables": {
          "input": {
            "databaseId": database_id,
            "rowId": row_ids[2],
            "position": 0
          }
        }
      }),
    )
    .await;
    let moved_row = &gql_data(&moved, &["updateDatabaseRowPosition"])["row"];
    assert_eq!(moved_row["title"], "Third");
    assert_eq!(moved_row["position"], 0);

    let listed = helpers::gql(
      &app,
      owner_session,
      json!({
        "query": r#"
        query Rows($workspaceId: String!, $databaseId: ID!) {
          workspace(id: $workspaceId) {
            databaseRows(databaseId: $databaseId) {
              rows { row { title position } }
            }
          }
        }
      "#,
        "variables": {
          "workspaceId": workspace_id.to_string(),
          "databaseId": database_id
        }
      }),
    )
    .await;
    let rows = gql_data(&listed, &["workspace"])["databaseRows"]["rows"]
      .as_array()
      .expect("rows");
    let ordered = rows
      .iter()
      .map(|row| {
        (
          row["row"]["title"].as_str().expect("row title"),
          row["row"]["position"].as_i64().expect("row position"),
        )
      })
      .collect::<Vec<_>>();
    assert_eq!(ordered, vec![("Third", 0), ("First", 1), ("Second", 2)]);

    helpers::cleanup_users(&pool, &[owner_id]).await;
  });
}

